TEST(AttachmentFeedbackLoopPipeline, DeclaresTheDynamicStateExactlyWhenSupported) {
    const auto enabled = PlanAttachmentFeedbackLoopPipeline(true);
    EXPECT_TRUE(enabled.declare_dynamic_state);
    EXPECT_FALSE(enabled.declare_static_color_feedback);

    const auto disabled = PlanAttachmentFeedbackLoopPipeline(false);
    EXPECT_FALSE(disabled.declare_dynamic_state);
    EXPECT_FALSE(disabled.declare_static_color_feedback);
}

TEST(AttachmentFeedbackLoopAccess, PreservesEverySimultaneousImageUseOnBothPaths) {
    constexpr auto expected = vk::AccessFlagBits2::eShaderRead |
                              vk::AccessFlagBits2::eColorAttachmentRead |
                              vk::AccessFlagBits2::eColorAttachmentWrite;
    EXPECT_EQ(AttachmentFeedbackLoopAccess(), expected);
    EXPECT_EQ(AttachmentFeedbackLoopTextureAccess(), expected);
    EXPECT_EQ(AttachmentFeedbackLoopRenderTargetAccess(), expected);

}

TEST(DepthAttachmentClear, RequiresEnabledWritableDepthOrExistingMetadata) {
    EXPECT_TRUE(Vulkan::ShouldClearDepthAttachment(true, true, true, false));
    EXPECT_FALSE(Vulkan::ShouldClearDepthAttachment(true, false, true, false));
    EXPECT_FALSE(Vulkan::ShouldClearDepthAttachment(true, true, false, false));
    EXPECT_FALSE(Vulkan::ShouldClearDepthAttachment(true, false, false, false));
    EXPECT_FALSE(Vulkan::ShouldClearDepthAttachment(false, true, true, false));

    EXPECT_TRUE(Vulkan::ShouldClearDepthAttachment(false, false, false, true));
    EXPECT_TRUE(Vulkan::ShouldClearDepthAttachment(true, false, false, true));
}

TEST(ImageAccess, TreatsAttachmentWritesAsWriteHazards) {
    EXPECT_TRUE(VideoCore::IsImageWriteAccess(vk::AccessFlagBits2::eTransferWrite));
    EXPECT_TRUE(VideoCore::IsImageWriteAccess(vk::AccessFlagBits2::eShaderWrite));
    EXPECT_TRUE(VideoCore::IsImageWriteAccess(vk::AccessFlagBits2::eColorAttachmentWrite));
    EXPECT_TRUE(VideoCore::IsImageWriteAccess(vk::AccessFlagBits2::eDepthStencilAttachmentWrite));
    EXPECT_TRUE(VideoCore::IsImageWriteAccess(vk::AccessFlagBits2::eMemoryWrite));
    EXPECT_TRUE(VideoCore::IsImageWriteAccess(vk::AccessFlagBits2::eColorAttachmentRead |
                                              vk::AccessFlagBits2::eColorAttachmentWrite));

    EXPECT_FALSE(VideoCore::IsImageWriteAccess(vk::AccessFlagBits2::eTransferRead));
    EXPECT_FALSE(VideoCore::IsImageWriteAccess(vk::AccessFlagBits2::eShaderRead));
    EXPECT_FALSE(VideoCore::IsImageWriteAccess(vk::AccessFlagBits2::eColorAttachmentRead));
    EXPECT_FALSE(VideoCore::IsImageWriteAccess(vk::AccessFlagBits2::eDepthStencilAttachmentRead));
    EXPECT_FALSE(VideoCore::IsImageWriteAccess(vk::AccessFlagBits2::eMemoryRead));
}

TEST(StencilReference, UsesOperationValueForEveryReplaceOpPath) {
    constexpr AmdGpu::StencilRefMask ref{
        .stencil_test_val = 0x12,
        .stencil_mask = 0xff,
        .stencil_write_mask = 0xff,
        .stencil_op_val = 0x34,
    };
    const auto plan = [&](AmdGpu::StencilFunc fail, AmdGpu::StencilFunc pass,
                          AmdGpu::StencilFunc depth_fail,
                          AmdGpu::CompareFunc compare = AmdGpu::CompareFunc::Always) {
        return Vulkan::PlanStencilReference(fail, pass, depth_fail, compare, ref);
    };

    const auto keep = plan(AmdGpu::StencilFunc::Keep, AmdGpu::StencilFunc::Keep,
                           AmdGpu::StencilFunc::Keep);
    EXPECT_EQ(keep.reference, ref.stencil_test_val);
    EXPECT_FALSE(keep.uses_operation_value);
    EXPECT_FALSE(keep.compare_conflict);

    for (const auto replace_path : {0, 1, 2}) {
        auto fail = AmdGpu::StencilFunc::Keep;
        auto pass = AmdGpu::StencilFunc::Keep;
        auto depth_fail = AmdGpu::StencilFunc::Keep;
        (replace_path == 0 ? fail : replace_path == 1 ? pass : depth_fail) =
            AmdGpu::StencilFunc::ReplaceOp;
        const auto replace = plan(fail, pass, depth_fail);
        EXPECT_EQ(replace.reference, ref.stencil_op_val);
        EXPECT_TRUE(replace.uses_operation_value);
        EXPECT_FALSE(replace.compare_conflict);
    }

    EXPECT_EQ(plan(AmdGpu::StencilFunc::ReplaceTest, AmdGpu::StencilFunc::Keep,
                   AmdGpu::StencilFunc::Keep)
                  .reference,
              ref.stencil_test_val);
    EXPECT_TRUE(plan(AmdGpu::StencilFunc::Keep, AmdGpu::StencilFunc::ReplaceOp,
                     AmdGpu::StencilFunc::Keep, AmdGpu::CompareFunc::Equal)
                    .compare_conflict);
    EXPECT_FALSE(plan(AmdGpu::StencilFunc::Keep, AmdGpu::StencilFunc::ReplaceOp,
                      AmdGpu::StencilFunc::Keep, AmdGpu::CompareFunc::Never)
                     .compare_conflict);
}

TEST(RuntimeInfo, ShaderPermutationEqualityIncludesEveryCompilationInput) {
    Shader::RuntimeInfo compute{};
    compute.Initialize(Shader::Stage::Compute);
    compute.num_user_data = 8;
    compute.num_input_vgprs = 2;
    compute.num_allocated_vgprs = 16;
    compute.fp_denorm_mode32 = AmdGpu::FpDenormMode::InOutFlush;
    compute.fp_denorm_mode16_64 = AmdGpu::FpDenormMode::InOutAllow;
    compute.fp_round_mode32 = AmdGpu::FpRoundMode::NearestEven;
    compute.fp_round_mode16_64 = AmdGpu::FpRoundMode::ToZero;
    compute.cs_info.shared_memory_size = 256;
    compute.cs_info.workgroup_size = {64, 1, 1};
    compute.cs_info.tgid_enable = {true, false, false};

    const auto expect_distinct = [&](auto mutate) {
        auto other = compute;
        mutate(other);
        EXPECT_NE(compute, other);
    };

    EXPECT_EQ(compute, compute);
    expect_distinct([](auto& info) { info.stage = Shader::Stage::Fragment; });
    expect_distinct([](auto& info) { ++info.num_user_data; });
    expect_distinct([](auto& info) { ++info.num_input_vgprs; });
    expect_distinct([](auto& info) { ++info.num_allocated_vgprs; });
    expect_distinct(
        [](auto& info) { info.fp_denorm_mode32 = AmdGpu::FpDenormMode::InOutAllow; });
    expect_distinct(
        [](auto& info) { info.fp_denorm_mode16_64 = AmdGpu::FpDenormMode::InOutFlush; });
    expect_distinct([](auto& info) { info.fp_round_mode32 = AmdGpu::FpRoundMode::ToZero; });
    expect_distinct(
        [](auto& info) { info.fp_round_mode16_64 = AmdGpu::FpRoundMode::NearestEven; });
    expect_distinct([](auto& info) { ++info.cs_info.shared_memory_size; });
    expect_distinct([](auto& info) { info.cs_info.workgroup_size[0] = 32; });
    expect_distinct([](auto& info) { info.cs_info.tgid_enable[1] = true; });

    Shader::RuntimeInfo geometry_a{};
    geometry_a.Initialize(Shader::Stage::Geometry);
    geometry_a.gs_info.num_invocations = 1;
    geometry_a.gs_info.output_vertices = 3;
    auto geometry_b = geometry_a;
    EXPECT_EQ(geometry_a, geometry_b);
    geometry_b.gs_info.num_invocations = 2;
    EXPECT_NE(geometry_a, geometry_b);
    geometry_b = geometry_a;
    ++geometry_b.gs_info.in_vertex_data_size;
    EXPECT_NE(geometry_a, geometry_b);
    geometry_b = geometry_a;
    ++geometry_b.gs_info.out_vertex_data_size;
    EXPECT_NE(geometry_a, geometry_b);
    geometry_b = geometry_a;
    geometry_b.gs_info.mode = static_cast<AmdGpu::GsScenario>(1);
    EXPECT_NE(geometry_a, geometry_b);
}

TEST(StageSpecialization, DescriptorPresenceParticipatesInPermutationEquality) {
    Shader::Info info{};
    Shader::StageSpecialization bound{};
    bound.info = &info;
    bound.runtime_info.Initialize(Shader::Stage::Fragment);
    bound.buffers.emplace_back();
    bound.bitset.set(0);

    auto missing = bound;
    missing.bitset.reset(0);
    EXPECT_NE(bound, missing);
    EXPECT_NE(missing, bound);

    auto same = bound;
    EXPECT_EQ(bound, same);
    same.buffers[0].stride = 4;
    EXPECT_NE(bound, same);
}

TEST(StageSpecialization, FetchProgramParticipatesEvenWithoutOrdinaryResources) {
    Shader::Info info{};
    Shader::StageSpecialization first{};
    first.info = &info;
    first.runtime_info.Initialize(Shader::Stage::Vertex);
    first.fetch_shader_data.emplace();
    first.fetch_shader_data->size = 16;
    first.fetch_shader_data->vertex_offset_sgpr = 2;

    auto second = first;
    second.fetch_shader_data->vertex_offset_sgpr = 4;

    ASSERT_TRUE(first.bitset.none());
    ASSERT_TRUE(second.bitset.none());
    EXPECT_NE(first, second);
    EXPECT_NE(second, first);

}

TEST(VertexAttribute, EveryInstructionFieldThatChangesTheFetchedValueParticipatesInEquality) {
    Shader::Gcn::VertexAttribute first{
        .semantic = 1,
        .dest_vgpr = 2,
        .num_elements = 3,
        .sgpr_base = 4,
        .dword_offset = 5,
        .instance_data = 0,
        .inst_offset = 6,
        .data_format = 7,
        .num_format = 8,
    };
    const auto expect_distinct = [&](auto mutate) {
        auto second = first;
        mutate(second);
        EXPECT_NE(first, second);
        EXPECT_NE(second, first);
    };
    expect_distinct([](auto& value) { ++value.inst_offset; });
    expect_distinct([](auto& value) { ++value.data_format; });
    expect_distinct([](auto& value) { ++value.num_format; });
}

TEST(VertexInputDynamicState,
     RebindsTheExactLayoutAndBuffersAfterDiagnosticPreDrawBeforeEitherDraw) {
    std::ifstream stream{PP_UPSTREAM_SAMPLE_TEE_RASTERIZER_SOURCE_PATH, std::ios::binary};
    ASSERT_TRUE(stream.good());
    const std::string source{std::istreambuf_iterator<char>{stream},
                             std::istreambuf_iterator<char>{}};
    const auto draw = source.find("void Rasterizer::Draw(bool is_indexed, u32 index_offset)");
    const auto draw_end = source.find("void Rasterizer::DrawIndirect(", draw);
    ASSERT_NE(draw, std::string::npos);
    ASSERT_NE(draw_end, std::string::npos);
    const auto body = source.substr(draw, draw_end - draw);
    const auto pre_draw = body.find("CapturePpTerminalScopePreDraw(");
    const auto reemit = body.find("buffer_cache.BindVertexBuffers(", pre_draw);
    const auto indexed = body.find("cmdbuf.drawIndexed(", pre_draw);
    const auto direct = body.find("cmdbuf.draw(", pre_draw);
    ASSERT_NE(pre_draw, std::string::npos);
    ASSERT_NE(reemit, std::string::npos);
    ASSERT_NE(indexed, std::string::npos);
    ASSERT_NE(direct, std::string::npos);
    EXPECT_LT(pre_draw, reemit);
    EXPECT_LT(reemit, indexed);
    EXPECT_LT(reemit, direct);
    const auto call_end = body.find(");", reemit);
    ASSERT_NE(call_end, std::string::npos);
    const auto call = body.substr(reemit, call_end - reemit);
    EXPECT_NE(call.find("*pipeline"), std::string::npos);
    EXPECT_NE(call.find("pipeline_result.vertex_inputs"), std::string::npos);
    EXPECT_NE(call.find("post_capture_vertex_barriers"), std::string::npos);
}

TEST(AttachmentFeedbackLoopRuntime, UsesTheContractsAtAllThreeBehaviorSeams) {
    const auto read = [](const char* path) {
        std::ifstream stream{path, std::ios::binary};
        EXPECT_TRUE(stream.is_open());
        return std::string{std::istreambuf_iterator<char>{stream},
                           std::istreambuf_iterator<char>{}};
    };
    const std::string pipeline = read(PP_GRAPHICS_PIPELINE_SOURCE_PATH);
    const std::string rasterizer = read(PP_UPSTREAM_SAMPLE_TEE_RASTERIZER_SOURCE_PATH);
    const std::string image = read(PP_IMAGE_SOURCE_PATH);

    EXPECT_NE(pipeline.find("vk::DynamicState::eAttachmentFeedbackLoopEnableEXT"),
              std::string::npos);
    EXPECT_NE(pipeline.find("PlanAttachmentFeedbackLoopPipeline("), std::string::npos);
    EXPECT_NE(rasterizer.find("AttachmentFeedbackLoopTextureAccess()"), std::string::npos);
    EXPECT_NE(rasterizer.find("AttachmentFeedbackLoopRenderTargetAccess()"), std::string::npos);
    EXPECT_NE(rasterizer.find("ShouldClearDepthAttachment("), std::string::npos);
    EXPECT_EQ(image.find("constexpr auto write_flags ="), std::string::npos);
    EXPECT_EQ(std::count(image.begin(), image.end(), '\0'), 0);
    EXPECT_GE(std::count(image.begin(), image.end(), 'I'), 2);
    EXPECT_NE(image.find("IsImageWriteAccess(state.access_mask)"), std::string::npos);
    EXPECT_NE(image.find("IsImageWriteAccess(last_state.access_mask)"), std::string::npos);
}

TEST(PpSourcePublication, ImageRefreshBranchesExposeTheirActualMutationOutcome) {
    const auto clean = VideoCore::PlanImageRefreshStart(false, 1);
    EXPECT_FALSE(clean.refresh);
    EXPECT_EQ(clean.result, VideoCore::ImageRefreshResult::Clean);

    const auto multisampled = VideoCore::PlanImageRefreshStart(true, 4);
    EXPECT_FALSE(multisampled.refresh);
    EXPECT_EQ(multisampled.result, VideoCore::ImageRefreshResult::MultisampledDirty);

    const auto dirty = VideoCore::PlanImageRefreshStart(true, 1);
    EXPECT_TRUE(dirty.refresh);
    EXPECT_EQ(VideoCore::CompleteImageRefresh(true),
              VideoCore::ImageRefreshResult::GpuModifiedUnchanged);
    EXPECT_EQ(VideoCore::CompleteImageRefresh(false), VideoCore::ImageRefreshResult::Uploaded);
}

TEST(PpSourcePublication, ClassifiesWhetherFlipRefreshMutatedTheSource) {
    EXPECT_EQ(ClassifyPpSourcePublication(
                  {.refresh = VideoCore::ImageRefreshResult::Clean, .gpu_modified_before = true}),
              PpSourcePublicationClass::CleanGpuTracked);
    EXPECT_EQ(ClassifyPpSourcePublication(
                  {.refresh = VideoCore::ImageRefreshResult::Clean, .gpu_modified_before = false}),
              PpSourcePublicationClass::CleanResident);
    EXPECT_EQ(ClassifyPpSourcePublication(
                  {.refresh = VideoCore::ImageRefreshResult::MaybeCpuDirtyUnchanged,
                   .gpu_modified_before = true}),
              PpSourcePublicationClass::DirtyNoUpload);
    EXPECT_EQ(
        ClassifyPpSourcePublication({.refresh = VideoCore::ImageRefreshResult::GpuModifiedUnchanged,
                                     .gpu_modified_before = true}),
        PpSourcePublicationClass::DirtyNoUpload);
    EXPECT_EQ(ClassifyPpSourcePublication({.refresh = VideoCore::ImageRefreshResult::Uploaded,
                                           .gpu_modified_before = true}),
              PpSourcePublicationClass::CpuUpload);
    EXPECT_EQ(
        ClassifyPpSourcePublication({.refresh = VideoCore::ImageRefreshResult::MultisampledDirty,
                                     .gpu_modified_before = true}),
        PpSourcePublicationClass::Unsupported);
}

TEST(PpSourcePublication, ReportsEverySelectedSequenceExactlyOnce) {
    PpSourcePublicationCoverage coverage{{.start = 4000, .count = 4}};
    const auto first = coverage.Observe(3999, PpSourcePublicationClass::CleanResident);
    EXPECT_FALSE(first.has_value());

    ASSERT_TRUE(coverage.Observe(4000, PpSourcePublicationClass::CleanGpuTracked));
    ASSERT_TRUE(coverage.Observe(4001, PpSourcePublicationClass::CleanGpuTracked));
    ASSERT_TRUE(coverage.Observe(4002, PpSourcePublicationClass::DirtyNoUpload));
    const auto final = coverage.Observe(4003, PpSourcePublicationClass::CpuUpload);
    ASSERT_TRUE(final);
    EXPECT_TRUE(final->final);
    EXPECT_EQ(final->sequence, 4003u);
    EXPECT_EQ(final->selected, 4u);
    EXPECT_EQ(final->emitted, 4u);
    EXPECT_EQ(final->clean_gpu_tracked, 2u);
    EXPECT_EQ(final->clean_resident, 0u);
    EXPECT_EQ(final->dirty_no_upload, 1u);
    EXPECT_EQ(final->cpu_upload, 1u);
    EXPECT_EQ(final->unsupported, 0u);
    EXPECT_EQ(final->loss, 0u);
}

TEST(PpSourcePublication, GapsAndDuplicatesFailClosed) {
    PpSourcePublicationCoverage coverage{{.start = 10, .count = 3}};
    ASSERT_TRUE(coverage.Observe(10, PpSourcePublicationClass::CleanGpuTracked));
    ASSERT_TRUE(coverage.Observe(10, PpSourcePublicationClass::CleanGpuTracked));
    const auto final = coverage.Observe(12, PpSourcePublicationClass::Unsupported);
    ASSERT_TRUE(final);
    EXPECT_EQ(final->selected, 3u);
    EXPECT_EQ(final->emitted, 3u);
    EXPECT_EQ(final->unsupported, 1u);
    EXPECT_EQ(final->loss, 2u);
}

TEST(PpSourcePublication, MissingWindowPrefixFailsFinalCoverage) {
    PpSourcePublicationCoverage coverage{{.start = 10, .count = 3}};
    ASSERT_TRUE(coverage.Observe(11, PpSourcePublicationClass::CleanGpuTracked));
    const auto final = coverage.Observe(12, PpSourcePublicationClass::CleanGpuTracked);
    ASSERT_TRUE(final);
    EXPECT_TRUE(final->final);
    EXPECT_EQ(final->expected, 3u);
    EXPECT_EQ(final->selected, 2u);
    EXPECT_EQ(final->emitted, 2u);
    EXPECT_EQ(final->loss, 1u);
}

TEST(PpSourcePublication, CompactOutputContainsOnlySequenceClassAndCounts) {
    const auto line = FormatPpSourcePublicationObservation(
        {.sequence = 4579, .classification = PpSourcePublicationClass::CleanGpuTracked});
    EXPECT_EQ(line, "FGSCP s=4579 r=0");

    PpSourcePublicationCoverage coverage{{.start = 1, .count = 1}};
    const auto final = coverage.Observe(1, PpSourcePublicationClass::CleanResident);
    ASSERT_TRUE(final);
    const auto coverage_line = FormatPpSourcePublicationCoverage(*final);
    EXPECT_EQ(coverage_line, "FGSCPC s=1 n=1/1/1 g=0 r=1 d=0 u=0 x=0 l=0");
    EXPECT_LT(line.size(), size_t{40});
    EXPECT_LT(coverage_line.size(), size_t{100});
}

TEST(PpSourceProducer, RecordsOnlySuccessfullyEncodedWriterClasses) {
    VideoCore::ImageProducerState state;
    EXPECT_EQ(state.Epoch(), 0u);
    EXPECT_EQ(state.MutationEpoch(), 0u);
    EXPECT_EQ(state.Observe(), (VideoCore::ImageProducerObservation{
                                   .classification = VideoCore::ImageProducerClass::Unknown,
                                   .produced_since_last_observation = false,
                               }));

    state.Mark(VideoCore::ImageProducerClass::ColorAttachment);
    EXPECT_EQ(state.Epoch(), 1u);
    EXPECT_EQ(state.MutationEpoch(), 1u);
    EXPECT_EQ(state.Observe(), (VideoCore::ImageProducerObservation{
                                   .classification = VideoCore::ImageProducerClass::ColorAttachment,
                                   .produced_since_last_observation = true,
                               }));
    EXPECT_EQ(state.Observe(), (VideoCore::ImageProducerObservation{
                                   .classification = VideoCore::ImageProducerClass::ColorAttachment,
                                   .produced_since_last_observation = false,
                               }));

    state.Mark(VideoCore::ImageProducerClass::StorageImage);
    state.Mark(VideoCore::ImageProducerClass::Transfer);
    EXPECT_EQ(state.Epoch(), 3u);
    EXPECT_EQ(state.MutationEpoch(), 3u);
    EXPECT_EQ(state.Observe(), (VideoCore::ImageProducerObservation{
                                   .classification = VideoCore::ImageProducerClass::Transfer,
                                   .produced_since_last_observation = true,
                               }));
}

TEST(PpSourceProducer, ResetAndGenerationChangesFailClosed) {
    VideoCore::ImageProducerState state;
    state.Mark(VideoCore::ImageProducerClass::ColorAttachment);
    ASSERT_TRUE(state.Observe().produced_since_last_observation);
    state.Reset();
    EXPECT_EQ(state.Epoch(), 0u);
    EXPECT_EQ(state.MutationEpoch(), 2u);
    EXPECT_EQ(state.Observe(), (VideoCore::ImageProducerObservation{
                                   .classification = VideoCore::ImageProducerClass::Unknown,
                                   .produced_since_last_observation = false,
                               }));
}

TEST(PpSourceProducer, CompactProducerOutputDoesNotExposeImageIdentity) {
    const auto line = FormatPpSourceProducerObservation(
        {.sequence = 4579,
         .producer = {.classification = VideoCore::ImageProducerClass::ColorAttachment,
                      .produced_since_last_observation = true}});
    EXPECT_EQ(line, "FGSCPR s=4579 r=1 n=1");
    EXPECT_LT(line.size(), size_t{40});
}

TEST(PpSourceProducer, CoverageCountsEveryFlipAndSeparatesNewProductionFromReuse) {
    PpSourceProducerCoverage coverage{{.start = 4000, .count = 2}};
    EXPECT_TRUE(
        coverage.Observe(4000, {.classification = VideoCore::ImageProducerClass::ColorAttachment,
                                .produced_since_last_observation = true}));
    const auto final =
        coverage.Observe(4001, {.classification = VideoCore::ImageProducerClass::ColorAttachment,
                                .produced_since_last_observation = false});
    ASSERT_TRUE(final);
    EXPECT_TRUE(final->final);
    EXPECT_EQ(final->expected, 2u);
    EXPECT_EQ(final->selected, 2u);
    EXPECT_EQ(final->emitted, 2u);
    EXPECT_EQ(final->color_attachment, 2u);
    EXPECT_EQ(final->new_production, 1u);
    EXPECT_EQ(final->reused_production, 1u);
    EXPECT_EQ(final->loss, 0u);
    EXPECT_EQ(FormatPpSourceProducerCoverage(*final),
              "FGSCPRC s=4001 n=2/2/2 c=2 s=0 t=0 u=0 x=0 p=1 r=1 l=0");
}

TEST(PpSourceProducerScope, DistinguishesFlipEndedScopeFromAlreadyEndedProducer) {
    EXPECT_EQ(ClassifyPpSourceProducerScope(true), PpSourceProducerScopeClass::ActiveAtFlip);
    EXPECT_EQ(ClassifyPpSourceProducerScope(false), PpSourceProducerScopeClass::EndedEarlier);
}

TEST(PpSourceProducerScope, CoverageIsExactAndPrivacySafe) {
    PpSourceProducerScopeCoverage coverage{{.start = 4000, .count = 2}};
    ASSERT_TRUE(coverage.Observe(4000, PpSourceProducerScopeClass::ActiveAtFlip,
                                 {.draw_count = 3,
                                  .last_draw = VideoCore::ImageColorScopeDrawKind::Direct,
                                  .clear_at_begin = true,
                                  .valid = true}));
    const auto final = coverage.Observe(4001, PpSourceProducerScopeClass::EndedEarlier,
                                        {.draw_count = 2,
                                         .last_draw = VideoCore::ImageColorScopeDrawKind::Indirect,
                                         .valid = true});
    ASSERT_TRUE(final);
    EXPECT_TRUE(final->final);
    EXPECT_EQ(final->active_at_flip, 1u);
    EXPECT_EQ(final->ended_earlier, 1u);
    EXPECT_EQ(final->valid_draw_scopes, 2u);
    EXPECT_EQ(final->invalid_draw_scopes, 0u);
    EXPECT_EQ(final->overflow_draw_scopes, 0u);
    EXPECT_EQ(final->loss, 0u);
    EXPECT_EQ(FormatPpSourceProducerScopeObservation(
                  {.sequence = 4001,
                   .classification = PpSourceProducerScopeClass::EndedEarlier,
                   .draw_scope = {.draw_count = 2,
                                  .last_draw = VideoCore::ImageColorScopeDrawKind::Indirect,
                                  .valid = true}}),
              "FGSCPS s=4001 r=1 d=2 k=2 c=0 x=0 j=0 e=0 n=0 b=0 u=0 w=0 ip=0 in=0 "
              "ia=0 iv=0 sd=0 sk=0 sc=0 sx=0 sj=0 se=0 sn=0 su=0 sw=0 np=0 nn=0 na=0 nv=0");
    EXPECT_EQ(FormatPpSourceProducerScopeCoverage(*final),
              "FGSCPSC s=4001 n=2/2/2 a=1 e=1 v=2 i=0 x=0 s=0 z=0 m=0 w=0 ic=0 "
              "is=0 it=0 iu=0 ix=0 if=0 ir=0 ia=0 il=0 sv=0 si=0 sx=0 sz=0 ss=0 "
              "sm=0 sd=0 sn=0 sc=0 dc=0 ds=0 dt=0 du=0 dx=0 df=0 dr=0 da=0 dl=0 l=0");
}

