    EXPECT_EQ(line.find("address"), std::string::npos);

    const auto shape_loss =
        MakePpTerminalScopeContentReport(4101, FinalGuestSurfaceStatus::GapLoss, {.gap = 1}, 3, 14);
    EXPECT_EQ(shape_loss.draw_count, 3u);
