struct CrossScopeTargetRepeatTestContext {
    PpDepthPredecessorCrossScopePairResult begin{};
    PpDepthPredecessorCrossScopePairResult initial_target_post{};
    PpDepthPredecessorEndpointStamp source{};
    PpDepthPredecessorEndpointStamp latest_target{};
    PpDepthPredecessorCandidateStamp candidate{};
    PpDepthPredecessorCrossScopeArmedP0RepeatProbeSlotStamp slot{};
    FinalGuestSurfaceReadbackSlotPool::Token retained_slot_token{};
};

[[nodiscard]] CrossScopeTargetRepeatTestContext ArmRootBoundTargetRepeat(
    PpDepthPredecessorCrossScopePairLifecycle& lifecycle,
    const CrossScopePairTestHarness& h, u32 raw_occurrences,
    u32 tail_occurrences, u64 source_mutation = 900,
    u32 candidate_index = 1) {
    BeginCrossScopeRootBoundLearning(lifecycle, h, tail_occurrences);
    const auto learning = MakeCrossScopeRootBoundAdmissionInputs(
        h, raw_occurrences, tail_occurrences);
    EXPECT_TRUE(lifecycle
                    .ObserveLearningRootBoundChainComplete(
                        learning.selected, learning.selected_latest,
                        learning.runtime_selection,
                        learning.logical_candidates,
                        learning.transition_candidates)
                    .committed);
    EXPECT_EQ(lifecycle.EndFrame().decision,
              PpDepthPredecessorCrossScopePairDecision::Committed);
    const auto begin = lifecycle.BeginFrame();
    const auto source = h.SourceEndpoint(source_mutation, 130, 600);
    const auto source_candidate =
        h.Candidate(begin.generation, candidate_index, 0x1, source.writer);
    EXPECT_EQ(lifecycle.ObserveSourcePostComplete(source, source_candidate).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    EXPECT_TRUE(lifecycle
                    .ObserveTargetPre(
                        h.Boundary(source, source_mutation, source_candidate))
                    .boundary_exact);
    const auto candidate =
        h.Candidate(begin.generation, candidate_index, 0x3, source.writer);
    EXPECT_TRUE(lifecycle.ObserveTargetPreComplete(candidate).candidate_saved);
    const PpDepthPredecessorEndpointStamp target_post{
        .writer = h.Stamp(h.p0, source_mutation + 1),
        .guest_rendering_serial = 131,
        .host_rendering_instance_id = 602,
        .producer_marked = true,
        .after_diagnostic_resume = true,
        .valid = true,
    };
    const FinalGuestSurfaceReadbackSlotPool::Token retained_slot_token{2, 77};
    const auto initial_target_post = lifecycle.ObserveTargetPost(
        target_post, h.FirstWriterLoad(), retained_slot_token);
    EXPECT_TRUE(initial_target_post.target_first_writer_exact);
    return {
        .begin = begin,
        .initial_target_post = initial_target_post,
        .source = source,
        .latest_target = target_post,
        .candidate = candidate,
        .slot = MakeArmedP0RepeatProbeSlot(begin, candidate_index),
        .retained_slot_token = retained_slot_token,
    };
}

