TEST(PpDepthPredecessorCrossScopePair,
     LearningClassifierRequiresRecordedExactRegularCrossScopeP0Predecessor) {
    const CrossScopePairTestHarness h{};
    const auto source_current = h.SourceEndpoint(20);
    const auto exact = ClassifyPpDepthPredecessorCrossScopeLearningBoundary(
        h.LearningBoundary(source_current, 20));
    EXPECT_TRUE(exact.predecessor_exact);
    EXPECT_TRUE(exact.regular_cross_scope_exact);
    EXPECT_TRUE(exact.load_exact);
    EXPECT_TRUE(exact.exact);

    auto resumed_source = h.LearningBoundary(source_current, 20);
    resumed_source.source_current.after_diagnostic_resume = true;
    EXPECT_TRUE(ClassifyPpDepthPredecessorCrossScopeLearningBoundary(resumed_source).exact)
        << "a real guest writer remains exact when its host scope was created by a diagnostic "
           "resume";

    for (u32 mismatch = 0; mismatch < 30; ++mismatch) {
        auto observation = h.LearningBoundary(source_current, 20);
        switch (mismatch) {
        case 0:
            observation.source_current.valid = false;
            break;
        case 1:
            observation.source_current.producer_marked = false;
            break;
        case 2:
            observation.source_current.writer.hint.valid = false;
            break;
        case 3:
            ++observation.target_intent.link.uid;
            break;
        case 4:
            ++observation.target_intent.range.base.layer;
            break;
        case 5:
            ++observation.target_intent.backing_generation;
            break;
        case 6:
            ++observation.target_intent.mutation_epoch;
            break;
        case 7:
            observation.predecessor.recorded = false;
            break;
        case 8:
            observation.predecessor.depth_stencil_exact = false;
            break;
        case 9:
            observation.predecessor.same_scope = true;
            break;
        case 10:
            observation.source_current.guest_rendering_serial = 0;
            break;
        case 11:
            observation.source_current.guest_rendering_serial =
                std::numeric_limits<u64>::max();
            break;
        case 12:
            observation.source_current.host_rendering_instance_id = 0;
            break;
        case 13:
            observation.target_guest_rendering_serial =
                observation.source_current.guest_rendering_serial;
            break;
        case 14:
            observation.target_guest_rendering_serial =
                observation.source_current.guest_rendering_serial + 2;
            break;
        case 15:
            observation.target_guest_rendering_serial = 0;
            break;
        case 16:
            observation.target_host_rendering_instance_id = 0;
            break;
        case 17:
            observation.target_host_rendering_instance_id =
                observation.source_current.host_rendering_instance_id;
            break;
        case 18:
            observation.source_outside_target_guest_scope = false;
            break;
        case 19:
            observation.target_rendering_active = false;
            break;
        case 20:
            observation.after_begin_rendering = false;
            break;
        case 21:
            observation.target_regular_origin = false;
            break;
        case 22:
            observation.target_after_diagnostic_resume = true;
            break;
        case 23:
            observation.target_depth_load = false;
            break;
        case 24:
            observation.target_depth_clear = true;
            break;
        case 25:
            observation.target_stencil_clear = true;
            break;
        case 26:
            observation.depth_aspect = false;
            break;
        case 27:
            observation.canonical_attachment = false;
            break;
        case 28:
            observation.source_current.writer.valid = false;
            break;
        case 29:
            observation.target_intent.valid = false;
            break;
        default:
            FAIL() << "unhandled learning-boundary mismatch";
        }
        SCOPED_TRACE(mismatch);
        EXPECT_FALSE(
            ClassifyPpDepthPredecessorCrossScopeLearningBoundary(observation).exact);
    }
}

TEST(PpDepthPredecessorCrossScopePair,
     ClassifierRequiresCopyLocalDiagnosticResumeThenExactNextGuestLoadScope) {
    const CrossScopePairTestHarness h{};
    const auto source_post = h.SourceEndpoint(20);
    const auto candidate = h.Candidate(9, 2, 0x1, source_post.writer);
    const auto exact = ClassifyPpDepthPredecessorCrossScopeBoundary(
        h.Boundary(source_post, 20, candidate), 9, 4);
    EXPECT_TRUE(exact.endpoint_exact);
    EXPECT_TRUE(exact.candidate_exact);
    EXPECT_TRUE(exact.resume_exact);
    EXPECT_TRUE(exact.scope_transition_exact);
    EXPECT_TRUE(exact.load_exact);
    EXPECT_TRUE(exact.exact);

    auto resumed_source = h.Boundary(source_post, 20, candidate);
    resumed_source.source_post.after_diagnostic_resume = true;
    EXPECT_TRUE(ClassifyPpDepthPredecessorCrossScopeBoundary(resumed_source, 9, 4).exact)
        << "a source writer already encoded in a resumed host remains distinct from the "
           "copy-local resume and the regular target host";

    for (u32 mismatch = 0; mismatch < 44; ++mismatch) {
        auto observation = h.Boundary(source_post, 20, candidate);
        switch (mismatch) {
        case 0:
            ++observation.target_pre_current_writer.hint.fragment_pgm_hash;
            break;
        case 1:
            ++observation.target_pre_current_writer.link.uid;
            break;
        case 2:
            ++observation.target_pre_current_writer.range.base.layer;
            break;
        case 3:
            ++observation.target_pre_current_writer.backing_generation;
            break;
        case 4:
            ++observation.target_pre_current_writer.mutation_epoch;
            break;
        case 5:
            --observation.candidate.generation;
            break;
        case 6:
            observation.candidate.recorded_plane_mask = 0x3;
            break;
        case 7:
            observation.candidate.candidate_index = 4;
            break;
        case 8:
            ++observation.candidate.writer.mutation_epoch;
            break;
        case 9:
            observation.target_guest_rendering_serial = source_post.guest_rendering_serial;
            break;
        case 10:
            observation.target_guest_rendering_serial = source_post.guest_rendering_serial + 2;
            break;
        case 11:
            observation.target_host_rendering_instance_id =
                observation.resume_host_rendering_instance_id;
            break;
        case 12:
            observation.resume_diagnostic_origin = false;
            break;
        case 13:
            observation.target_regular_origin = false;
            break;
        case 14:
            observation.target_depth_clear = true;
            break;
        case 15:
            observation.canonical_attachment = false;
            break;
        case 16:
            observation.source_post.host_rendering_instance_id = 0;
            break;
        case 17:
            observation.resume_host_rendering_instance_id = 0;
            break;
        case 18:
            observation.resume_host_rendering_instance_id =
                observation.source_post.host_rendering_instance_id;
            break;
        case 19:
            observation.source_post.guest_rendering_serial = 0;
            break;
        case 20:
            observation.resume_guest_rendering_serial = 0;
            break;
        case 21:
            ++observation.resume_guest_rendering_serial;
            break;
        case 22:
            observation.resume_preserved_guest_serial = false;
            break;
        case 23:
            observation.source_post.valid = false;
            break;
        case 24:
            observation.source_post.producer_marked = false;
            break;
        case 25:
            observation.source_post.writer.hint.valid = false;
            break;
        case 26:
            observation.source_outside_target_guest_scope = false;
            break;
        case 27:
            observation.after_begin_rendering = false;
            break;
        case 28:
            observation.target_host_rendering_instance_id = 0;
            break;
        case 29:
            observation.target_guest_rendering_serial = 0;
            break;
        case 30:
            observation.target_after_diagnostic_resume = true;
            break;
        case 31:
            observation.target_depth_load = false;
            break;
        case 32:
            observation.target_stencil_clear = true;
            break;
        case 33:
            observation.depth_aspect = false;
            break;
        case 34:
            observation.candidate.valid = false;
            break;
        case 35:
            ++observation.target_intent.link.uid;
            break;
        case 36:
            ++observation.target_intent.mutation_epoch;
            break;
        case 37:
            observation.source_post.writer.valid = false;
            break;
        case 38:
            ++observation.target_intent.range.base.layer;
            break;
        case 39:
            ++observation.target_intent.backing_generation;
            break;
        case 40:
            observation.target_intent.valid = false;
            break;
        case 41:
            observation.target_host_rendering_instance_id =
                observation.source_post.host_rendering_instance_id;
            break;
        case 42:
            observation.resume_rendering_active = false;
            break;
        case 43:
            observation.target_rendering_active = false;
            break;
        default:
            FAIL() << "unhandled boundary mismatch";
        }
        SCOPED_TRACE(mismatch);
        EXPECT_FALSE(ClassifyPpDepthPredecessorCrossScopeBoundary(observation, 9, 4).exact);
    }

    auto overflow = h.Boundary(
        h.SourceEndpoint(20, std::numeric_limits<u64>::max()), 20, candidate);
    overflow.candidate.writer = overflow.source_post.writer;
    overflow.target_pre_current_writer = overflow.source_post.writer;
    EXPECT_FALSE(ClassifyPpDepthPredecessorCrossScopeBoundary(overflow, 9, 4).exact)
        << "guest serial +1 must be overflow-safe";
}

TEST(PpDepthPredecessorCrossScopePair,
     LearnsOnlyAfterExactMode3ChainAndFirstWriterLoadProof) {
    const CrossScopePairTestHarness h{};
    PpDepthPredecessorCrossScopePairLifecycle lifecycle{4, 7};
    const auto begin = lifecycle.BeginLearningFrame(h.Mode3Begin(3), h.p0, h.p1, h.anchor);
    ASSERT_EQ(begin.role, PpDepthPredecessorCrossScopePairRole::TargetPre);
    const auto source_post = h.SourceEndpoint(10);
    ASSERT_TRUE(lifecycle.ObserveLearningTargetPre(h.LearningBoundary(source_post, 10))
                    .boundary_exact);
    ASSERT_TRUE(lifecycle.ObserveTargetPost(h.Stamp(h.p0, 11), h.FirstWriterLoad())
                    .target_first_writer_exact);
    auto selected_mode3 = h.Mode3Selected(3);
    selected_mode3.candidate_index = 3;
    const auto committed = lifecycle.ObserveLearningChainComplete(selected_mode3);
    EXPECT_TRUE(committed.committed);
    EXPECT_EQ(committed.expected_tail_occurrences, 3u);
    EXPECT_EQ(lifecycle.EndFrame().decision,
              PpDepthPredecessorCrossScopePairDecision::Committed);

    const auto armed = lifecycle.BeginFrame();
    EXPECT_EQ(armed.phase, PpDepthPredecessorCrossScopePairPhase::Armed);
    EXPECT_EQ(armed.role, PpDepthPredecessorCrossScopePairRole::SourcePost);
    EXPECT_EQ(armed.expected_tail_occurrences, 3u);
    EXPECT_FALSE(armed.candidate_saved);
    EXPECT_EQ(armed.candidate_index, 0u)
        << "the mode3 P0 candidate is learning-only and must never seed mode4";
    ASSERT_NE(lifecycle.PeekArmedSourceHint(), nullptr);
    EXPECT_EQ(*lifecycle.PeekArmedSourceHint(), h.source);
    EXPECT_TRUE(lifecycle.MatchesSourcePost(h.source.draw, h.source.fragment_pgm_hash));
    EXPECT_FALSE(lifecycle.MatchesTargetPre(h.p0.draw, h.p0.fragment_pgm_hash));
}

TEST(PpDepthPredecessorCrossScopePair,
     Mode3ProofRequiresExactBeginAndSelectedContinuityBeforePublishingSource) {
    const CrossScopePairTestHarness h{};
    for (u32 mismatch = 0; mismatch < 11; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4};
        auto begin = h.Mode3Begin(2);
        switch (mismatch) {
        case 0:
            begin.phase = PpDepthPredecessorTwoHopPhase::LearnP2;
            break;
        case 1:
            begin.chain_kind = PpDepthPredecessorTwoHopChainKind::Distinct;
            break;
        case 2:
            begin.occurrence_role = PpDepthPredecessorTwoHopOccurrenceRole::RawP2;
            break;
        case 3:
            begin.generation = 0;
            break;
        case 4:
            begin.expected_occurrences = 1;
            break;
        case 5:
            begin.expected_occurrences = std::numeric_limits<u32>::max();
            break;
        case 6:
            begin.identity_collision =
                PpDepthPredecessorTwoHopIdentityCollision::P2EqualsP1;
            break;
        case 7:
            begin.raw_armed = false;
            break;
        case 8:
            begin.decision = PpDepthPredecessorTwoHopDecision::Committed;
            break;
        case 9:
            begin.metadata_only = true;
            break;
        case 10:
            begin.prefix_join_discriminator =
                PpDepthPredecessorPrefixJoinDiscriminator::Exact;
            break;
        default:
            FAIL() << "unhandled mode3 begin mismatch";
        }
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(lifecycle.BeginLearningFrame(begin, h.p0, h.p1, h.anchor).decision,
                  PpDepthPredecessorCrossScopePairDecision::Mode3ProofMismatch);
        EXPECT_NE(lifecycle.EndFrame().decision,
                  PpDepthPredecessorCrossScopePairDecision::Committed);
        EXPECT_EQ(lifecycle.PeekArmedSourceHint(), nullptr);
    }

    for (u32 mismatch = 0; mismatch < 21; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4};
        ASSERT_EQ(lifecycle.BeginLearningFrame(h.Mode3Begin(2), h.p0, h.p1, h.anchor).role,
                  PpDepthPredecessorCrossScopePairRole::TargetPre);
        ASSERT_TRUE(lifecycle
                        .ObserveLearningTargetPre(
                            h.LearningBoundary(h.SourceEndpoint(10), 10))
                        .boundary_exact);
        ASSERT_TRUE(lifecycle.ObserveTargetPost(h.Stamp(h.p0, 11), h.FirstWriterLoad())
                        .target_first_writer_exact);
        auto selected = h.Mode3Selected(2);
        switch (mismatch) {
        case 0:
            selected.phase = PpDepthPredecessorTwoHopPhase::LearnP2;
            break;
        case 1:
            selected.decision = PpDepthPredecessorTwoHopDecision::Committed;
            break;
        case 2:
            selected.chain_kind = PpDepthPredecessorTwoHopChainKind::Distinct;
            break;
        case 3:
            selected.occurrence_role = PpDepthPredecessorTwoHopOccurrenceRole::RawPrefix;
            break;
        case 4:
            ++selected.generation;
            break;
        case 5:
            ++selected.expected_occurrences;
            break;
        case 6:
            --selected.observed_occurrences;
            break;
        case 7:
            selected.raw_occurrences = 2;
            break;
        case 8:
            --selected.bridge_occurrences;
            break;
        case 9:
            selected.identity_collision =
                PpDepthPredecessorTwoHopIdentityCollision::P2EqualsConfiguredAnchor;
            break;
        case 10:
            selected.anchor_exact = false;
            break;
        case 11:
            selected.p1_intent = false;
            break;
        case 12:
            selected.p2_exact = false;
            break;
        case 13:
            selected.p1_post_exact = false;
            break;
        case 14:
            selected.prefix_join_exact = false;
            break;
        case 15:
            selected.candidate_saved = false;
            break;
        case 16:
            selected.select = false;
            break;
        case 17:
            selected.prefix_join_discriminator =
                PpDepthPredecessorPrefixJoinDiscriminator::CandidateMismatch;
            break;
        case 18:
            selected.prefix_join_discriminator =
                PpDepthPredecessorPrefixJoinDiscriminator::NotAttempted;
            break;
        case 19:
            selected.raw_armed = false;
            break;
        case 20:
            selected.metadata_only = true;
            break;
        default:
            FAIL() << "unhandled mode3 selected mismatch";
        }
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(lifecycle.ObserveLearningChainComplete(selected).decision,
                  PpDepthPredecessorCrossScopePairDecision::Mode3ProofMismatch);
        EXPECT_NE(lifecycle.EndFrame().decision,
                  PpDepthPredecessorCrossScopePairDecision::Committed);
        EXPECT_EQ(lifecycle.PeekArmedSourceHint(), nullptr);
    }
}

TEST(PpDepthPredecessorCrossScopePair,
     P0PostRequiresExactNextFullStampAndEveryFirstWriterLoadPredicate) {
    const CrossScopePairTestHarness h{};
    const auto perturb = [&](u32 mismatch, PpDepthPredecessorWriterStamp& post,
                             PpUpstreamDepthFirstWriterClassification& first_writer) {
        switch (mismatch) {
        case 0:
            ++post.hint.fragment_pgm_hash;
            break;
        case 1:
            ++post.link.uid;
            break;
        case 2:
            ++post.range.base.layer;
            break;
        case 3:
            ++post.backing_generation;
            break;
        case 4:
            ++post.mutation_epoch;
            break;
        case 5:
            post.mutation_epoch = 0;
            break;
        case 6:
            first_writer.post_exact = false;
            break;
        case 7:
            first_writer.target_first_depth_writer = false;
            break;
        case 8:
            first_writer.target_scope_load = false;
            break;
        case 9:
            first_writer.target_scope_clear = true;
            break;
        default:
            FAIL() << "unhandled P0-post mismatch";
        }
    };

    for (u32 mismatch = 0; mismatch < 10; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle learning{4};
        ASSERT_EQ(learning.BeginLearningFrame(h.Mode3Begin(), h.p0, h.p1, h.anchor).role,
                  PpDepthPredecessorCrossScopePairRole::TargetPre);
        const u64 pre_mutation =
            mismatch == 5 ? std::numeric_limits<u64>::max() : 10;
        const auto source_current = h.SourceEndpoint(pre_mutation);
        ASSERT_TRUE(learning
                        .ObserveLearningTargetPre(
                            h.LearningBoundary(source_current, pre_mutation))
                        .boundary_exact);
        auto post = h.Stamp(h.p0, mismatch == 5 ? 0 : 11);
        auto first_writer = h.FirstWriterLoad();
        perturb(mismatch, post, first_writer);
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(learning.ObserveTargetPost(post, first_writer).decision,
                  PpDepthPredecessorCrossScopePairDecision::TargetFirstWriterMismatch);
        EXPECT_FALSE(learning.ObserveLearningChainComplete(h.Mode3Selected()).committed);
        EXPECT_NE(learning.EndFrame().decision,
                  PpDepthPredecessorCrossScopePairDecision::Committed);
        EXPECT_EQ(learning.PeekArmedSourceHint(), nullptr)
            << "a failed staged learn must publish no S hint";
    }

    for (u32 mismatch = 0; mismatch < 10; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle armed_lifecycle{4, 20};
        h.Learn(armed_lifecycle);
        const auto frame = armed_lifecycle.BeginFrame();
        const u64 pre_mutation =
            mismatch == 5 ? std::numeric_limits<u64>::max() : 100;
        const auto source_post = h.SourceEndpoint(pre_mutation, 90, 200);
        const auto partial =
            h.Candidate(frame.generation, 1, 0x1, source_post.writer);
        ASSERT_EQ(armed_lifecycle.ObserveSourcePostComplete(source_post, partial).role,
                  PpDepthPredecessorCrossScopePairRole::TargetPre);
        auto boundary = h.Boundary(source_post, pre_mutation, partial);
        boundary.resume_host_rendering_instance_id = 201;
        boundary.target_host_rendering_instance_id = 202;
        ASSERT_TRUE(armed_lifecycle.ObserveTargetPre(boundary).boundary_exact);
        ASSERT_TRUE(armed_lifecycle
                        .ObserveTargetPreComplete(h.Candidate(
                            frame.generation, 1, 0x3, source_post.writer))
                        .candidate_saved);
        auto post = h.Stamp(h.p0, mismatch == 5 ? 0 : 101);
        auto first_writer = h.FirstWriterLoad();
        perturb(mismatch, post, first_writer);
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(armed_lifecycle.ObserveTargetPost(post, first_writer).decision,
                  PpDepthPredecessorCrossScopePairDecision::TargetFirstWriterMismatch);
        EXPECT_FALSE(armed_lifecycle.ObserveAnchor(h.anchor, post).select);
    }
}

TEST(PpDepthPredecessorCrossScopePair,
     ArmedCapturesSourcePostThenTargetPreAndSelectsOnlyAfterExactTailAnchor) {
    const CrossScopePairTestHarness h{};
    PpDepthPredecessorCrossScopePairLifecycle lifecycle{4, 7};
    h.Learn(lifecycle, 2);
    const auto armed = lifecycle.BeginFrame();
    ASSERT_EQ(armed.role, PpDepthPredecessorCrossScopePairRole::SourcePost);

    const auto source_post = h.SourceEndpoint(100, 90, 200);
    const auto source_plane = h.Candidate(armed.generation, 2, 0x1, source_post.writer);
    const auto source_complete = lifecycle.ObserveSourcePostComplete(source_post, source_plane);
    ASSERT_EQ(source_complete.role, PpDepthPredecessorCrossScopePairRole::TargetPre);
    EXPECT_EQ(source_complete.source_post_count, 1u);
    EXPECT_TRUE(lifecycle.MatchesTargetPre(h.p0.draw, h.p0.fragment_pgm_hash));

    auto boundary = h.Boundary(source_post, 100, source_plane);
    boundary.resume_host_rendering_instance_id = 201;
    boundary.target_host_rendering_instance_id = 202;
    const auto target_pre = lifecycle.ObserveTargetPre(boundary);
    ASSERT_TRUE(target_pre.boundary_exact);
    EXPECT_EQ(target_pre.target_pre_count, 1u);
    EXPECT_FALSE(target_pre.candidate_saved)
        << "mask1 is only an open endpoint pair and cannot be selected";

    const auto completed_pair = h.Candidate(armed.generation, 2, 0x3, source_post.writer);
    const auto target_complete = lifecycle.ObserveTargetPreComplete(completed_pair);
    ASSERT_EQ(target_complete.role, PpDepthPredecessorCrossScopePairRole::Tail);
    ASSERT_TRUE(target_complete.candidate_saved);
    ASSERT_TRUE(lifecycle.ObserveTargetPost(h.Stamp(h.p0, 101), h.FirstWriterLoad())
                    .target_first_writer_exact);

    EXPECT_EQ(lifecycle.ObserveAnchor(h.anchor, h.Stamp(h.p0, 101)).decision,
              PpDepthPredecessorCrossScopePairDecision::EarlyAnchor);
    EXPECT_FALSE(lifecycle.EndFrame().select);

    PpDepthPredecessorCrossScopePairLifecycle selected{4, 20};
    h.Learn(selected, 2);
    const auto selected_frame = selected.BeginFrame();
    const auto selected_source = h.SourceEndpoint(200, 100, 300);
    const auto selected_plane =
        h.Candidate(selected_frame.generation, 3, 0x1, selected_source.writer);
    ASSERT_EQ(selected.ObserveSourcePostComplete(selected_source, selected_plane).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    auto selected_boundary = h.Boundary(selected_source, 200, selected_plane);
    selected_boundary.resume_host_rendering_instance_id = 301;
    selected_boundary.target_host_rendering_instance_id = 302;
    ASSERT_TRUE(selected.ObserveTargetPre(selected_boundary).boundary_exact);
    ASSERT_TRUE(selected
                    .ObserveTargetPreComplete(
                        h.Candidate(selected_frame.generation, 3, 0x3,
                                    selected_source.writer))
                    .candidate_saved);
    const auto p0_post = h.Stamp(h.p0, 201);
    ASSERT_TRUE(selected.ObserveTargetPost(p0_post, h.FirstWriterLoad())
                    .target_first_writer_exact);
    ASSERT_TRUE(selected.ObserveTailPre(h.Intent(h.p1, 201), p0_post).tail_exact);
    const auto p1_post1 = h.Stamp(h.p1, 202);
    ASSERT_TRUE(selected.ObserveTailPost(p1_post1).tail_exact);
    ASSERT_TRUE(selected.ObserveTailPre(h.Intent(h.p1, 202), p1_post1).tail_exact);
    const auto p1_post2 = h.Stamp(h.p1, 203);
    ASSERT_TRUE(selected.ObserveTailPost(p1_post2).tail_exact);

    const auto anchor = selected.ObserveAnchor(h.anchor, p1_post2);
    EXPECT_EQ(anchor.decision, PpDepthPredecessorCrossScopePairDecision::Selected);
    EXPECT_TRUE(anchor.select);
    EXPECT_EQ(anchor.candidate_index, 3u);
    EXPECT_EQ(anchor.observed_tail_occurrences, 2u);
    EXPECT_EQ(anchor.source_post_count, 1u);
    EXPECT_EQ(anchor.target_pre_count, 1u);
    EXPECT_TRUE(anchor.candidate_saved);
    EXPECT_EQ(selected.EndFrame().decision,
              PpDepthPredecessorCrossScopePairDecision::Selected);
}

TEST(PpDepthPredecessorCrossScopePair,
     SourcePostRequiresMarkedEndpointAndPartialCandidateBoundToItsFullStamp) {
    const CrossScopePairTestHarness h{};
    for (u32 mismatch = 0; mismatch < 12; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4, 20};
        h.Learn(lifecycle);
        const auto frame = lifecycle.BeginFrame();
        auto endpoint = h.SourceEndpoint(225, 105, 350);
        auto partial = h.Candidate(frame.generation, 1, 0x1, endpoint.writer);
        switch (mismatch) {
        case 0:
            partial.valid = false;
            break;
        case 1:
            ++partial.writer.hint.fragment_pgm_hash;
            break;
        case 2:
            ++partial.writer.link.uid;
            break;
        case 3:
            ++partial.writer.range.base.layer;
            break;
        case 4:
            ++partial.writer.backing_generation;
            break;
        case 5:
            ++partial.writer.mutation_epoch;
            break;
        case 6:
            endpoint.valid = false;
            break;
        case 7:
            endpoint.producer_marked = false;
            break;
        case 8:
            endpoint.guest_rendering_serial = 0;
            break;
        case 9:
            endpoint.host_rendering_instance_id = 0;
            break;
        case 10:
            endpoint.writer.hint.valid = false;
            break;
        case 11:
            endpoint.writer.valid = false;
            break;
        default:
            FAIL() << "unhandled source-post mismatch";
        }
        SCOPED_TRACE(mismatch);
        const auto rejected = lifecycle.ObserveSourcePostComplete(endpoint, partial);
        EXPECT_NE(rejected.decision, PpDepthPredecessorCrossScopePairDecision::Idle);
        EXPECT_FALSE(rejected.candidate_saved);
        EXPECT_FALSE(lifecycle.ObserveAnchor(h.anchor, h.Stamp(h.p1, 226)).select);
    }

    PpDepthPredecessorCrossScopePairLifecycle resumed_lifecycle{4, 20};
    h.Learn(resumed_lifecycle);
    const auto resumed_frame = resumed_lifecycle.BeginFrame();
    auto resumed_endpoint = h.SourceEndpoint(225, 105, 350);
    resumed_endpoint.after_diagnostic_resume = true;
    const auto resumed_partial =
        h.Candidate(resumed_frame.generation, 1, 0x1, resumed_endpoint.writer);
    const auto resumed =
        resumed_lifecycle.ObserveSourcePostComplete(resumed_endpoint, resumed_partial);
    EXPECT_EQ(resumed.decision, PpDepthPredecessorCrossScopePairDecision::Idle);
    EXPECT_EQ(resumed.role, PpDepthPredecessorCrossScopePairRole::TargetPre);
    EXPECT_EQ(resumed.source_post_count, 1u);
    EXPECT_FALSE(resumed.candidate_saved)
        << "the partial source candidate is not selectable before target PRE completes plane1";
}

TEST(PpDepthPredecessorCrossScopePair,
     LifecycleMatchesLearnedP0TargetIntentInLearningAndArmedFrames) {
    const CrossScopePairTestHarness h{};
    PpDepthPredecessorCrossScopePairLifecycle learning{4};
    ASSERT_EQ(learning.BeginLearningFrame(h.Mode3Begin(), h.p0, h.p1, h.anchor).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    auto learning_boundary = h.LearningBoundary(h.SourceEndpoint(10), 10);
    learning_boundary.target_intent.hint = h.p1;
    ASSERT_TRUE(
        ClassifyPpDepthPredecessorCrossScopeLearningBoundary(learning_boundary).exact)
        << "the structural classifier must not substitute for lifecycle P0 identity";
    EXPECT_EQ(learning.ObserveLearningTargetPre(learning_boundary).decision,
              PpDepthPredecessorCrossScopePairDecision::TargetMismatch);
    EXPECT_FALSE(learning.ObserveLearningChainComplete(h.Mode3Selected()).committed);
    EXPECT_NE(learning.EndFrame().decision,
              PpDepthPredecessorCrossScopePairDecision::Committed);
    EXPECT_EQ(learning.PeekArmedSourceHint(), nullptr);

    PpDepthPredecessorCrossScopePairLifecycle armed{4};
    h.Learn(armed);
    const auto frame = armed.BeginFrame();
    const auto endpoint = h.SourceEndpoint(100, 90, 200);
    const auto partial = h.Candidate(frame.generation, 0, 0x1, endpoint.writer);
    ASSERT_EQ(armed.ObserveSourcePostComplete(endpoint, partial).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    auto armed_boundary = h.Boundary(endpoint, 100, partial);
    armed_boundary.resume_host_rendering_instance_id = 201;
    armed_boundary.target_host_rendering_instance_id = 202;
    armed_boundary.target_intent.hint = h.p1;
    ASSERT_TRUE(ClassifyPpDepthPredecessorCrossScopeBoundary(
                    armed_boundary, frame.generation, 4)
                    .exact)
        << "the structural classifier must not substitute for lifecycle P0 identity";
    EXPECT_EQ(armed.ObserveTargetPre(armed_boundary).decision,
              PpDepthPredecessorCrossScopePairDecision::TargetMismatch);
    EXPECT_FALSE(armed.ObserveAnchor(h.anchor, h.Stamp(h.p1, 101)).select);
}

TEST(PpDepthPredecessorCrossScopePair,
     TargetPreRequiresSavedSourceCandidateAndCompletionTransitionsOnlyThatCandidateToMask3) {
    const CrossScopePairTestHarness h{};
    for (u32 mismatch = 0; mismatch < 10; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4, 30};
        h.Learn(lifecycle);
        const auto frame = lifecycle.BeginFrame();
        const auto endpoint = h.SourceEndpoint(250, 110, 400);
        const auto saved = h.Candidate(frame.generation, 1, 0x1, endpoint.writer);
        ASSERT_EQ(lifecycle.ObserveSourcePostComplete(endpoint, saved).role,
                  PpDepthPredecessorCrossScopePairRole::TargetPre);
        auto boundary = h.Boundary(endpoint, 250, saved);
        switch (mismatch) {
        case 0:
            boundary.candidate.valid = false;
            break;
        case 1:
            --boundary.candidate.generation;
            break;
        case 2:
            ++boundary.candidate.candidate_index;
            break;
        case 3:
            boundary.candidate.recorded_plane_mask = 0x3;
            break;
        case 4:
            ++boundary.candidate.writer.hint.fragment_pgm_hash;
            break;
        case 5:
            ++boundary.candidate.writer.link.uid;
            break;
        case 6:
            ++boundary.candidate.writer.range.base.layer;
            break;
        case 7:
            ++boundary.candidate.writer.backing_generation;
            break;
        case 8:
            ++boundary.candidate.writer.mutation_epoch;
            break;
        case 9:
            boundary.candidate.recorded_plane_mask = 0;
            break;
        default:
            FAIL() << "unhandled saved-source drift";
        }
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(lifecycle.ObserveTargetPre(boundary).decision,
                  PpDepthPredecessorCrossScopePairDecision::CandidateMismatch);
        EXPECT_FALSE(lifecycle.ObserveAnchor(h.anchor, h.Stamp(h.p1, 251)).select);
    }

    for (u32 mismatch = 0; mismatch < 10; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4, 50};
        h.Learn(lifecycle);
        const auto frame = lifecycle.BeginFrame();
        const auto endpoint = h.SourceEndpoint(350, 120, 500);
        const auto partial = h.Candidate(frame.generation, 2, 0x1, endpoint.writer);
        ASSERT_EQ(lifecycle.ObserveSourcePostComplete(endpoint, partial).role,
                  PpDepthPredecessorCrossScopePairRole::TargetPre);
        ASSERT_TRUE(lifecycle.ObserveTargetPre(h.Boundary(endpoint, 350, partial))
                        .boundary_exact);
        auto complete = h.Candidate(frame.generation, 2, 0x3, endpoint.writer);
        switch (mismatch) {
        case 0:
            complete.valid = false;
            break;
        case 1:
            --complete.generation;
            break;
        case 2:
            ++complete.candidate_index;
            break;
        case 3:
            complete.recorded_plane_mask = 0x1;
            break;
        case 4:
            ++complete.writer.hint.fragment_pgm_hash;
            break;
        case 5:
            ++complete.writer.link.uid;
            break;
        case 6:
            ++complete.writer.range.base.layer;
            break;
        case 7:
            ++complete.writer.backing_generation;
            break;
        case 8:
            ++complete.writer.mutation_epoch;
            break;
        case 9:
            complete.recorded_plane_mask = 0x2;
            break;
        default:
            FAIL() << "unhandled target-pre completion drift";
        }
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(lifecycle.ObserveTargetPreComplete(complete).decision,
                  PpDepthPredecessorCrossScopePairDecision::CandidateMismatch);
        EXPECT_FALSE(lifecycle.ObserveAnchor(h.anchor, h.Stamp(h.p1, 351)).select);
    }
}

TEST(PpDepthPredecessorCrossScopePair,
     TailRequiresExactLearnedCardinalityFullStampPostsAndUniqueAnchor) {
    const CrossScopePairTestHarness h{};

    PpDepthPredecessorCrossScopePairLifecycle too_few{4};
    h.Learn(too_few, 2);
    h.ArmThroughTargetPost(too_few, 700);
    const auto too_few_p0 = h.Stamp(h.p0, 701);
    ASSERT_TRUE(too_few.ObserveTailPre(h.Intent(h.p1, 701), too_few_p0).tail_exact);
    const auto too_few_p1 = h.Stamp(h.p1, 702);
    ASSERT_TRUE(too_few.ObserveTailPost(too_few_p1).tail_exact);
    EXPECT_EQ(too_few.ObserveAnchor(h.anchor, too_few_p1).decision,
              PpDepthPredecessorCrossScopePairDecision::EarlyAnchor);
    EXPECT_FALSE(too_few.EndFrame().select);

    PpDepthPredecessorCrossScopePairLifecycle too_many{4};
    h.Learn(too_many, 2);
    h.ArmThroughTargetPost(too_many, 710);
    auto prior = h.Stamp(h.p0, 711);
    for (u64 mutation = 711; mutation <= 712; ++mutation) {
        ASSERT_TRUE(too_many.ObserveTailPre(h.Intent(h.p1, mutation), prior).tail_exact);
        prior = h.Stamp(h.p1, mutation + 1);
        ASSERT_TRUE(too_many.ObserveTailPost(prior).tail_exact);
    }
    EXPECT_EQ(too_many.ObserveTailPre(h.Intent(h.p1, 713), prior).decision,
              PpDepthPredecessorCrossScopePairDecision::TailMismatch);
    EXPECT_FALSE(too_many.ObserveAnchor(h.anchor, prior).select);

    PpDepthPredecessorCrossScopePairLifecycle missing_post{4};
    h.Learn(missing_post, 2);
    h.ArmThroughTargetPost(missing_post, 720);
    const auto missing_p0 = h.Stamp(h.p0, 721);
    ASSERT_TRUE(missing_post.ObserveTailPre(h.Intent(h.p1, 721), missing_p0).tail_exact);
    EXPECT_EQ(missing_post.ObserveTailPre(h.Intent(h.p1, 722), h.Stamp(h.p1, 722)).decision,
              PpDepthPredecessorCrossScopePairDecision::MissingTailPost);
    EXPECT_FALSE(missing_post.ObserveAnchor(h.anchor, missing_p0).select);

    PpDepthPredecessorCrossScopePairLifecycle duplicate_post{4};
    h.Learn(duplicate_post, 2);
    h.ArmThroughTargetPost(duplicate_post, 730);
    ASSERT_TRUE(duplicate_post
                    .ObserveTailPre(h.Intent(h.p1, 731), h.Stamp(h.p0, 731))
                    .tail_exact);
    const auto duplicate_p1 = h.Stamp(h.p1, 732);
    ASSERT_TRUE(duplicate_post.ObserveTailPost(duplicate_p1).tail_exact);
    EXPECT_EQ(duplicate_post.ObserveTailPost(duplicate_p1).decision,
              PpDepthPredecessorCrossScopePairDecision::DuplicateTailPost);

    for (u32 mismatch = 0; mismatch < 6; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle post_drift{4};
        h.Learn(post_drift, 2);
        const u64 source_mutation =
            mismatch == 5 ? std::numeric_limits<u64>::max() - 1 : 735;
        h.ArmThroughTargetPost(post_drift, source_mutation);
        const u64 tail_pre_mutation = source_mutation + 1;
        ASSERT_TRUE(post_drift
                        .ObserveTailPre(h.Intent(h.p1, tail_pre_mutation),
                                        h.Stamp(h.p0, tail_pre_mutation))
                        .tail_exact);
        auto post = h.Stamp(h.p1, mismatch == 5 ? 0 : tail_pre_mutation + 1);
        if (mismatch == 0) {
            ++post.hint.fragment_pgm_hash;
        } else if (mismatch == 1) {
            ++post.link.uid;
        } else if (mismatch == 2) {
            ++post.range.base.layer;
        } else if (mismatch == 3) {
            ++post.backing_generation;
        } else if (mismatch == 4) {
            ++post.mutation_epoch;
        } else {
            post.mutation_epoch = 0;
        }
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(post_drift.ObserveTailPost(post).decision,
                  PpDepthPredecessorCrossScopePairDecision::TailMismatch);
        EXPECT_FALSE(post_drift.ObserveAnchor(h.anchor, post).select);
    }

    for (u32 mismatch = 0; mismatch < 5; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle drift{4};
        h.Learn(drift, 2);
        h.ArmThroughTargetPost(drift, 740);
        ASSERT_TRUE(drift.ObserveTailPre(h.Intent(h.p1, 741), h.Stamp(h.p0, 741)).tail_exact);
        const auto first_post = h.Stamp(h.p1, 742);
        ASSERT_TRUE(drift.ObserveTailPost(first_post).tail_exact);
        auto current = first_post;
        auto intent = h.Intent(h.p1, 742);
        if (mismatch == 0) {
            ++current.hint.fragment_pgm_hash;
            intent.hint = current.hint;
        } else if (mismatch == 1) {
            ++current.link.uid;
            ++intent.link.uid;
        } else if (mismatch == 2) {
            ++current.range.base.layer;
            ++intent.range.base.layer;
        } else if (mismatch == 3) {
            ++current.backing_generation;
            ++intent.backing_generation;
        } else {
            ++current.mutation_epoch;
            ++intent.mutation_epoch;
        }
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(drift.ObserveTailPre(intent, current).decision,
                  PpDepthPredecessorCrossScopePairDecision::TailMismatch);
        EXPECT_FALSE(drift.ObserveAnchor(h.anchor, first_post).select);
    }

    for (u32 mismatch = 0; mismatch < 5; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle final_current{4};
        h.Learn(final_current, 2);
        h.ArmThroughTargetPost(final_current, 745);
        auto current = h.Stamp(h.p0, 746);
        for (u64 mutation = 746; mutation <= 747; ++mutation) {
            ASSERT_TRUE(final_current
                            .ObserveTailPre(h.Intent(h.p1, mutation), current)
                            .tail_exact);
            current = h.Stamp(h.p1, mutation + 1);
            ASSERT_TRUE(final_current.ObserveTailPost(current).tail_exact);
        }
        auto mismatched_final = current;
        if (mismatch == 0) {
            ++mismatched_final.hint.fragment_pgm_hash;
        } else if (mismatch == 1) {
            ++mismatched_final.link.uid;
        } else if (mismatch == 2) {
            ++mismatched_final.range.base.layer;
        } else if (mismatch == 3) {
            ++mismatched_final.backing_generation;
        } else {
            ++mismatched_final.mutation_epoch;
        }
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(final_current.ObserveAnchor(h.anchor, mismatched_final).decision,
                  PpDepthPredecessorCrossScopePairDecision::AnchorMismatch);
        EXPECT_FALSE(final_current.EndFrame().select);
    }

    PpDepthPredecessorCrossScopePairLifecycle wrong_anchor{4};
    h.Learn(wrong_anchor, 2);
    h.ArmThroughTargetPost(wrong_anchor, 750);
    auto anchor_prior = h.Stamp(h.p0, 751);
    for (u64 mutation = 751; mutation <= 752; ++mutation) {
        ASSERT_TRUE(
            wrong_anchor.ObserveTailPre(h.Intent(h.p1, mutation), anchor_prior).tail_exact);
        anchor_prior = h.Stamp(h.p1, mutation + 1);
        ASSERT_TRUE(wrong_anchor.ObserveTailPost(anchor_prior).tail_exact);
    }
    EXPECT_EQ(wrong_anchor.ObserveAnchor(h.p0, anchor_prior).decision,
              PpDepthPredecessorCrossScopePairDecision::AnchorMismatch);
    EXPECT_FALSE(wrong_anchor.ObserveAnchor(h.anchor, anchor_prior).select)
        << "a wrong first anchor must poison the frame";

    PpDepthPredecessorCrossScopePairLifecycle duplicate_anchor{4};
    h.Learn(duplicate_anchor, 2);
    h.ArmThroughTargetPost(duplicate_anchor, 760);
    auto duplicate_prior = h.Stamp(h.p0, 761);
    for (u64 mutation = 761; mutation <= 762; ++mutation) {
        ASSERT_TRUE(duplicate_anchor
                        .ObserveTailPre(h.Intent(h.p1, mutation), duplicate_prior)
                        .tail_exact);
        duplicate_prior = h.Stamp(h.p1, mutation + 1);
        ASSERT_TRUE(duplicate_anchor.ObserveTailPost(duplicate_prior).tail_exact);
    }
    ASSERT_TRUE(duplicate_anchor.ObserveAnchor(h.anchor, duplicate_prior).select);
    EXPECT_EQ(duplicate_anchor.ObserveAnchor(h.anchor, duplicate_prior).decision,
              PpDepthPredecessorCrossScopePairDecision::DuplicateAnchor);
    EXPECT_FALSE(duplicate_anchor.EndFrame().select);
}

TEST(PpDepthPredecessorCrossScopePair,
     RejectsEndpointOrderCandidateDriftScopeDriftAndFirstWriterFailureWithoutFallback) {
    const CrossScopePairTestHarness h{};

    PpDepthPredecessorCrossScopePairLifecycle missing_source{4};
    h.Learn(missing_source);
    const auto missing_frame = missing_source.BeginFrame();
    const auto missing_endpoint = h.SourceEndpoint(300);
    EXPECT_EQ(missing_source
                  .ObserveTargetPre(h.Boundary(
                      missing_endpoint, 300,
                      h.Candidate(missing_frame.generation, 0, 0x1,
                                  missing_endpoint.writer)))
                  .decision,
              PpDepthPredecessorCrossScopePairDecision::MissingSourcePost);

    PpDepthPredecessorCrossScopePairLifecycle duplicate_source{4};
    h.Learn(duplicate_source);
    const auto duplicate_frame = duplicate_source.BeginFrame();
    const auto duplicate_endpoint = h.SourceEndpoint(310);
    const auto duplicate_plane = h.Candidate(duplicate_frame.generation, 0, 0x1,
                                             duplicate_endpoint.writer);
    ASSERT_EQ(duplicate_source.ObserveSourcePostComplete(duplicate_endpoint, duplicate_plane).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    EXPECT_EQ(duplicate_source.ObserveSourcePostComplete(duplicate_endpoint, duplicate_plane)
                  .decision,
              PpDepthPredecessorCrossScopePairDecision::DuplicateSourcePost);

    for (u32 mismatch = 0; mismatch < 8; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle rejected{4, 30};
        h.Learn(rejected);
        const auto frame = rejected.BeginFrame();
        auto endpoint = h.SourceEndpoint(320);
        auto source_plane = h.Candidate(frame.generation, 1, 0x1, endpoint.writer);
        if (mismatch == 0) {
            endpoint.writer.hint = h.p1;
            source_plane.writer = endpoint.writer;
        } else if (mismatch == 1) {
            source_plane.generation = frame.generation - 1;
        } else if (mismatch == 2) {
            source_plane.recorded_plane_mask = 0x3;
        } else if (mismatch == 3) {
            source_plane.candidate_index = 4;
        }
        SCOPED_TRACE(mismatch);
        const auto source_result = rejected.ObserveSourcePostComplete(endpoint, source_plane);
        if (mismatch < 4) {
            EXPECT_NE(source_result.decision,
                      PpDepthPredecessorCrossScopePairDecision::Idle);
            EXPECT_FALSE(rejected.ObserveAnchor(h.anchor, h.Stamp(h.p1, 321)).select);
            continue;
        }
        ASSERT_EQ(source_result.role, PpDepthPredecessorCrossScopePairRole::TargetPre);
        auto boundary = h.Boundary(endpoint, 320, source_plane);
        if (mismatch == 4) {
            ++boundary.target_pre_current_writer.mutation_epoch;
        } else if (mismatch == 5) {
            boundary.target_guest_rendering_serial = endpoint.guest_rendering_serial;
        } else if (mismatch == 6) {
            boundary.target_guest_rendering_serial = endpoint.guest_rendering_serial + 2;
        } else {
            boundary.target_depth_clear = true;
        }
        const auto target_result = rejected.ObserveTargetPre(boundary);
        EXPECT_NE(target_result.decision,
                  PpDepthPredecessorCrossScopePairDecision::Idle);
        EXPECT_FALSE(rejected.ObserveAnchor(h.anchor, h.Stamp(h.p1, 321)).select);
    }

    PpDepthPredecessorCrossScopePairLifecycle wrong_completion{4, 50};
    h.Learn(wrong_completion);
    const auto completion_frame = wrong_completion.BeginFrame();
    const auto completion_endpoint = h.SourceEndpoint(400);
    const auto completion_plane = h.Candidate(completion_frame.generation, 2, 0x1,
                                              completion_endpoint.writer);
    ASSERT_EQ(wrong_completion.ObserveSourcePostComplete(completion_endpoint, completion_plane)
                  .role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    ASSERT_TRUE(wrong_completion
                    .ObserveTargetPre(h.Boundary(completion_endpoint, 400, completion_plane))
                    .boundary_exact);
    auto wrong_full = h.Candidate(completion_frame.generation, 3, 0x3,
                                  completion_endpoint.writer);
    EXPECT_EQ(wrong_completion.ObserveTargetPreComplete(wrong_full).decision,
              PpDepthPredecessorCrossScopePairDecision::CandidateMismatch);
    EXPECT_FALSE(wrong_completion.ObserveAnchor(h.anchor, h.Stamp(h.p1, 401)).select)
        << "a failed newest pair must not expose any older candidate";

    PpDepthPredecessorCrossScopePairLifecycle non_first{4};
    h.Learn(non_first);
    const auto non_first_frame = non_first.BeginFrame();
    const auto non_first_endpoint = h.SourceEndpoint(500);
    const auto non_first_plane = h.Candidate(non_first_frame.generation, 0, 0x1,
                                            non_first_endpoint.writer);
    ASSERT_EQ(non_first.ObserveSourcePostComplete(non_first_endpoint, non_first_plane).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    ASSERT_TRUE(non_first
                    .ObserveTargetPre(h.Boundary(non_first_endpoint, 500, non_first_plane))
                    .boundary_exact);
    ASSERT_TRUE(non_first
                    .ObserveTargetPreComplete(h.Candidate(
                        non_first_frame.generation, 0, 0x3, non_first_endpoint.writer))
                    .candidate_saved);
    auto rejected_first_writer = h.FirstWriterLoad();
    rejected_first_writer.target_first_depth_writer = false;
    EXPECT_EQ(non_first.ObserveTargetPost(h.Stamp(h.p0, 501), rejected_first_writer).decision,
              PpDepthPredecessorCrossScopePairDecision::TargetFirstWriterMismatch);
}

TEST(PpDepthPredecessorCrossScopePair,
     FailedNewestArmedPairClearsCandidateAndCannotFallBackOnRetry) {
    const CrossScopePairTestHarness h{};
    PpDepthPredecessorCrossScopePairLifecycle lifecycle{4, 70};
    h.Learn(lifecycle, 2);
    h.ArmThroughTargetPost(lifecycle, 800, 1);
    auto prior = h.Stamp(h.p0, 801);
    for (u64 mutation = 801; mutation <= 802; ++mutation) {
        ASSERT_TRUE(lifecycle.ObserveTailPre(h.Intent(h.p1, mutation), prior).tail_exact);
        prior = h.Stamp(h.p1, mutation + 1);
        ASSERT_TRUE(lifecycle.ObserveTailPost(prior).tail_exact);
    }
    ASSERT_TRUE(lifecycle.ObserveAnchor(h.anchor, prior).select);
    ASSERT_EQ(lifecycle.EndFrame().decision,
              PpDepthPredecessorCrossScopePairDecision::Selected);

    const auto failed_frame = lifecycle.BeginFrame();
    ASSERT_EQ(failed_frame.role, PpDepthPredecessorCrossScopePairRole::SourcePost);
    const auto endpoint = h.SourceEndpoint(900, 150, 700);
    const auto partial = h.Candidate(failed_frame.generation, 2, 0x1, endpoint.writer);
    ASSERT_EQ(lifecycle.ObserveSourcePostComplete(endpoint, partial).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    auto boundary = h.Boundary(endpoint, 900, partial);
    boundary.resume_host_rendering_instance_id = 701;
    boundary.target_host_rendering_instance_id = 702;
    ASSERT_TRUE(lifecycle.ObserveTargetPre(boundary).boundary_exact);
    auto failed_complete = h.Candidate(failed_frame.generation, 3, 0x3, endpoint.writer);
    ASSERT_EQ(lifecycle.ObserveTargetPreComplete(failed_complete).decision,
              PpDepthPredecessorCrossScopePairDecision::CandidateMismatch);
    EXPECT_FALSE(lifecycle.EndFrame().select);

    const auto retry = lifecycle.BeginFrame();
    EXPECT_EQ(retry.phase, PpDepthPredecessorCrossScopePairPhase::Armed);
    EXPECT_EQ(retry.role, PpDepthPredecessorCrossScopePairRole::SourcePost);
    EXPECT_FALSE(retry.candidate_saved);
    EXPECT_EQ(retry.candidate_index, 0u);
    EXPECT_FALSE(retry.select);
    EXPECT_FALSE(lifecycle.ObserveAnchor(h.anchor, prior).select)
        << "the prior frame's selected candidate must not be a fallback";
}

TEST(PpDepthPredecessorCrossScopePair,
     RejectsIncompleteMode3ProofTailSignatureCardinalityAndGenerationOverflow) {
    const CrossScopePairTestHarness h{};
    for (u32 mismatch = 0; mismatch < 6; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle learn_reject{4};
        ASSERT_EQ(learn_reject.BeginLearningFrame(h.Mode3Begin(2), h.p0, h.p1, h.anchor).role,
                  PpDepthPredecessorCrossScopePairRole::TargetPre);
        const auto source_post = h.SourceEndpoint(10);
        auto boundary = h.LearningBoundary(source_post, 10);
        if (mismatch == 0) {
            boundary.source_current.valid = false;
        } else if (mismatch == 1) {
            ++boundary.target_intent.link.uid;
        } else if (mismatch == 2) {
            ++boundary.target_intent.range.base.layer;
        } else if (mismatch == 3) {
            ++boundary.target_intent.backing_generation;
        } else if (mismatch == 4) {
            boundary.target_depth_clear = true;
        }
        SCOPED_TRACE(mismatch);
        if (mismatch < 5) {
            EXPECT_FALSE(learn_reject.ObserveLearningTargetPre(boundary).boundary_exact);
        } else {
            ASSERT_TRUE(learn_reject.ObserveLearningTargetPre(boundary).boundary_exact);
            auto non_first = h.FirstWriterLoad();
            non_first.target_first_depth_writer = false;
            EXPECT_FALSE(learn_reject.ObserveTargetPost(h.Stamp(h.p0, 11), non_first)
                             .target_first_writer_exact);
        }
        EXPECT_FALSE(learn_reject.ObserveLearningChainComplete(h.Mode3Selected(2)).committed);
        EXPECT_NE(learn_reject.EndFrame().decision,
                  PpDepthPredecessorCrossScopePairDecision::Committed);
        EXPECT_EQ(learn_reject.PeekArmedSourceHint(), nullptr);
    }

    PpDepthPredecessorCrossScopePairLifecycle incomplete_chain{4};
    ASSERT_EQ(incomplete_chain.BeginLearningFrame(h.Mode3Begin(2), h.p0, h.p1, h.anchor).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    ASSERT_TRUE(incomplete_chain
                    .ObserveLearningTargetPre(
                        h.LearningBoundary(h.SourceEndpoint(10), 10))
                    .boundary_exact);
    ASSERT_TRUE(incomplete_chain.ObserveTargetPost(h.Stamp(h.p0, 11), h.FirstWriterLoad())
                    .target_first_writer_exact);
    auto incomplete = h.Mode3Selected(2);
    incomplete.observed_occurrences = 1;
    EXPECT_FALSE(incomplete_chain.ObserveLearningChainComplete(incomplete).committed);
    EXPECT_NE(incomplete_chain.EndFrame().decision,
              PpDepthPredecessorCrossScopePairDecision::Committed);
    EXPECT_EQ(incomplete_chain.PeekArmedSourceHint(), nullptr);

    PpDepthPredecessorCrossScopePairLifecycle tail_drift{4};
    h.Learn(tail_drift, 2);
    const auto frame = tail_drift.BeginFrame();
    const auto endpoint = h.SourceEndpoint(600);
    const auto partial = h.Candidate(frame.generation, 0, 0x1, endpoint.writer);
    ASSERT_EQ(tail_drift.ObserveSourcePostComplete(endpoint, partial).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    ASSERT_TRUE(tail_drift.ObserveTargetPre(h.Boundary(endpoint, 600, partial)).boundary_exact);
    ASSERT_TRUE(tail_drift
                    .ObserveTargetPreComplete(
                        h.Candidate(frame.generation, 0, 0x3, endpoint.writer))
                    .candidate_saved);
    const auto p0_post = h.Stamp(h.p0, 601);
    ASSERT_TRUE(tail_drift.ObserveTargetPost(p0_post, h.FirstWriterLoad())
                    .target_first_writer_exact);
    auto wrong_tail_intent = h.Intent(h.p1, 601);
    ++wrong_tail_intent.hint.fragment_pgm_hash;
    EXPECT_EQ(tail_drift.ObserveTailPre(wrong_tail_intent, p0_post).decision,
              PpDepthPredecessorCrossScopePairDecision::TailMismatch);
    EXPECT_FALSE(tail_drift.ObserveAnchor(h.anchor, p0_post).select);

    PpDepthPredecessorCrossScopePairLifecycle overflow{
        4, std::numeric_limits<u64>::max()};
    h.Learn(overflow);
    const auto wrapped = overflow.BeginFrame();
    EXPECT_EQ(wrapped.phase, PpDepthPredecessorCrossScopePairPhase::GenerationWrap);
    EXPECT_EQ(wrapped.decision,
              PpDepthPredecessorCrossScopePairDecision::GenerationWrap);
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     DedicatedMode4RouteBootstrapsWithTrainingMode3ThenArmsOnlyCrossScope) {
    using Path = PpDepthPredecessorRuntimePath;
    const auto disabled = PlanPpDepthPredecessorRuntimeFrame({
        .hint_mode = false,
        .configured_hops = 4,
        .cross_scope_pair_ready = false,
        .prospective_capture = true,
    });
    EXPECT_EQ(disabled.path, Path::Disabled);
    EXPECT_FALSE(disabled.begin_one_hop);
    EXPECT_FALSE(disabled.begin_multi_hop);
    EXPECT_FALSE(disabled.begin_cross_scope);

    const auto one_hop = PlanPpDepthPredecessorRuntimeFrame({
        .hint_mode = true,
        .configured_hops = 1,
        .cross_scope_pair_ready = false,
        .prospective_capture = true,
    });
    EXPECT_EQ(one_hop.path, Path::OneHop);
    EXPECT_TRUE(one_hop.begin_one_hop);
    EXPECT_FALSE(one_hop.begin_multi_hop);
    EXPECT_FALSE(one_hop.begin_cross_scope);

    for (const u32 hops : {2u, 3u}) {
        const auto multi_hop = PlanPpDepthPredecessorRuntimeFrame({
            .hint_mode = true,
            .configured_hops = hops,
            .cross_scope_pair_ready = false,
            .prospective_capture = true,
        });
        SCOPED_TRACE(hops);
        EXPECT_EQ(multi_hop.path, Path::MultiHop);
        EXPECT_EQ(multi_hop.structural_hops, hops);
        EXPECT_TRUE(multi_hop.begin_multi_hop);
        EXPECT_FALSE(multi_hop.begin_one_hop);
        EXPECT_FALSE(multi_hop.begin_cross_scope);
        EXPECT_FALSE(multi_hop.training_only);
        EXPECT_TRUE(multi_hop.publish_feedback);
    }

    const auto bootstrap = PlanPpDepthPredecessorRuntimeFrame({
        .hint_mode = true,
        .configured_hops = 4,
        .cross_scope_pair_ready = false,
        .prospective_capture = true,
    });
    EXPECT_EQ(bootstrap.path, Path::CrossScopeBootstrap);
    EXPECT_EQ(bootstrap.structural_hops, 3u);
    EXPECT_FALSE(bootstrap.begin_one_hop)
        << "mode4 must never fall through the existing one-hop branch";
    EXPECT_TRUE(bootstrap.begin_multi_hop)
        << "mode3 is structural training only until the cross-scope pair commits";
    EXPECT_FALSE(bootstrap.begin_cross_scope);
    EXPECT_TRUE(bootstrap.feedback_eligible);
    EXPECT_TRUE(bootstrap.arm_feedback);
    EXPECT_TRUE(bootstrap.acquire_slot);
    EXPECT_TRUE(bootstrap.training_only);
    EXPECT_FALSE(bootstrap.publish_feedback);
    EXPECT_FALSE(bootstrap.allow_configured_fallback);

    const auto armed = PlanPpDepthPredecessorRuntimeFrame({
        .hint_mode = true,
        .configured_hops = 4,
        .cross_scope_pair_ready = true,
        .prospective_capture = true,
    });
    EXPECT_EQ(armed.path, Path::CrossScopeArmed);
    EXPECT_EQ(armed.structural_hops, 0u);
    EXPECT_FALSE(armed.begin_one_hop);
    EXPECT_FALSE(armed.begin_multi_hop)
        << "the committed frame must not keep consuming generic mode3 candidates";
    EXPECT_TRUE(armed.begin_cross_scope);
    EXPECT_TRUE(armed.feedback_eligible);
    EXPECT_TRUE(armed.arm_feedback);
    EXPECT_TRUE(armed.acquire_slot);
    EXPECT_FALSE(armed.training_only);
    EXPECT_TRUE(armed.publish_feedback);
    EXPECT_FALSE(armed.allow_configured_fallback);

    for (const bool pair_ready : {false, true}) {
        const auto outside_window = PlanPpDepthPredecessorRuntimeFrame({
            .hint_mode = true,
            .configured_hops = 4,
            .cross_scope_pair_ready = pair_ready,
            .prospective_capture = false,
        });
        SCOPED_TRACE(pair_ready);
        EXPECT_FALSE(outside_window.begin_one_hop);
        EXPECT_FALSE(outside_window.begin_multi_hop);
        EXPECT_FALSE(outside_window.begin_cross_scope);
        EXPECT_FALSE(outside_window.feedback_eligible);
        EXPECT_FALSE(outside_window.arm_feedback);
        EXPECT_FALSE(outside_window.acquire_slot);
        EXPECT_FALSE(outside_window.publish_feedback);
        EXPECT_FALSE(outside_window.allow_configured_fallback);
    }
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     DedicatedBootstrapResolverAndCommittedMode3SnapshotStayOutsideGenericMultiHop) {
    EXPECT_FALSE(IsPpDepthPredecessorMultiHopHintMode(true, 4));
    EXPECT_EQ(ResolvePpDepthPredecessorMultiHopLifecycleHops(true, 4), 2u)
        << "the existing generic resolver remains unchanged for modes 2/3";
    EXPECT_EQ(ResolvePpDepthPredecessorCrossScopeBootstrapLifecycleHops(false, 4), 0u);
    EXPECT_EQ(ResolvePpDepthPredecessorCrossScopeBootstrapLifecycleHops(true, 3), 0u);
    EXPECT_EQ(ResolvePpDepthPredecessorCrossScopeBootstrapLifecycleHops(true, 4), 3u);

    const SameWriterTwoHopTestHarness h{};
    PpDepthPredecessorTwoHopLifecycle mode3{
        4, 0, ResolvePpDepthPredecessorCrossScopeBootstrapLifecycleHops(true, 4)};
    h.BootstrapDistinctPrefix(mode3, 2);
    const auto begin = mode3.BeginFrame();
    ASSERT_EQ(begin.phase, PpDepthPredecessorTwoHopPhase::ArmedP2);
    ASSERT_EQ(begin.chain_kind,
              PpDepthPredecessorTwoHopChainKind::DistinctPrefixBeforeSameWriter);
    ASSERT_EQ(begin.occurrence_role, PpDepthPredecessorTwoHopOccurrenceRole::RawPrefix);
    const auto snapshot = mode3.PeekCrossScopeBootstrapSnapshot(begin);
    ASSERT_TRUE(snapshot.valid);
    EXPECT_EQ(snapshot.p0_raw_prefix, h.first_p2);
    EXPECT_EQ(snapshot.p1_tail, h.p1);
    EXPECT_EQ(snapshot.configured_anchor, h.anchor);
    EXPECT_NE(snapshot.p0_raw_prefix, snapshot.p1_tail);
    EXPECT_NE(snapshot.p0_raw_prefix, snapshot.configured_anchor);
    EXPECT_NE(snapshot.p1_tail, snapshot.configured_anchor);

    for (u32 mismatch = 0; mismatch < 13; ++mismatch) {
        auto drift = begin;
        switch (mismatch) {
        case 0:
            drift.phase = PpDepthPredecessorTwoHopPhase::LearnP2;
            break;
        case 1:
            drift.chain_kind = PpDepthPredecessorTwoHopChainKind::Distinct;
            break;
        case 2:
            drift.occurrence_role = PpDepthPredecessorTwoHopOccurrenceRole::RawP2;
            break;
        case 3:
            drift.raw_armed = false;
            break;
        case 4:
            drift.metadata_only = true;
            break;
        case 5:
            drift.prefix_join_discriminator =
                PpDepthPredecessorPrefixJoinDiscriminator::Exact;
            break;
        case 6:
            drift.generation = 0;
            break;
        case 7:
            drift.decision = PpDepthPredecessorTwoHopDecision::Committed;
            break;
        case 8:
            drift.identity_collision =
                PpDepthPredecessorTwoHopIdentityCollision::P2EqualsConfiguredAnchor;
            break;
        case 9:
            drift.expected_occurrences = 1;
            break;
        case 10:
            drift.expected_occurrences = std::numeric_limits<u32>::max();
            break;
        case 11:
            ++drift.generation;
            break;
        case 12:
            ++drift.expected_occurrences;
            break;
        default:
            FAIL() << "unhandled committed mode3 snapshot mismatch";
        }
        SCOPED_TRACE(mismatch);
        EXPECT_FALSE(mode3.PeekCrossScopeBootstrapSnapshot(drift).valid);
    }
    EXPECT_EQ(mode3.PeekCrossScopeBootstrapSnapshot(begin), snapshot)
        << "snapshot access is read-only and cannot advance nested mode3 state";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     BootstrapReadinessGroupsFailuresWithoutChangingTheSnapshotContract) {
    using Readiness = PpDepthPredecessorCrossScopeBootstrapReadiness;
    const auto classify = [](bool requested, bool pair_ready, bool begin_shape_exact,
                             bool generation_and_count_exact, bool hints_valid,
                             bool hints_distinct) {
        return ClassifyPpDepthPredecessorCrossScopeBootstrapReadiness({
            .requested = requested,
            .pair_ready = pair_ready,
            .begin_shape_exact = begin_shape_exact,
            .generation_and_count_exact = generation_and_count_exact,
            .hints_valid = hints_valid,
            .hints_distinct = hints_distinct,
        });
    };
    EXPECT_EQ(classify(false, true, true, true, true, true), Readiness::NotRequested);
    EXPECT_EQ(classify(true, false, true, true, true, true), Readiness::PairNotReady);
    EXPECT_EQ(classify(true, true, false, true, true, true),
              Readiness::BeginShapeMismatch);
    EXPECT_EQ(classify(true, true, true, false, true, true),
              Readiness::GenerationOrCountMismatch);
    EXPECT_EQ(classify(true, true, true, true, false, true), Readiness::HintMismatch)
        << "an invalid stored hint is a grouped hint mismatch";
    EXPECT_EQ(classify(true, true, true, true, true, false), Readiness::HintMismatch)
        << "a stored hint identity collision is a grouped hint mismatch";
    EXPECT_EQ(classify(true, true, true, true, true, true), Readiness::Exact);

    const SameWriterTwoHopTestHarness h{};
    PpDepthPredecessorTwoHopLifecycle mode3{
        4, 0, ResolvePpDepthPredecessorCrossScopeBootstrapLifecycleHops(true, 4)};
    auto not_ready_begin = mode3.BeginFrame();
    EXPECT_EQ(mode3.ClassifyCrossScopeBootstrapSnapshot(not_ready_begin).readiness,
              Readiness::PairNotReady);
    static_cast<void>(mode3.EndFrame());

    PpDepthPredecessorTwoHopLifecycle armed_mode3{
        4, 0, ResolvePpDepthPredecessorCrossScopeBootstrapLifecycleHops(true, 4)};
    h.BootstrapDistinctPrefix(armed_mode3, 2);
    const auto begin = armed_mode3.BeginFrame();
    const auto exact = armed_mode3.ClassifyCrossScopeBootstrapSnapshot(begin);
    ASSERT_EQ(exact.readiness, Readiness::Exact);
    EXPECT_TRUE(exact.snapshot.valid);
    EXPECT_EQ(exact.snapshot, armed_mode3.PeekCrossScopeBootstrapSnapshot(begin));
    EXPECT_EQ(armed_mode3.ClassifyCrossScopeBootstrapSnapshot(begin, false).readiness,
              Readiness::NotRequested);
    EXPECT_FALSE(armed_mode3.ClassifyCrossScopeBootstrapSnapshot(begin, false)
                     .snapshot.valid);

    for (u32 mismatch = 0; mismatch < 24; ++mismatch) {
        auto drift = begin;
        Readiness expected = Readiness::BeginShapeMismatch;
        switch (mismatch) {
        case 0:
            drift.phase = PpDepthPredecessorTwoHopPhase::LearnP2;
            break;
        case 1:
            drift.chain_kind = PpDepthPredecessorTwoHopChainKind::Distinct;
            break;
        case 2:
            drift.occurrence_role = PpDepthPredecessorTwoHopOccurrenceRole::RawP2;
            break;
        case 3:
            drift.raw_armed = false;
            break;
        case 4:
            drift.metadata_only = true;
            break;
        case 5:
            drift.prefix_join_discriminator =
                PpDepthPredecessorPrefixJoinDiscriminator::Exact;
            break;
        case 6:
            drift.generation = 0;
            expected = Readiness::GenerationOrCountMismatch;
            break;
        case 7:
            drift.decision = PpDepthPredecessorTwoHopDecision::Committed;
            break;
        case 8:
            drift.identity_collision =
                PpDepthPredecessorTwoHopIdentityCollision::P2EqualsConfiguredAnchor;
            break;
        case 9:
            drift.expected_occurrences = 1;
            expected = Readiness::GenerationOrCountMismatch;
            break;
        case 10:
            drift.expected_occurrences = std::numeric_limits<u32>::max();
            expected = Readiness::GenerationOrCountMismatch;
            break;
        case 11:
            ++drift.generation;
            expected = Readiness::GenerationOrCountMismatch;
            break;
        case 12:
            ++drift.expected_occurrences;
            expected = Readiness::GenerationOrCountMismatch;
            break;
        case 13:
            ++drift.observed_occurrences;
            expected = Readiness::GenerationOrCountMismatch;
            break;
        case 14:
            ++drift.raw_occurrences;
            expected = Readiness::GenerationOrCountMismatch;
            break;
        case 15:
            ++drift.bridge_occurrences;
            expected = Readiness::GenerationOrCountMismatch;
            break;
        case 16:
            drift.anchor_exact = true;
            break;
        case 17:
            drift.p1_intent = true;
            break;
        case 18:
            drift.p2_exact = true;
            break;
        case 19:
            drift.p1_post_exact = true;
            break;
        case 20:
            drift.prefix_join_exact = true;
            break;
        case 21:
            drift.candidate_saved = true;
            break;
        case 22:
            drift.committed = true;
            break;
        case 23:
            drift.select = true;
            break;
        default:
            FAIL() << "unhandled grouped bootstrap mismatch";
        }
        SCOPED_TRACE(mismatch);
        const auto classified = armed_mode3.ClassifyCrossScopeBootstrapSnapshot(drift);
        EXPECT_EQ(classified.readiness, expected);
        EXPECT_FALSE(classified.snapshot.valid);
        EXPECT_EQ(armed_mode3.PeekCrossScopeBootstrapSnapshot(begin), exact.snapshot)
            << "classification and mismatch probes cannot mutate nested mode3 state";
    }
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     Mode3SelectedProofDiscriminatorSeparatesEveryCurrentAdmissionPredicate) {
    using Reason = PpDepthPredecessorCrossScopeMode3SelectedProofReason;
    const CrossScopePairTestHarness h{};
    const auto begin = h.Mode3Begin(2);
    const auto selected = h.Mode3Selected(2);
    const auto exact =
        ClassifyPpDepthPredecessorCrossScopeMode3SelectedProof(begin, selected);
    EXPECT_TRUE(exact.attempted);
    EXPECT_EQ(exact.reason, Reason::Exact);
    EXPECT_EQ(exact.expected_occurrences, 2u);
    EXPECT_EQ(exact.observed_occurrences, 2u);
    EXPECT_EQ(exact.raw_occurrences, 1u);
    EXPECT_EQ(exact.bridge_occurrences, 2u);
    EXPECT_TRUE(exact.phase_exact);
    EXPECT_TRUE(exact.decision_exact);
    EXPECT_TRUE(exact.chain_exact);
    EXPECT_TRUE(exact.occurrence_role_exact);
    EXPECT_TRUE(exact.generation_continuity_exact);
    EXPECT_TRUE(exact.expected_continuity_exact);
    EXPECT_TRUE(exact.observed_cardinality_exact);
    EXPECT_TRUE(exact.raw_cardinality_exact);
    EXPECT_TRUE(exact.bridge_cardinality_exact);
    EXPECT_TRUE(exact.collision_exact);
    EXPECT_TRUE(exact.proof_flags_exact);
    EXPECT_TRUE(exact.candidate_exact);
    EXPECT_TRUE(exact.select_exact);
    EXPECT_TRUE(exact.exact);

    const auto prepare = [&](PpDepthPredecessorCrossScopePairLifecycle& lifecycle) {
        ASSERT_EQ(lifecycle.BeginLearningFrame(begin, h.p0, h.p1, h.anchor).role,
                  PpDepthPredecessorCrossScopePairRole::TargetPre);
        ASSERT_TRUE(lifecycle
                        .ObserveLearningTargetPre(
                            h.LearningBoundary(h.SourceEndpoint(10), 10))
                        .boundary_exact);
        ASSERT_TRUE(lifecycle.ObserveTargetPost(h.Stamp(h.p0, 11), h.FirstWriterLoad())
                        .target_first_writer_exact);
    };
    PpDepthPredecessorCrossScopePairLifecycle exact_lifecycle{4};
    prepare(exact_lifecycle);
    const PpDepthPredecessorCrossScopePairLifecycle& const_lifecycle =
        exact_lifecycle;
    EXPECT_EQ(const_lifecycle.ClassifyMode3SelectedProof(selected), exact)
        << "runtime proof snapshot access must be const and read-only";
    const auto exact_commit =
        exact_lifecycle.ObserveLearningChainComplete(selected);
    EXPECT_EQ(exact_commit.decision,
              PpDepthPredecessorCrossScopePairDecision::Committed);
    EXPECT_TRUE(exact_commit.committed);

    for (u32 mismatch = 0; mismatch < 31; ++mismatch) {
        auto drift = selected;
        Reason expected_reason = Reason::NotAttempted;
        switch (mismatch) {
        case 0:
            drift.phase = PpDepthPredecessorTwoHopPhase::LearnP2;
            expected_reason = Reason::PhaseMismatch;
            break;
        case 1:
            drift.decision = PpDepthPredecessorTwoHopDecision::Committed;
            expected_reason = Reason::DecisionMismatch;
            break;
        case 2:
            drift.chain_kind = PpDepthPredecessorTwoHopChainKind::Distinct;
            expected_reason = Reason::ChainMismatch;
            break;
        case 3:
            drift.occurrence_role = PpDepthPredecessorTwoHopOccurrenceRole::RawPrefix;
            expected_reason = Reason::OccurrenceRoleMismatch;
            break;
        case 4:
            drift.generation = 0;
            expected_reason = Reason::GenerationContinuityMismatch;
            break;
        case 5:
            ++drift.generation;
            expected_reason = Reason::GenerationContinuityMismatch;
            break;
        case 6:
            drift.generation = std::numeric_limits<u64>::max();
            expected_reason = Reason::GenerationContinuityMismatch;
            break;
        case 7:
            drift.expected_occurrences = 0;
            expected_reason = Reason::ExpectedContinuityMismatch;
            break;
        case 8:
            drift.expected_occurrences = 1;
            expected_reason = Reason::ExpectedContinuityMismatch;
            break;
        case 9:
            drift.expected_occurrences = std::numeric_limits<u32>::max();
            expected_reason = Reason::ExpectedContinuityMismatch;
            break;
        case 10:
            ++drift.expected_occurrences;
            expected_reason = Reason::ExpectedContinuityMismatch;
            break;
        case 11:
            --drift.observed_occurrences;
            expected_reason = Reason::ObservedCardinalityMismatch;
            break;
        case 12:
            ++drift.observed_occurrences;
            expected_reason = Reason::ObservedCardinalityMismatch;
            break;
        case 13:
            drift.raw_occurrences = 0;
            expected_reason = Reason::RawCardinalityMismatch;
            break;
        case 14:
            drift.raw_occurrences = 2;
            expected_reason = Reason::RawCardinalityMismatch;
            break;
        case 15:
            drift.raw_occurrences = std::numeric_limits<u32>::max();
            expected_reason = Reason::RawCardinalityMismatch;
            break;
        case 16:
            --drift.bridge_occurrences;
            expected_reason = Reason::BridgeCardinalityMismatch;
            break;
        case 17:
            ++drift.bridge_occurrences;
            expected_reason = Reason::BridgeCardinalityMismatch;
            break;
        case 18:
            drift.identity_collision =
                PpDepthPredecessorTwoHopIdentityCollision::P2EqualsConfiguredAnchor;
            expected_reason = Reason::IdentityCollision;
            break;
        case 19:
            drift.identity_collision =
                static_cast<PpDepthPredecessorTwoHopIdentityCollision>(
                    std::numeric_limits<u32>::max());
            expected_reason = Reason::IdentityCollision;
            break;
        case 20:
            drift.anchor_exact = false;
            expected_reason = Reason::ProofFlagsMismatch;
            break;
        case 21:
            drift.p1_intent = false;
            expected_reason = Reason::ProofFlagsMismatch;
            break;
        case 22:
            drift.p2_exact = false;
            expected_reason = Reason::ProofFlagsMismatch;
            break;
        case 23:
            drift.p1_post_exact = false;
            expected_reason = Reason::ProofFlagsMismatch;
            break;
        case 24:
            drift.prefix_join_exact = false;
            expected_reason = Reason::ProofFlagsMismatch;
            break;
        case 25:
            drift.raw_armed = false;
            expected_reason = Reason::ProofFlagsMismatch;
            break;
        case 26:
            drift.metadata_only = true;
            expected_reason = Reason::ProofFlagsMismatch;
            break;
        case 27:
            drift.prefix_join_discriminator =
                PpDepthPredecessorPrefixJoinDiscriminator::NotAttempted;
            expected_reason = Reason::ProofFlagsMismatch;
            break;
        case 28:
            drift.prefix_join_discriminator =
                static_cast<PpDepthPredecessorPrefixJoinDiscriminator>(
                    std::numeric_limits<u32>::max());
            expected_reason = Reason::ProofFlagsMismatch;
            break;
        case 29:
            drift.candidate_saved = false;
            expected_reason = Reason::CandidateMismatch;
            break;
        case 30:
            drift.select = false;
            expected_reason = Reason::SelectMismatch;
            break;
        default:
            FAIL() << "unhandled mode3 selected proof mismatch";
        }
        SCOPED_TRACE(mismatch);
        const auto classified =
            ClassifyPpDepthPredecessorCrossScopeMode3SelectedProof(begin, drift);
        EXPECT_TRUE(classified.attempted);
        EXPECT_EQ(classified.reason, expected_reason);
        EXPECT_FALSE(classified.exact);
        EXPECT_EQ(classified.expected_occurrences, drift.expected_occurrences);
        EXPECT_EQ(classified.observed_occurrences, drift.observed_occurrences);
        EXPECT_EQ(classified.raw_occurrences, drift.raw_occurrences);
        EXPECT_EQ(classified.bridge_occurrences, drift.bridge_occurrences);

        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4};
        prepare(lifecycle);
        const auto admitted = lifecycle.ObserveLearningChainComplete(drift);
        EXPECT_EQ(classified.exact, admitted.committed)
            << "the observation-only classifier must match current admission";
        EXPECT_EQ(admitted.decision,
                  PpDepthPredecessorCrossScopePairDecision::Mode3ProofMismatch);
    }

    auto zero_generation_begin = begin;
    auto zero_generation_selected = selected;
    zero_generation_begin.generation = 0;
    zero_generation_selected.generation = 0;
    const auto zero_generation =
        ClassifyPpDepthPredecessorCrossScopeMode3SelectedProof(
            zero_generation_begin, zero_generation_selected);
    EXPECT_EQ(zero_generation.reason,
              Reason::GenerationContinuityMismatch);
    EXPECT_FALSE(zero_generation.generation_continuity_exact)
        << "zero must not equal zero as a valid generation proof";

    for (const u32 invalid_expected :
         {1u, std::numeric_limits<u32>::max()}) {
        auto bounded_begin = begin;
        auto bounded_selected = selected;
        bounded_begin.expected_occurrences = invalid_expected;
        bounded_selected.expected_occurrences = invalid_expected;
        bounded_selected.observed_occurrences = invalid_expected;
        bounded_selected.bridge_occurrences = invalid_expected;
        const auto bounded =
            ClassifyPpDepthPredecessorCrossScopeMode3SelectedProof(
                bounded_begin, bounded_selected);
        EXPECT_EQ(bounded.reason, Reason::ExpectedContinuityMismatch);
        EXPECT_FALSE(bounded.expected_continuity_exact)
            << "matching out-of-bounds counts are not valid continuity";
    }

    auto two_faults = selected;
    two_faults.decision = PpDepthPredecessorTwoHopDecision::Committed;
    two_faults.raw_occurrences = 2;
    const auto first_failure =
        ClassifyPpDepthPredecessorCrossScopeMode3SelectedProof(begin,
                                                               two_faults);
    EXPECT_EQ(first_failure.reason, Reason::DecisionMismatch);
    EXPECT_FALSE(first_failure.decision_exact);
    EXPECT_FALSE(first_failure.raw_cardinality_exact)
        << "bounded reason precedence must not erase later predicate facts";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     Mode3SelectedLatestPrivateWitnessTracksTheLatestFullStampAndRollingLifecycle) {
    const SameWriterTwoHopTestHarness h{};
    PpDepthPredecessorTwoHopLifecycle mode3{4, 40, 3};
    h.BootstrapDistinctPrefix(mode3, 2);
    const auto begin = mode3.BeginFrame();
    ASSERT_EQ(begin.phase, PpDepthPredecessorTwoHopPhase::ArmedP2);

    const auto first = h.Observation(
        h.Stamp(h.first_p2, 301), h.Candidate(begin.generation, 2));
    const auto first_complete = mode3.ObserveRawP2Complete(first);
    ASSERT_EQ(first_complete.occurrence_role,
              PpDepthPredecessorTwoHopOccurrenceRole::P1Tail);
    const auto before_restart =
        mode3.SnapshotCrossScopeSelectedLatestPrivateWitness(first_complete);
    EXPECT_FALSE(before_restart.valid)
        << "a latest prefix is not a Selected witness before the terminal anchor";
    EXPECT_TRUE(before_restart.root_valid);
    EXPECT_EQ(before_restart.root_prefix, first.writer);
    EXPECT_EQ(before_restart.root_candidate, first.candidate);

    const auto restart = mode3.BeginRawPrefixRestart();
    ASSERT_EQ(restart.occurrence_role,
              PpDepthPredecessorTwoHopOccurrenceRole::RawPrefix);
    const auto restart_open =
        mode3.SnapshotCrossScopeSelectedLatestPrivateWitness(restart);
    EXPECT_FALSE(restart_open.valid);
    EXPECT_EQ(restart_open.restart_attempt_count, 1u);
    EXPECT_EQ(restart_open.restart_completion_count, 0u);
    EXPECT_TRUE(restart_open.restart_open);
    EXPECT_FALSE(restart_open.count_overflow);
    EXPECT_EQ(restart_open.root_prefix, first.writer)
        << "opening a destructive restart cannot overwrite the immutable chain root";
    EXPECT_EQ(restart_open.root_candidate, first.candidate);

    const auto replacement = h.Observation(
        h.Stamp(h.first_p2, 303), h.Candidate(begin.generation, 2));
    ASSERT_EQ(mode3.ObserveRawP2Complete(replacement).raw_occurrences, 2u);
    const auto second_restart = mode3.BeginRawPrefixRestart();
    ASSERT_EQ(second_restart.occurrence_role,
              PpDepthPredecessorTwoHopOccurrenceRole::RawPrefix);
    const auto second_restart_open =
        mode3.SnapshotCrossScopeSelectedLatestPrivateWitness(second_restart);
    EXPECT_EQ(second_restart_open.restart_attempt_count, 2u);
    EXPECT_EQ(second_restart_open.restart_completion_count, 1u);
    EXPECT_TRUE(second_restart_open.restart_open);
    EXPECT_FALSE(second_restart_open.valid);
    EXPECT_EQ(second_restart_open.root_prefix, first.writer);
    EXPECT_EQ(second_restart_open.root_candidate, first.candidate);
    const auto latest = h.Observation(
        h.Stamp(h.first_p2, 305), h.Candidate(begin.generation, 2));
    ASSERT_EQ(mode3.ObserveRawP2Complete(latest).raw_occurrences, 3u);
    ASSERT_TRUE(mode3.ObserveP1Pre(h.Intent(305), latest).prefix_join_exact);
    ASSERT_TRUE(mode3.ObserveP1Post(h.Stamp(h.p1, 306)).p1_post_exact);
    ASSERT_TRUE(
        mode3.ObserveP1Pre(h.Intent(306), h.Observation(h.Stamp(h.p1, 306)))
            .p2_exact);
    ASSERT_TRUE(mode3.ObserveP1Post(h.Stamp(h.p1, 307)).p1_post_exact);
    const auto selected = mode3.ObserveAnchor(h.anchor, h.Stamp(h.p1, 307));
    ASSERT_TRUE(selected.select);
    ASSERT_EQ(selected.raw_occurrences, 3u);
    const auto witness =
        mode3.SnapshotCrossScopeSelectedLatestPrivateWitness(selected);
    EXPECT_EQ(witness.latest_prefix, latest.writer);
    EXPECT_EQ(witness.latest_candidate, latest.candidate);
    EXPECT_EQ(witness.candidate_capacity, 4u);
    EXPECT_EQ(witness.restart_attempt_count, 2u);
    EXPECT_EQ(witness.restart_completion_count, 2u);
    EXPECT_FALSE(witness.restart_open);
    EXPECT_FALSE(witness.count_overflow);
    EXPECT_TRUE(witness.chain_exact);
    EXPECT_TRUE(witness.root_valid);
    EXPECT_TRUE(witness.root_to_latest_chain_exact);
    EXPECT_EQ(witness.root_prefix, first.writer);
    EXPECT_EQ(witness.root_candidate, first.candidate);
    EXPECT_TRUE(witness.valid);

    ASSERT_EQ(mode3.EndFrame().decision,
              PpDepthPredecessorTwoHopDecision::Selected);
    const auto next_frame = mode3.BeginFrame();
    const auto reset =
        mode3.SnapshotCrossScopeSelectedLatestPrivateWitness(next_frame);
    EXPECT_EQ(reset,
              PpDepthPredecessorCrossScopeMode3SelectedLatestPrivateWitness{})
        << "the next frame cannot inherit a private selected-latest witness";

    PpDepthPredecessorTwoHopLifecycle failed{4, 50, 3};
    h.BootstrapDistinctPrefix(failed, 2);
    const auto failed_begin = failed.BeginFrame();
    const auto superseded = h.Observation(
        h.Stamp(h.first_p2, 401), h.Candidate(failed_begin.generation, 1));
    ASSERT_EQ(failed.ObserveRawP2Complete(superseded).occurrence_role,
              PpDepthPredecessorTwoHopOccurrenceRole::P1Tail);
    ASSERT_EQ(failed.BeginRawPrefixRestart().occurrence_role,
              PpDepthPredecessorTwoHopOccurrenceRole::RawPrefix);
    auto invalid_latest = h.Observation(
        h.Stamp(h.first_p2, 403), h.Candidate(failed_begin.generation, 1));
    ++invalid_latest.writer.link.uid;
    invalid_latest.candidate.writer = invalid_latest.writer;
    ASSERT_NE(failed.ObserveRawP2Complete(invalid_latest).decision,
              PpDepthPredecessorTwoHopDecision::Idle);
    const auto no_fallback =
        failed.SnapshotCrossScopeSelectedLatestPrivateWitness(
            failed.ObserveAnchor(h.anchor, h.Stamp(h.p1, 403)));
    EXPECT_FALSE(no_fallback.valid);
    EXPECT_FALSE(no_fallback.root_valid);
    EXPECT_EQ(no_fallback.root_prefix, PpDepthPredecessorWriterStamp{});
    EXPECT_EQ(no_fallback.root_candidate, PpDepthPredecessorCandidateStamp{});
    EXPECT_EQ(no_fallback.latest_prefix, PpDepthPredecessorWriterStamp{});
    EXPECT_EQ(no_fallback.latest_candidate, PpDepthPredecessorCandidateStamp{})
        << "a failed replacement cannot restore the superseded full stamp";

    PpDepthPredecessorTwoHopLifecycle incomplete{4, 60, 3};
    h.BootstrapDistinctPrefix(incomplete, 2);
    const auto incomplete_begin = incomplete.BeginFrame();
    const auto incomplete_first = h.Observation(
        h.Stamp(h.first_p2, 501),
        h.Candidate(incomplete_begin.generation, 3));
    ASSERT_EQ(incomplete.ObserveRawP2Complete(incomplete_first).occurrence_role,
              PpDepthPredecessorTwoHopOccurrenceRole::P1Tail);
    const auto incomplete_open = incomplete.BeginRawPrefixRestart();
    ASSERT_EQ(incomplete_open.occurrence_role,
              PpDepthPredecessorTwoHopOccurrenceRole::RawPrefix);
    ASSERT_TRUE(incomplete
                    .SnapshotCrossScopeSelectedLatestPrivateWitness(
                        incomplete_open)
                    .restart_open);
    const auto incomplete_end = incomplete.EndFrame();
    EXPECT_EQ(incomplete_end.decision,
              PpDepthPredecessorTwoHopDecision::P2Mismatch);
    const auto incomplete_no_fallback =
        incomplete.SnapshotCrossScopeSelectedLatestPrivateWitness(
            incomplete_end);
    EXPECT_FALSE(incomplete_no_fallback.valid);
    EXPECT_FALSE(incomplete_no_fallback.root_valid);
    EXPECT_EQ(incomplete_no_fallback.latest_prefix,
              PpDepthPredecessorWriterStamp{});
    EXPECT_EQ(incomplete_no_fallback.latest_candidate,
              PpDepthPredecessorCandidateStamp{});
    const auto incomplete_next = incomplete.BeginFrame();
    EXPECT_EQ(incomplete.SnapshotCrossScopeSelectedLatestPrivateWitness(
                  incomplete_next),
              PpDepthPredecessorCrossScopeMode3SelectedLatestPrivateWitness{})
        << "an incomplete restart is destructive and its proof resets next frame";

    u32 count = std::numeric_limits<u32>::max() - 1;
    EXPECT_TRUE(
        TryIncrementPpDepthPredecessorCrossScopeMode3RollingCount(count));
    EXPECT_EQ(count, std::numeric_limits<u32>::max());
    EXPECT_FALSE(
        TryIncrementPpDepthPredecessorCrossScopeMode3RollingCount(count));
    EXPECT_EQ(count, std::numeric_limits<u32>::max());
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     Mode3RuntimeSelectionSnapshotIsOneAtomicPerFrameAttemptWithoutFallback) {
    using Event =
        PpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshotEvent;
    const CrossScopePairTestHarness h{};
    const auto latest_writer = h.Stamp(h.p0, 11);
    const auto latest_candidate = h.Candidate(31, 2, 0x3, latest_writer);
    const PpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshotObservation exact{
        .event = Event::Selection,
        .selected_candidate = latest_candidate,
        .frame_generation = 31,
        .expected_generation = 31,
        .frame_candidate_index = 2,
        .live_recorded_plane_mask = 0x3,
        .restart_count = 1,
        .chain_kind =
            PpDepthPredecessorTwoHopChainKind::DistinctPrefixBeforeSameWriter,
        .select_attempted = true,
        .select_succeeded = true,
        .slot_present = true,
        .frame_complete = true,
        .frame_loss_free = true,
        .final_binding_point = true,
    };
    const auto first =
        AccumulatePpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshot(
            {}, exact);
    EXPECT_EQ(first.attempt_count, 1u);
    EXPECT_EQ(first.selected_candidate, latest_candidate);
    EXPECT_EQ(first.frame_generation, 31u);
    EXPECT_EQ(first.expected_generation, 31u);
    EXPECT_EQ(first.frame_candidate_index, 2u);
    EXPECT_EQ(first.live_recorded_plane_mask, 0x3u);
    EXPECT_EQ(first.restart_count, 1u);
    EXPECT_TRUE(first.generation_exact);
    EXPECT_TRUE(first.candidate_index_exact);
    EXPECT_TRUE(first.candidate_mask_exact);
    EXPECT_TRUE(first.restart_count_bounded);
    EXPECT_TRUE(first.chain_exact);
    EXPECT_TRUE(first.select_exact);
    EXPECT_TRUE(first.slot_exact);
    EXPECT_TRUE(first.frame_exact);
    EXPECT_TRUE(first.final_binding_exact);
    EXPECT_TRUE(first.valid);

    const auto preserved =
        AccumulatePpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshot(
            first, {.event = Event::NonSelection});
    EXPECT_EQ(preserved, first)
        << "unrelated events cannot OR into or erase the one selection snapshot";

    auto second_observation = exact;
    second_observation.selected_candidate.writer.mutation_epoch = 12;
    const auto second =
        AccumulatePpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshot(
            preserved, second_observation);
    EXPECT_EQ(second.attempt_count, 2u);
    EXPECT_FALSE(second.valid);
    EXPECT_EQ(second.selected_candidate, PpDepthPredecessorCandidateStamp{})
        << "a second selection attempt clears instead of replacing the first snapshot";

    const auto invalidated_after_selection =
        AccumulatePpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshot(
            first,
            {
                .event = Event::FrameInvalidated,
                .live_recorded_plane_mask = 0x1,
                .slot_present = false,
                .frame_complete = false,
                .frame_loss_free = false,
                .final_binding_point = true,
            });
    EXPECT_EQ(invalidated_after_selection,
              PpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshot{})
        << "a later mask, slot, or frame failure invalidates the selection before binding";

    for (u32 mismatch = 0; mismatch < 15; ++mismatch) {
        auto drift = exact;
        switch (mismatch) {
        case 0:
            drift.selected_candidate.valid = false;
            break;
        case 1:
            drift.frame_generation = 30;
            break;
        case 2:
            drift.expected_generation = 0;
            break;
        case 3:
            ++drift.frame_candidate_index;
            break;
        case 4:
            drift.live_recorded_plane_mask = 0x1;
            break;
        case 5:
            drift.selected_candidate.recorded_plane_mask = 0x1;
            break;
        case 6:
            drift.restart_count = 0;
            break;
        case 7:
            drift.restart_count = std::numeric_limits<u32>::max();
            break;
        case 8:
            drift.chain_kind = PpDepthPredecessorTwoHopChainKind::Distinct;
            break;
        case 9:
            drift.select_attempted = false;
            break;
        case 10:
            drift.select_succeeded = false;
            break;
        case 11:
            drift.slot_present = false;
            break;
        case 12:
            drift.frame_complete = false;
            break;
        case 13:
            drift.frame_loss_free = false;
            break;
        case 14:
            drift.final_binding_point = false;
            break;
        default:
            FAIL() << "unhandled mode3 runtime selection mismatch";
        }
        SCOPED_TRACE(mismatch);
        const auto rejected =
            AccumulatePpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshot(
                {}, drift);
        EXPECT_EQ(rejected.attempt_count, 1u);
        EXPECT_FALSE(rejected.valid);
        EXPECT_EQ(rejected.selected_candidate,
                  PpDepthPredecessorCandidateStamp{})
            << "a malformed or stale selection event retains no private fallback";
    }

    const auto reset =
        AccumulatePpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshot(
            first, {.event = Event::Reset});
    EXPECT_EQ(reset,
              PpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshot{});
    const auto invalid =
        AccumulatePpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshot(
            first,
            {.event = static_cast<Event>(std::numeric_limits<u32>::max())});
    EXPECT_EQ(invalid,
              PpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshot{})
        << "unknown events clear rather than carrying private state to another frame";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     Mode3SelectedLatestBindingIsObservationOnlyAndBindsEveryPrivateFullStamp) {
    using Reason =
        PpDepthPredecessorCrossScopeMode3SelectedLatestBindingReason;
    using SelectionEvent =
        PpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshotEvent;
    const CrossScopePairTestHarness h{};
    const auto begin = h.Mode3Begin(2);
    auto selected = h.Mode3Selected(2);
    selected.raw_occurrences = 2;
    selected.candidate_index = 2;
    const auto p0_post = h.Stamp(h.p0, 11);
    const auto candidate = h.Candidate(31, 2, 0x3, p0_post);
    const PpDepthPredecessorCrossScopeMode3SelectedLatestPrivateWitness latest{
        .latest_prefix = p0_post,
        .latest_candidate = candidate,
        .candidate_capacity = 4,
        .restart_attempt_count = 1,
        .restart_completion_count = 1,
        .restart_open = false,
        .count_overflow = false,
        .chain_exact = true,
        .valid = true,
    };
    const auto selection =
        AccumulatePpDepthPredecessorCrossScopeMode3RuntimeSelectionSnapshot(
            {},
            {
                .event = SelectionEvent::Selection,
                .selected_candidate = candidate,
                .frame_generation = 31,
                .expected_generation = 31,
                .frame_candidate_index = 2,
                .live_recorded_plane_mask = 0x3,
                .restart_count = 1,
                .chain_kind = PpDepthPredecessorTwoHopChainKind::
                    DistinctPrefixBeforeSameWriter,
                .select_attempted = true,
                .select_succeeded = true,
                .slot_present = true,
                .frame_complete = true,
                .frame_loss_free = true,
                .final_binding_point = true,
            });
    ASSERT_TRUE(selection.valid);
    const PpDepthPredecessorCrossScopeLearningLogicalCandidateSummary logical{
        .count = 1,
        .count_overflow = false,
        .unique_valid = true,
    };
    const PpDepthPredecessorCrossScopeLearningTransitionCandidateSummary transition{
        .count = 1,
        .count_overflow = false,
        .unique_valid = true,
    };
    const PpDepthPredecessorCrossScopeMode3SelectedLatestBindingObservation exact{
        .begin = begin,
        .selected = selected,
        .selected_latest = latest,
        .runtime_selection = selection,
        .learning_p0_hint = h.p0,
        .learning_target_intent = h.Intent(h.p0, 10),
        .learning_p0_post = p0_post,
        .logical_candidates = logical,
        .transition_candidates = transition,
        .expected_generation = 31,
        .candidate_capacity = 4,
        .lifecycle_phase = PpDepthPredecessorCrossScopePairPhase::Learning,
        .lifecycle_role = PpDepthPredecessorCrossScopePairRole::TargetPre,
        .lifecycle_decision = PpDepthPredecessorCrossScopePairDecision::Idle,
        .lifecycle_frame_open = true,
        .lifecycle_boundary_exact = true,
        .lifecycle_target_first_writer_exact = true,
        .lifecycle_target_pre_seen = true,
        .lifecycle_target_post_seen = true,
    };
    const auto classified =
        ClassifyPpDepthPredecessorCrossScopeMode3SelectedLatestBinding(exact);
    EXPECT_TRUE(classified.attempted);
    EXPECT_EQ(classified.reason, Reason::Exact);
    EXPECT_EQ(classified.raw_occurrences, 2u);
    EXPECT_EQ(classified.restart_attempt_count, 1u);
    EXPECT_EQ(classified.restart_completion_count, 1u);
    EXPECT_TRUE(classified.raw_rolling_bounded);
    EXPECT_TRUE(classified.selected_core_without_raw_exact);
    EXPECT_TRUE(classified.rolling_counts_exact);
    EXPECT_TRUE(classified.latest_witness_exact);
    EXPECT_TRUE(classified.runtime_selection_exact);
    EXPECT_TRUE(classified.generation_exact);
    EXPECT_TRUE(classified.candidate_index_exact);
    EXPECT_TRUE(classified.candidate_mask_exact);
    EXPECT_TRUE(classified.actual_selected_latest_exact);
    EXPECT_TRUE(classified.latest_p0_post_exact);
    EXPECT_TRUE(classified.intent_p0_post_exact);
    EXPECT_TRUE(classified.logical_summary_exact);
    EXPECT_TRUE(classified.transition_summary_exact);
    EXPECT_TRUE(classified.lifecycle_learning_exact);
    EXPECT_TRUE(classified.exact);

    const auto legacy =
        ClassifyPpDepthPredecessorCrossScopeMode3SelectedProof(begin, selected);
    EXPECT_FALSE(legacy.raw_cardinality_exact);
    EXPECT_FALSE(legacy.exact)
        << "raw==1 remains the admission contract even when observation binds raw2 exactly";

    auto raw3 = exact;
    raw3.selected.raw_occurrences = 3;
    raw3.selected_latest.restart_attempt_count = 2;
    raw3.selected_latest.restart_completion_count = 2;
    raw3.runtime_selection.restart_count = 2;
    EXPECT_TRUE(
        ClassifyPpDepthPredecessorCrossScopeMode3SelectedLatestBinding(raw3)
            .exact)
        << "bounded multiple exact replacements remain observable";

    auto raw_zero = exact;
    raw_zero.selected.raw_occurrences = 0;
    const auto raw_zero_rejected =
        ClassifyPpDepthPredecessorCrossScopeMode3SelectedLatestBinding(
            raw_zero);
    EXPECT_EQ(raw_zero_rejected.reason, Reason::RawRollingMismatch);
    EXPECT_FALSE(raw_zero_rejected.raw_rolling_bounded);
    EXPECT_FALSE(raw_zero_rejected.exact)
        << "selected-latest observation requires a bounded raw count greater than one";

    auto index_out_of_declared_capacity = exact;
    index_out_of_declared_capacity.candidate_capacity =
        index_out_of_declared_capacity.selected.candidate_index;
    index_out_of_declared_capacity.selected_latest.candidate_capacity =
        index_out_of_declared_capacity.selected.candidate_index;
    const auto index_out_of_declared_capacity_rejected =
        ClassifyPpDepthPredecessorCrossScopeMode3SelectedLatestBinding(
            index_out_of_declared_capacity);
    EXPECT_FALSE(index_out_of_declared_capacity_rejected.candidate_index_exact);
    EXPECT_FALSE(index_out_of_declared_capacity_rejected.exact)
        << "equal outer and witness capacities cannot hide an out-of-range selected index";

    auto capacity_above_plan_max = exact;
    capacity_above_plan_max.candidate_capacity =
        PpUpstreamFeedbackPrePostPlan::MaxCandidates + 1;
    capacity_above_plan_max.selected_latest.candidate_capacity =
        PpUpstreamFeedbackPrePostPlan::MaxCandidates + 1;
    const auto capacity_above_plan_max_rejected =
        ClassifyPpDepthPredecessorCrossScopeMode3SelectedLatestBinding(
            capacity_above_plan_max);
    EXPECT_FALSE(capacity_above_plan_max_rejected.latest_witness_exact);
    EXPECT_FALSE(capacity_above_plan_max_rejected.exact)
        << "equal capacities above the public plan bound are never a valid witness";

    for (u32 generation_drift = 0; generation_drift < 2;
         ++generation_drift) {
        auto drift = exact;
        if (generation_drift == 0) {
            ++drift.runtime_selection.frame_generation;
        } else {
            ++drift.runtime_selection.expected_generation;
        }
        SCOPED_TRACE(generation_drift);
        const auto rejected =
            ClassifyPpDepthPredecessorCrossScopeMode3SelectedLatestBinding(
                drift);
        EXPECT_FALSE(rejected.generation_exact);
        EXPECT_FALSE(rejected.exact)
            << "binding rechecks both private runtime generations instead of trusting the snapshot flag";
    }

    for (u32 mismatch = 0; mismatch < 62; ++mismatch) {
        auto drift = exact;
        Reason expected_reason = Reason::NotAttempted;
        switch (mismatch) {
        case 0:
            drift.selected.phase = PpDepthPredecessorTwoHopPhase::LearnP2;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 1:
            drift.selected.decision = PpDepthPredecessorTwoHopDecision::Committed;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 2:
            drift.selected.chain_kind = PpDepthPredecessorTwoHopChainKind::Distinct;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 3:
            drift.selected.occurrence_role =
                PpDepthPredecessorTwoHopOccurrenceRole::RawPrefix;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 4:
            drift.begin.generation = 0;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 5:
            ++drift.selected.generation;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 6:
            ++drift.selected.expected_occurrences;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 7:
            --drift.selected.observed_occurrences;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 8:
            --drift.selected.bridge_occurrences;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 9:
            drift.selected.identity_collision =
                PpDepthPredecessorTwoHopIdentityCollision::P2EqualsP1;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 10:
            drift.selected.anchor_exact = false;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 11:
            drift.selected.p1_intent = false;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 12:
            drift.selected.p2_exact = false;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 13:
            drift.selected.p1_post_exact = false;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 14:
            drift.selected.prefix_join_exact = false;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 15:
            drift.selected.raw_armed = false;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 16:
            drift.selected.metadata_only = true;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 17:
            drift.selected.prefix_join_discriminator =
                PpDepthPredecessorPrefixJoinDiscriminator::NotAttempted;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 18:
            drift.selected.candidate_saved = false;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 19:
            drift.selected.select = false;
            expected_reason = Reason::SelectedCoreMismatch;
            break;
        case 20:
            drift.selected.raw_occurrences = 1;
            expected_reason = Reason::RawRollingMismatch;
            break;
        case 21:
            drift.selected.raw_occurrences = std::numeric_limits<u32>::max();
            expected_reason = Reason::RawRollingMismatch;
            break;
        case 22:
            drift.selected_latest.restart_attempt_count = 0;
            expected_reason = Reason::RestartCountMismatch;
            break;
        case 23:
            drift.selected_latest.restart_completion_count = 0;
            expected_reason = Reason::RestartCountMismatch;
            break;
        case 24:
            drift.selected_latest.restart_attempt_count = 2;
            drift.selected_latest.restart_completion_count = 2;
            expected_reason = Reason::RestartCountMismatch;
            break;
        case 25:
            drift.selected_latest.restart_open = true;
            expected_reason = Reason::RestartCountMismatch;
            break;
        case 26:
            drift.selected_latest.count_overflow = true;
            expected_reason = Reason::RestartCountMismatch;
            break;
        case 27:
            drift.selected_latest.chain_exact = false;
            expected_reason = Reason::LatestWitnessMismatch;
            break;
        case 28:
            drift.selected_latest.valid = false;
            expected_reason = Reason::LatestWitnessMismatch;
            break;
        case 29:
            drift.selected_latest.candidate_capacity = 0;
            expected_reason = Reason::LatestWitnessMismatch;
            break;
        case 30:
            ++drift.selected_latest.candidate_capacity;
            expected_reason = Reason::LatestWitnessMismatch;
            break;
        case 31:
            drift.selected_latest.latest_prefix.valid = false;
            expected_reason = Reason::LatestWitnessMismatch;
            break;
        case 32:
            drift.selected_latest.latest_candidate.valid = false;
            expected_reason = Reason::LatestWitnessMismatch;
            break;
        case 33:
            ++drift.selected_latest.latest_candidate.generation;
            expected_reason = Reason::CandidateMismatch;
            break;
        case 34:
            ++drift.selected_latest.latest_candidate.candidate_index;
            expected_reason = Reason::CandidateMismatch;
            break;
        case 35:
            drift.selected_latest.latest_candidate.recorded_plane_mask = 0x1;
            expected_reason = Reason::CandidateMismatch;
            break;
        case 36:
            ++drift.selected_latest.latest_candidate.writer.mutation_epoch;
            expected_reason = Reason::CandidateMismatch;
            break;
        case 37:
            drift.runtime_selection.valid = false;
            expected_reason = Reason::RuntimeSelectionMismatch;
            break;
        case 38:
            ++drift.runtime_selection.selected_candidate.generation;
            expected_reason = Reason::CandidateMismatch;
            break;
        case 39:
            ++drift.runtime_selection.frame_candidate_index;
            expected_reason = Reason::CandidateMismatch;
            break;
        case 40:
            drift.runtime_selection.live_recorded_plane_mask = 0x1;
            expected_reason = Reason::CandidateMismatch;
            break;
        case 41:
            drift.runtime_selection.restart_count = 0;
            expected_reason = Reason::RuntimeSelectionMismatch;
            break;
        case 42:
            drift.runtime_selection.chain_kind =
                PpDepthPredecessorTwoHopChainKind::Distinct;
            expected_reason = Reason::RuntimeSelectionMismatch;
            break;
        case 43:
            ++drift.runtime_selection.selected_candidate.writer.mutation_epoch;
            expected_reason = Reason::CandidateMismatch;
            break;
        case 44: {
            const auto newer = h.Stamp(h.p0, 12);
            drift.selected_latest.latest_prefix = newer;
            drift.selected_latest.latest_candidate.writer = newer;
            drift.runtime_selection.selected_candidate.writer = newer;
            expected_reason = Reason::TargetPostMismatch;
            break;
        }
        case 45:
            drift.learning_target_intent.hint = h.source;
            expected_reason = Reason::TargetPostMismatch;
            break;
        case 46:
            drift.learning_p0_post.mutation_epoch = 10;
            expected_reason = Reason::TargetPostMismatch;
            break;
        case 47:
            drift.logical_candidates.count = 0;
            expected_reason = Reason::LogicalSummaryMismatch;
            break;
        case 48:
            drift.logical_candidates.count = 2;
            expected_reason = Reason::LogicalSummaryMismatch;
            break;
        case 49:
            drift.logical_candidates.count_overflow = true;
            expected_reason = Reason::LogicalSummaryMismatch;
            break;
        case 50:
            drift.logical_candidates.unique_valid = false;
            expected_reason = Reason::LogicalSummaryMismatch;
            break;
        case 51:
            drift.transition_candidates.count = 0;
            expected_reason = Reason::TransitionSummaryMismatch;
            break;
        case 52:
            drift.transition_candidates.count = 2;
            expected_reason = Reason::TransitionSummaryMismatch;
            break;
        case 53:
            drift.transition_candidates.count_overflow = true;
            expected_reason = Reason::TransitionSummaryMismatch;
            break;
        case 54:
            drift.transition_candidates.unique_valid = false;
            expected_reason = Reason::TransitionSummaryMismatch;
            break;
        case 55:
            drift.lifecycle_phase = PpDepthPredecessorCrossScopePairPhase::Armed;
            expected_reason = Reason::LearningStateMismatch;
            break;
        case 56:
            drift.lifecycle_role = PpDepthPredecessorCrossScopePairRole::None;
            expected_reason = Reason::LearningStateMismatch;
            break;
        case 57:
            drift.lifecycle_decision =
                PpDepthPredecessorCrossScopePairDecision::Committed;
            expected_reason = Reason::LearningStateMismatch;
            break;
        case 58:
            drift.lifecycle_frame_open = false;
            expected_reason = Reason::LearningStateMismatch;
            break;
        case 59:
            drift.lifecycle_boundary_exact = false;
            expected_reason = Reason::LearningStateMismatch;
            break;
        case 60:
            drift.lifecycle_target_first_writer_exact = false;
            expected_reason = Reason::LearningStateMismatch;
            break;
        case 61:
            drift.lifecycle_target_post_seen = false;
            expected_reason = Reason::LearningStateMismatch;
            break;
        default:
            FAIL() << "unhandled selected-latest binding mismatch";
        }
        SCOPED_TRACE(mismatch);
        const auto rejected =
            ClassifyPpDepthPredecessorCrossScopeMode3SelectedLatestBinding(
                drift);
        EXPECT_TRUE(rejected.attempted);
        EXPECT_EQ(rejected.reason, expected_reason);
        EXPECT_FALSE(rejected.exact);
    }

    for (u32 mismatch = 0; mismatch < 31; ++mismatch) {
        auto drift = exact;
        switch (mismatch) {
        case 0:
            drift.selected_latest.latest_prefix.hint = h.source;
            drift.selected_latest.latest_candidate.writer.hint = h.source;
            drift.runtime_selection.selected_candidate.writer.hint = h.source;
            break;
        case 1:
            ++drift.selected_latest.latest_prefix.link.uid;
            ++drift.selected_latest.latest_candidate.writer.link.uid;
            ++drift.runtime_selection.selected_candidate.writer.link.uid;
            break;
        case 2:
            ++drift.selected_latest.latest_prefix.range.base.layer;
            ++drift.selected_latest.latest_candidate.writer.range.base.layer;
            ++drift.runtime_selection.selected_candidate.writer.range.base.layer;
            break;
        case 3:
            ++drift.selected_latest.latest_prefix.backing_generation;
            ++drift.selected_latest.latest_candidate.writer.backing_generation;
            ++drift.runtime_selection.selected_candidate.writer.backing_generation;
            break;
        case 4:
            ++drift.selected_latest.latest_prefix.mutation_epoch;
            ++drift.selected_latest.latest_candidate.writer.mutation_epoch;
            ++drift.runtime_selection.selected_candidate.writer.mutation_epoch;
            break;
        case 5:
            drift.selected_latest.latest_prefix.valid = false;
            break;
        case 6:
            ++drift.selected_latest.latest_candidate.writer.link.uid;
            break;
        case 7:
            ++drift.runtime_selection.selected_candidate.writer.link.uid;
            break;
        case 8:
            drift.learning_p0_hint = h.source;
            break;
        case 9:
            drift.learning_p0_hint.valid = false;
            break;
        case 10:
            drift.learning_target_intent.valid = false;
            break;
        case 11:
            drift.learning_target_intent.hint = h.source;
            break;
        case 12:
            ++drift.learning_target_intent.link.uid;
            break;
        case 13:
            ++drift.learning_target_intent.range.base.layer;
            break;
        case 14:
            ++drift.learning_target_intent.backing_generation;
            break;
        case 15:
            --drift.learning_target_intent.mutation_epoch;
            break;
        case 16:
            drift.learning_p0_post.valid = false;
            break;
        case 17:
            drift.learning_p0_post.hint = h.source;
            break;
        case 18:
            ++drift.learning_p0_post.link.uid;
            break;
        case 19:
            ++drift.learning_p0_post.range.base.layer;
            break;
        case 20:
            ++drift.learning_p0_post.backing_generation;
            break;
        case 21:
            ++drift.learning_p0_post.mutation_epoch;
            break;
        case 22:
            drift.expected_generation = 0;
            break;
        case 23:
            ++drift.expected_generation;
            break;
        case 24:
            drift.candidate_capacity = 0;
            break;
        case 25:
            ++drift.candidate_capacity;
            break;
        case 26:
            ++drift.selected.candidate_index;
            break;
        case 27:
            ++drift.runtime_selection.selected_candidate.candidate_index;
            break;
        case 28:
            drift.runtime_selection.selected_candidate.recorded_plane_mask =
                0x1;
            break;
        case 29:
            drift.lifecycle_target_pre_seen = false;
            break;
        case 30:
            drift.lifecycle_target_post_seen = false;
            break;
        default:
            FAIL() << "unhandled selected-latest full-stamp mismatch";
        }
        SCOPED_TRACE(mismatch);
        const auto rejected =
            ClassifyPpDepthPredecessorCrossScopeMode3SelectedLatestBinding(
                drift);
        EXPECT_NE(rejected.reason, Reason::Exact);
        EXPECT_FALSE(rejected.exact)
            << "every private full-stamp, capacity, and lifecycle field participates";
    }

    const auto mutate_one_stamp_field =
        [&](PpDepthPredecessorWriterStamp& stamp, u32 field) {
            switch (field) {
            case 0:
                stamp.valid = false;
                break;
            case 1:
                stamp.hint.valid = false;
                break;
            case 2:
                ++stamp.hint.draw.element_count;
                break;
            case 3:
                ++stamp.hint.fragment_pgm_hash;
                break;
            case 4:
                ++stamp.link.uid;
                break;
            case 5:
                ++stamp.range.base.layer;
                break;
            case 6:
                ++stamp.backing_generation;
                break;
            case 7:
                ++stamp.mutation_epoch;
                break;
            default:
                FAIL() << "unhandled private writer-stamp field";
            }
        };
    for (u32 mismatch = 0; mismatch < 24; ++mismatch) {
        auto drift = exact;
        const u32 relation = mismatch / 8;
        const u32 field = mismatch % 8;
        switch (relation) {
        case 0:
            mutate_one_stamp_field(
                drift.selected_latest.latest_candidate.writer, field);
            break;
        case 1:
            mutate_one_stamp_field(
                drift.runtime_selection.selected_candidate.writer, field);
            break;
        case 2:
            mutate_one_stamp_field(drift.learning_p0_post, field);
            break;
        default:
            FAIL() << "unhandled private full-stamp relation";
        }
        SCOPED_TRACE(mismatch);
        const auto rejected =
            ClassifyPpDepthPredecessorCrossScopeMode3SelectedLatestBinding(
                drift);
        EXPECT_FALSE(rejected.exact);
        if (relation == 0) {
            EXPECT_FALSE(rejected.latest_witness_exact)
                << "latest candidate.writer must equal the latest prefix full stamp";
        } else if (relation == 1) {
            EXPECT_FALSE(rejected.actual_selected_latest_exact)
                << "runtime selected candidate must equal the latest full candidate";
        } else {
            EXPECT_FALSE(rejected.latest_p0_post_exact)
                << "cross learning P0 post must equal the latest prefix full stamp";
        }
    }

    PpDepthPredecessorCrossScopePairLifecycle learning{4};
    ASSERT_EQ(learning.BeginLearningFrame(begin, h.p0, h.p1, h.anchor).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    ASSERT_TRUE(learning
                    .ObserveLearningTargetPre(
                        h.LearningBoundary(h.SourceEndpoint(10), 10))
                    .boundary_exact);
    ASSERT_TRUE(learning
                    .ObserveTargetPost(p0_post, h.FirstWriterLoad())
                    .target_first_writer_exact);
    const PpDepthPredecessorCrossScopePairLifecycle& read_only = learning;
    EXPECT_EQ(read_only.ClassifyMode3SelectedLatestBinding(
                  selected, latest, selection, logical, transition),
              classified)
        << "the lifecycle wrapper binds the observation to its private intent/post state";
    const auto legacy_admission = learning.ObserveLearningChainComplete(selected);
    EXPECT_FALSE(legacy_admission.committed);
    EXPECT_EQ(legacy_admission.decision,
              PpDepthPredecessorCrossScopePairDecision::Mode3ProofMismatch)
        << "the new exact evidence is observation-only and cannot relax raw==1";
    EXPECT_FALSE(learning
                     .ClassifyMode3SelectedLatestBinding(
                         selected, latest, selection, logical, transition)
                     .exact)
        << "failed legacy admission is terminal and cannot reuse prior evidence";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     Mode3RootBindingSeparatesAbsentCrossStateFromARealRootMismatch) {
    using Reason = PpDepthPredecessorCrossScopeMode3RootBindingReason;
    const CrossScopePairTestHarness h{};
    const auto root = h.Stamp(h.p0, 11);
    const auto latest = h.Stamp(h.p0, 15);
    const auto root_candidate = h.Candidate(31, 2, 0x3, root);
    const auto latest_candidate = h.Candidate(31, 2, 0x3, latest);
    const PpDepthPredecessorCrossScopeMode3SelectedLatestPrivateWitness witness{
        .root_prefix = root,
        .root_candidate = root_candidate,
        .latest_prefix = latest,
        .latest_candidate = latest_candidate,
        .candidate_capacity = 4,
        .restart_attempt_count = 1,
        .restart_completion_count = 1,
        .restart_open = false,
        .count_overflow = false,
        .chain_exact = true,
        .root_valid = true,
        .root_to_latest_chain_exact = true,
        .valid = true,
    };
    const PpDepthPredecessorCrossScopeMode3SelectedLatestBindingEvidence
        latest_selection{
            .attempted = true,
            .reason =
                PpDepthPredecessorCrossScopeMode3SelectedLatestBindingReason::
                    TargetPostMismatch,
            .raw_occurrences = 2,
            .restart_attempt_count = 1,
            .restart_completion_count = 1,
            .raw_rolling_bounded = true,
            .selected_core_without_raw_exact = true,
            .rolling_counts_exact = true,
            .latest_witness_exact = true,
            .runtime_selection_exact = true,
            .generation_exact = true,
            .candidate_index_exact = true,
            .candidate_mask_exact = true,
            .actual_selected_latest_exact = true,
            .latest_p0_post_exact = false,
            .intent_p0_post_exact = true,
            .logical_summary_exact = true,
            .transition_summary_exact = true,
            .lifecycle_learning_exact = true,
            .exact = false,
        };
    const PpDepthPredecessorCrossScopeMode3RootBindingObservation exact{
        .selected_latest = witness,
        .selected_latest_evidence = latest_selection,
        .stored_source = h.SourceEndpoint(10),
        .target_intent = h.Intent(h.p0, 10),
        .p0_post = root,
        .lifecycle_phase = PpDepthPredecessorCrossScopePairPhase::Learning,
        .lifecycle_role = PpDepthPredecessorCrossScopePairRole::TargetPre,
        .lifecycle_decision = PpDepthPredecessorCrossScopePairDecision::Idle,
        .lifecycle_frame_open = true,
        .lifecycle_boundary_exact = true,
        .lifecycle_target_first_writer_exact = true,
        .lifecycle_target_pre_seen = true,
        .lifecycle_target_post_seen = true,
    };

    const auto classified =
        ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(exact);
    EXPECT_TRUE(classified.attempted);
    EXPECT_EQ(classified.reason, Reason::Exact);
    EXPECT_TRUE(classified.root_witness_exact);
    EXPECT_TRUE(classified.cross_state_present);
    EXPECT_TRUE(classified.cross_root_exact);
    EXPECT_TRUE(classified.chain_exact);
    EXPECT_TRUE(classified.latest_selection_exact)
        << "latest selection is independent of whether cross P0 bound the root or latest post";
    EXPECT_TRUE(classified.lifecycle_exact);
    EXPECT_TRUE(classified.exact);

    auto raw1 = exact;
    raw1.selected_latest_evidence.raw_occurrences = 1;
    raw1.selected_latest.restart_attempt_count = 0;
    raw1.selected_latest.restart_completion_count = 0;
    raw1.selected_latest.root_to_latest_chain_exact = false;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(raw1),
              PpDepthPredecessorCrossScopeMode3RootBindingEvidence{})
        << "without a bounded restart there is no root-to-latest question";

    auto raw3 = exact;
    raw3.selected_latest.latest_prefix = h.Stamp(h.p0, 17);
    raw3.selected_latest.latest_candidate.writer =
        raw3.selected_latest.latest_prefix;
    raw3.selected_latest.restart_attempt_count = 2;
    raw3.selected_latest.restart_completion_count = 2;
    raw3.selected_latest_evidence.raw_occurrences = 3;
    raw3.selected_latest_evidence.restart_attempt_count = 2;
    raw3.selected_latest_evidence.restart_completion_count = 2;
    EXPECT_TRUE(
        ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(raw3).exact)
        << "the immutable root survives more than one exact replacement";

    auto absent = exact;
    absent.stored_source = {};
    const auto absent_result =
        ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(absent);
    EXPECT_EQ(absent_result.reason, Reason::CrossStateAbsent);
    EXPECT_FALSE(absent_result.cross_state_present);

    for (u32 source_drift = 0; source_drift < 3; ++source_drift) {
        auto disconnected = exact;
        switch (source_drift) {
        case 0:
            ++disconnected.stored_source.writer.link.uid;
            break;
        case 1:
            ++disconnected.stored_source.writer.backing_generation;
            break;
        case 2:
            ++disconnected.stored_source.writer.mutation_epoch;
            break;
        default:
            FAIL() << "unhandled stored-source drift";
        }
        SCOPED_TRACE(source_drift);
        const auto disconnected_result =
            ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(
                disconnected);
        EXPECT_TRUE(disconnected_result.cross_state_present);
        EXPECT_EQ(disconnected_result.reason, Reason::CrossRootMismatch)
            << "a structurally valid but unrelated stored source is not root-bound cross state";
    }
    auto noncanonical_source_range = exact;
    ++noncanonical_source_range.stored_source.writer.range.base.layer;
    const auto noncanonical_range_result =
        ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(
            noncanonical_source_range);
    EXPECT_FALSE(noncanonical_range_result.cross_state_present);
    EXPECT_EQ(noncanonical_range_result.reason, Reason::CrossStateAbsent)
        << "there is no alternative valid depth-predecessor range: range drift is structurally absent";

    auto root_mismatch = exact;
    root_mismatch.p0_post = latest;
    const auto mismatch_result =
        ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(root_mismatch);
    EXPECT_EQ(mismatch_result.reason, Reason::CrossRootMismatch);
    EXPECT_TRUE(mismatch_result.cross_state_present);
    EXPECT_FALSE(mismatch_result.cross_root_exact);

    auto overwritten_root = exact;
    overwritten_root.selected_latest.root_prefix = h.Stamp(h.p0, 13);
    overwritten_root.selected_latest.root_candidate.writer =
        overwritten_root.selected_latest.root_prefix;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(
                  overwritten_root)
                  .reason,
              Reason::CrossRootMismatch)
        << "a later prefix cannot masquerade as the immutable root";

    auto malformed_root = exact;
    ++malformed_root.selected_latest.root_candidate.writer.link.uid;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(
                  malformed_root)
                  .reason,
              Reason::RootWitnessMismatch);

    for (u32 failure = 0; failure < 2; ++failure) {
        auto broken_chain = exact;
        if (failure == 0) {
            broken_chain.selected_latest.restart_open = true;
        } else {
            broken_chain.selected_latest.count_overflow = true;
        }
        SCOPED_TRACE(failure);
        EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(
                      broken_chain)
                      .reason,
                  Reason::ChainMismatch)
            << "an open or overflowed destructive restart has no root fallback";
    }

    auto latest_selection_mismatch = exact;
    latest_selection_mismatch.selected_latest_evidence.runtime_selection_exact =
        false;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(
                  latest_selection_mismatch)
                  .reason,
              Reason::LatestSelectionMismatch);

    auto selected_count_mismatch = exact;
    selected_count_mismatch.selected_latest_evidence.restart_attempt_count = 0;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(
                  selected_count_mismatch)
                  .reason,
              Reason::LatestSelectionMismatch)
        << "the selected-latest summary must bind the same raw-1 count as the private witness";

    auto lifecycle_mismatch = exact;
    lifecycle_mismatch.lifecycle_target_post_seen = false;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeMode3RootBinding(
                  lifecycle_mismatch)
                  .reason,
              Reason::LifecycleMismatch);

    PpDepthPredecessorCrossScopePairLifecycle probed{4};
    PpDepthPredecessorCrossScopePairLifecycle control{4};
    for (auto* lifecycle : {&probed, &control}) {
        ASSERT_EQ(lifecycle->BeginLearningFrame(
                      h.Mode3Begin(), h.p0, h.p1, h.anchor)
                      .role,
                  PpDepthPredecessorCrossScopePairRole::TargetPre);
        ASSERT_TRUE(lifecycle
                        ->ObserveLearningTargetPre(
                            h.LearningBoundary(h.SourceEndpoint(10), 10))
                        .boundary_exact);
        ASSERT_TRUE(lifecycle
                        ->ObserveTargetPost(root, h.FirstWriterLoad())
                        .target_first_writer_exact);
    }
    const PpDepthPredecessorCrossScopePairLifecycle& read_only = probed;
    EXPECT_TRUE(read_only.ClassifyMode3RootBinding(witness, latest_selection)
                    .exact);
    const auto probed_admission =
        probed.ObserveLearningChainComplete(h.Mode3Selected());
    const auto control_admission =
        control.ObserveLearningChainComplete(h.Mode3Selected());
    EXPECT_EQ(probed_admission.decision, control_admission.decision);
    EXPECT_EQ(probed_admission.committed, control_admission.committed);
    EXPECT_EQ(probed_admission.select, control_admission.select);
    const auto probed_end = probed.EndFrame();
    const auto control_end = control.EndFrame();
    EXPECT_EQ(probed_end.decision, control_end.decision);
    EXPECT_EQ(probed_end.committed, control_end.committed);
    EXPECT_EQ(probed_end.select, control_end.select)
        << "the const root probe cannot affect raw==1 admission or publication state";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     RootBoundRollingAdmissionPreservesRawOneAndCommitsOnlyExactRawTwoOrThreeAtEnd) {
    const CrossScopePairTestHarness h{};

    PpDepthPredecessorCrossScopePairLifecycle legacy_raw_one{4};
    BeginCrossScopeRootBoundLearning(legacy_raw_one, h);
    EXPECT_TRUE(legacy_raw_one.ObserveLearningChainComplete(h.Mode3Selected(2)).committed)
        << "the established raw==1 admission path is unchanged";
    EXPECT_EQ(legacy_raw_one.EndFrame().decision,
              PpDepthPredecessorCrossScopePairDecision::Committed);
    EXPECT_EQ(legacy_raw_one.BeginFrame().role,
              PpDepthPredecessorCrossScopePairRole::SourcePost);

    PpDepthPredecessorCrossScopePairLifecycle rolling_raw_one{4};
    BeginCrossScopeRootBoundLearning(rolling_raw_one, h);
    const auto raw_one = MakeCrossScopeRootBoundAdmissionInputs(h, 1);
    EXPECT_FALSE(rolling_raw_one
                     .ObserveLearningRootBoundChainComplete(
                         raw_one.selected, raw_one.selected_latest,
                         raw_one.runtime_selection, raw_one.logical_candidates,
                         raw_one.transition_candidates)
                     .committed)
        << "root-bound rolling admission is separate and never broadens raw==1";
    EXPECT_EQ(rolling_raw_one.EndFrame().decision,
              PpDepthPredecessorCrossScopePairDecision::Mode3ProofMismatch);
    EXPECT_NE(rolling_raw_one.BeginFrame().role,
              PpDepthPredecessorCrossScopePairRole::SourcePost);

    for (const u32 raw_occurrences : {2u, 3u}) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4};
        BeginCrossScopeRootBoundLearning(lifecycle, h);
        const auto input =
            MakeCrossScopeRootBoundAdmissionInputs(h, raw_occurrences);
        const auto staged = lifecycle.ObserveLearningRootBoundChainComplete(
            input.selected, input.selected_latest, input.runtime_selection,
            input.logical_candidates, input.transition_candidates);
        SCOPED_TRACE(raw_occurrences);
        EXPECT_EQ(staged.phase, PpDepthPredecessorCrossScopePairPhase::Learning);
        EXPECT_EQ(staged.decision,
                  PpDepthPredecessorCrossScopePairDecision::Committed);
        EXPECT_TRUE(staged.committed);
        EXPECT_EQ(lifecycle.EndFrame().decision,
                  PpDepthPredecessorCrossScopePairDecision::Committed);
        EXPECT_EQ(lifecycle.BeginFrame().role,
                  PpDepthPredecessorCrossScopePairRole::SourcePost)
            << "the root-bound learning result becomes armed only at EndFrame";
    }

    for (const u32 raw_occurrences :
         {0u, std::numeric_limits<u32>::max()}) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4};
        BeginCrossScopeRootBoundLearning(lifecycle, h);
        const auto input =
            MakeCrossScopeRootBoundAdmissionInputs(h, raw_occurrences);
        SCOPED_TRACE(raw_occurrences);
        EXPECT_EQ(lifecycle
                      .ObserveLearningRootBoundChainComplete(
                          input.selected, input.selected_latest,
                          input.runtime_selection, input.logical_candidates,
                          input.transition_candidates)
                      .decision,
                  PpDepthPredecessorCrossScopePairDecision::Mode3ProofMismatch);
        EXPECT_FALSE(lifecycle.EndFrame().committed);
        EXPECT_NE(lifecycle.BeginFrame().role,
                  PpDepthPredecessorCrossScopePairRole::SourcePost);
    }
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     RootBoundRollingAdmissionRecomputesEveryPrivateBoundGroupAndHasNoFallback) {
    const CrossScopePairTestHarness h{};
    const auto exact = MakeCrossScopeRootBoundAdmissionInputs(h, 2);

    for (u32 mismatch = 0; mismatch < 18; ++mismatch) {
        auto drift = exact;
        switch (mismatch) {
        case 0:
            drift.selected.anchor_exact = false;
            break;
        case 1:
            drift.selected.select = false;
            break;
        case 2:
            drift.selected_latest = {};
            break;
        case 3:
            drift.selected_latest.root_prefix = h.Stamp(h.p0, 13);
            drift.selected_latest.root_candidate.writer =
                drift.selected_latest.root_prefix;
            break;
        case 4:
            drift.selected_latest.restart_open = true;
            break;
        case 5:
            --drift.selected_latest.restart_completion_count;
            break;
        case 6:
            drift.selected_latest.count_overflow = true;
            break;
        case 7:
            drift.runtime_selection.valid = false;
            break;
        case 8:
            ++drift.runtime_selection.frame_generation;
            break;
        case 9:
            ++drift.runtime_selection.selected_candidate.candidate_index;
            break;
        case 10:
            drift.runtime_selection.live_recorded_plane_mask = 0x1;
            break;
        case 11:
            ++drift.selected_latest.latest_candidate.writer.link.uid;
            break;
        case 12:
            drift.logical_candidates.count = 2;
            break;
        case 13:
            drift.transition_candidates.unique_valid = false;
            break;
        case 14:
            ++drift.selected.generation;
            break;
        case 15:
            ++drift.selected.candidate_index;
            break;
        case 16:
            drift.selected_latest.latest_candidate.recorded_plane_mask = 0x1;
            break;
        case 17:
            drift.selected.raw_occurrences = 3;
            break;
        default:
            FAIL() << "unhandled root-bound admission mismatch";
        }
        SCOPED_TRACE(mismatch);
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4};
        BeginCrossScopeRootBoundLearning(lifecycle, h);
        EXPECT_EQ(lifecycle
                      .ObserveLearningRootBoundChainComplete(
                          drift.selected, drift.selected_latest,
                          drift.runtime_selection, drift.logical_candidates,
                          drift.transition_candidates)
                      .decision,
                  PpDepthPredecessorCrossScopePairDecision::Mode3ProofMismatch);
        EXPECT_FALSE(lifecycle
                         .ObserveLearningRootBoundChainComplete(
                             exact.selected, exact.selected_latest,
                             exact.runtime_selection, exact.logical_candidates,
                             exact.transition_candidates)
                         .committed)
            << "a malformed first attempt cannot fall back to later exact evidence";
        EXPECT_FALSE(lifecycle.EndFrame().committed);
        EXPECT_NE(lifecycle.BeginFrame().role,
                  PpDepthPredecessorCrossScopePairRole::SourcePost);
    }

    PpDepthPredecessorCrossScopePairLifecycle duplicate{4};
    BeginCrossScopeRootBoundLearning(duplicate, h);
    ASSERT_TRUE(duplicate
                    .ObserveLearningRootBoundChainComplete(
                        exact.selected, exact.selected_latest,
                        exact.runtime_selection, exact.logical_candidates,
                        exact.transition_candidates)
                    .committed);
    EXPECT_EQ(duplicate
                  .ObserveLearningRootBoundChainComplete(
                      exact.selected, exact.selected_latest,
                      exact.runtime_selection, exact.logical_candidates,
                      exact.transition_candidates)
                  .decision,
              PpDepthPredecessorCrossScopePairDecision::Mode3ProofMismatch)
        << "duplicate admission rolls the staged commit back without fallback";
    EXPECT_FALSE(duplicate.EndFrame().committed);
    EXPECT_NE(duplicate.BeginFrame().role,
              PpDepthPredecessorCrossScopePairRole::SourcePost);

    PpDepthPredecessorCrossScopePairLifecycle missing_target_post{4};
    ASSERT_EQ(missing_target_post
                  .BeginLearningFrame(h.Mode3Begin(2), h.p0, h.p1, h.anchor)
                  .role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    ASSERT_TRUE(missing_target_post
                    .ObserveLearningTargetPre(
                        h.LearningBoundary(h.SourceEndpoint(10), 10))
                    .boundary_exact);
    EXPECT_FALSE(missing_target_post
                     .ObserveLearningRootBoundChainComplete(
                         exact.selected, exact.selected_latest,
                         exact.runtime_selection, exact.logical_candidates,
                         exact.transition_candidates)
                     .committed);
    EXPECT_FALSE(missing_target_post.EndFrame().committed);

    PpDepthPredecessorCrossScopePairLifecycle p0_bound_to_latest{4};
    ASSERT_EQ(p0_bound_to_latest
                  .BeginLearningFrame(h.Mode3Begin(2), h.p0, h.p1, h.anchor)
                  .role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    ASSERT_TRUE(p0_bound_to_latest
                    .ObserveLearningTargetPre(
                        h.LearningBoundary(h.SourceEndpoint(14), 14))
                    .boundary_exact);
    ASSERT_TRUE(p0_bound_to_latest
                    .ObserveTargetPost(h.Stamp(h.p0, 15), h.FirstWriterLoad())
                    .target_first_writer_exact);
    EXPECT_FALSE(p0_bound_to_latest
                     .ObserveLearningRootBoundChainComplete(
                         exact.selected, exact.selected_latest,
                         exact.runtime_selection, exact.logical_candidates,
                         exact.transition_candidates)
                     .committed)
        << "a lifecycle P0 bound to the latest replacement is not root-bound";
    EXPECT_FALSE(p0_bound_to_latest.EndFrame().committed);

    PpDepthPredecessorCrossScopePairLifecycle malformed_source{4};
    ASSERT_EQ(malformed_source
                  .BeginLearningFrame(h.Mode3Begin(2), h.p0, h.p1, h.anchor)
                  .role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    auto source_drift = h.LearningBoundary(h.SourceEndpoint(10), 10);
    ++source_drift.source_current.writer.link.uid;
    EXPECT_FALSE(malformed_source.ObserveLearningTargetPre(source_drift).boundary_exact);
    EXPECT_FALSE(malformed_source
                     .ObserveLearningRootBoundChainComplete(
                         exact.selected, exact.selected_latest,
                         exact.runtime_selection, exact.logical_candidates,
                         exact.transition_candidates)
                     .committed)
        << "private source full-stamp drift cannot be repaired by caller evidence";
    EXPECT_FALSE(malformed_source.EndFrame().committed);

    PpDepthPredecessorCrossScopePairLifecycle first_writer_drift{4};
    ASSERT_EQ(first_writer_drift
                  .BeginLearningFrame(h.Mode3Begin(2), h.p0, h.p1, h.anchor)
                  .role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    ASSERT_TRUE(first_writer_drift
                    .ObserveLearningTargetPre(
                        h.LearningBoundary(h.SourceEndpoint(10), 10))
                    .boundary_exact);
    auto clear = h.FirstWriterLoad();
    clear.target_scope_load = false;
    clear.target_scope_clear = true;
    EXPECT_FALSE(first_writer_drift.ObserveTargetPost(h.Stamp(h.p0, 11), clear)
                     .target_first_writer_exact);
    EXPECT_FALSE(first_writer_drift
                     .ObserveLearningRootBoundChainComplete(
                         exact.selected, exact.selected_latest,
                         exact.runtime_selection, exact.logical_candidates,
                         exact.transition_candidates)
                     .committed);
    EXPECT_FALSE(first_writer_drift.EndFrame().committed);
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     RootBoundRollingAdmissionRejectsEveryMalformedImmutableRootAndTheArmedPhase) {
    const CrossScopePairTestHarness h{};
    const auto exact = MakeCrossScopeRootBoundAdmissionInputs(h, 2);

    for (u32 mismatch = 0; mismatch < 6; ++mismatch) {
        auto drift = exact;
        switch (mismatch) {
        case 0:
            drift.selected_latest.root_valid = false;
            break;
        case 1:
            drift.selected_latest.root_candidate.generation = 0;
            break;
        case 2:
            ++drift.selected_latest.root_candidate.generation;
            break;
        case 3:
            drift.selected_latest.root_candidate.candidate_index =
                drift.selected_latest.candidate_capacity;
            break;
        case 4:
            drift.selected_latest.root_candidate.recorded_plane_mask = 0x1;
            break;
        case 5:
            ++drift.selected_latest.root_candidate.writer.link.uid;
            break;
        default:
            FAIL() << "unhandled immutable-root mismatch";
        }
        SCOPED_TRACE(mismatch);
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4};
        BeginCrossScopeRootBoundLearning(lifecycle, h);
        EXPECT_EQ(lifecycle
                      .ObserveLearningRootBoundChainComplete(
                          drift.selected, drift.selected_latest,
                          drift.runtime_selection, drift.logical_candidates,
                          drift.transition_candidates)
                      .decision,
                  PpDepthPredecessorCrossScopePairDecision::Mode3ProofMismatch);
        EXPECT_FALSE(lifecycle
                         .ObserveLearningRootBoundChainComplete(
                             exact.selected, exact.selected_latest,
                             exact.runtime_selection, exact.logical_candidates,
                             exact.transition_candidates)
                         .committed)
            << "malformed immutable-root evidence is terminal";
        EXPECT_FALSE(lifecycle.EndFrame().committed);
    }

    PpDepthPredecessorCrossScopePairLifecycle armed{4};
    h.Learn(armed);
    ASSERT_EQ(armed.BeginFrame().role,
              PpDepthPredecessorCrossScopePairRole::SourcePost);
    const auto rejected = armed.ObserveLearningRootBoundChainComplete(
        exact.selected, exact.selected_latest, exact.runtime_selection,
        exact.logical_candidates, exact.transition_candidates);
    EXPECT_EQ(rejected.phase, PpDepthPredecessorCrossScopePairPhase::Armed);
    EXPECT_EQ(rejected.decision,
              PpDepthPredecessorCrossScopePairDecision::Mode3ProofMismatch);
    EXPECT_FALSE(rejected.committed);
    EXPECT_FALSE(rejected.select);
    const auto armed_end = armed.EndFrame();
    EXPECT_FALSE(armed_end.committed);
    EXPECT_FALSE(armed_end.select)
        << "rolling-learning admission cannot select or publish from an armed frame";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     ArmedTargetRepeatMetadataRollsExactP0EndpointsWithoutRecopyingTheCandidate) {
    const CrossScopePairTestHarness h{};

    PpDepthPredecessorCrossScopePairLifecycle legacy{4};
    h.Learn(legacy, 2);
    EXPECT_EQ(legacy.BeginFrame().expected_target_repeat_count, 0u)
        << "raw-one learning keeps the established no-repeat lifecycle";

    PpDepthPredecessorCrossScopePairLifecycle legacy_selected{4};
    h.Learn(legacy_selected, 2);
    h.ArmThroughTargetPost(legacy_selected, 880, 1);
    auto legacy_current = h.Stamp(h.p0, 881);
    for (u32 tail = 0; tail < 2; ++tail) {
        ASSERT_TRUE(legacy_selected
                        .ObserveTailPre(
                            h.Intent(h.p1, legacy_current.mutation_epoch),
                            legacy_current)
                        .tail_exact);
        legacy_current = h.Stamp(h.p1, legacy_current.mutation_epoch + 1);
        ASSERT_TRUE(legacy_selected.ObserveTailPost(legacy_current).tail_exact);
    }
    EXPECT_TRUE(legacy_selected.ObserveAnchor(h.anchor, legacy_current).select)
        << "raw-one selection remains byte-for-byte lifecycle compatible";

    for (const auto [raw_occurrences, tail_occurrences] :
         std::array{std::pair{2u, 2u}, std::pair{6u, 6u}}) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4};
        auto context = ArmRootBoundTargetRepeat(
            lifecycle, h, raw_occurrences, tail_occurrences);
        const u32 expected_repeats = raw_occurrences - 1;
        SCOPED_TRACE(raw_occurrences);
        EXPECT_EQ(context.begin.expected_target_repeat_count,
                  expected_repeats);
        EXPECT_EQ(context.initial_target_post.expected_target_repeat_count,
                  expected_repeats);
        EXPECT_EQ(context.initial_target_post.target_repeat_attempt_count, 0u);
        EXPECT_EQ(context.initial_target_post.target_repeat_completion_count, 0u);
        EXPECT_EQ(context.initial_target_post.source_post_count, 1u);
        EXPECT_EQ(context.initial_target_post.target_pre_count, 1u);
        EXPECT_TRUE(context.initial_target_post.candidate_saved);
        EXPECT_TRUE(lifecycle.MatchesTargetRepeat(
            h.p0.draw, h.p0.fragment_pgm_hash));

        for (u32 repeat = 0; repeat < expected_repeats; ++repeat) {
            const auto pre = MakeCrossScopeTargetRepeatPre(h, context);
            const auto before =
                lifecycle.SnapshotTargetRepeatRetainedState();
            EXPECT_EQ(before.candidate, context.candidate);
            EXPECT_EQ(before.latest_p0_post, context.latest_target);
            EXPECT_EQ(before.retained_slot_token,
                      context.retained_slot_token);
            EXPECT_EQ(before.expected_count, expected_repeats);
            EXPECT_EQ(before.attempt_count, repeat);
            EXPECT_EQ(before.completion_count, repeat);
            EXPECT_FALSE(before.pre_open);
            const auto opened =
                lifecycle.ObserveTargetRepeatPreMetadata(pre);
            EXPECT_EQ(opened.decision,
                      PpDepthPredecessorCrossScopePairDecision::Idle);
            EXPECT_EQ(opened.target_repeat_attempt_count, repeat + 1);
            EXPECT_EQ(opened.target_repeat_completion_count, repeat);
            EXPECT_TRUE(opened.target_repeat_pre_open);
            EXPECT_EQ(opened.source_post_count, 1u);
            EXPECT_EQ(opened.target_pre_count, 1u);
            EXPECT_TRUE(opened.candidate_saved);
            EXPECT_EQ(opened.candidate_index,
                      before.candidate.candidate_index);
            EXPECT_FALSE(opened.select);
            const auto after_pre =
                lifecycle.SnapshotTargetRepeatRetainedState();
            EXPECT_EQ(after_pre.candidate, before.candidate);
            EXPECT_EQ(after_pre.latest_p0_post, before.latest_p0_post);
            EXPECT_EQ(after_pre.retained_slot_token,
                      before.retained_slot_token);
            EXPECT_EQ(after_pre.expected_count, before.expected_count);
            EXPECT_EQ(after_pre.attempt_count, repeat + 1);
            EXPECT_EQ(after_pre.completion_count, repeat);
            EXPECT_TRUE(after_pre.pre_open);

            const auto post =
                MakeCrossScopeTargetRepeatPost(h, context, pre);
            const auto completed =
                lifecycle.ObserveTargetRepeatPostMetadata(post);
            EXPECT_EQ(completed.decision,
                      PpDepthPredecessorCrossScopePairDecision::Idle);
            EXPECT_EQ(completed.target_repeat_attempt_count, repeat + 1);
            EXPECT_EQ(completed.target_repeat_completion_count, repeat + 1);
            EXPECT_FALSE(completed.target_repeat_pre_open);
            EXPECT_EQ(completed.source_post_count, 1u);
            EXPECT_EQ(completed.target_pre_count, 1u);
            EXPECT_TRUE(completed.candidate_saved);
            EXPECT_EQ(completed.candidate_index,
                      before.candidate.candidate_index);
            EXPECT_FALSE(completed.select);
            const auto after_post =
                lifecycle.SnapshotTargetRepeatRetainedState();
            EXPECT_EQ(after_post.candidate, before.candidate);
            EXPECT_EQ(after_post.latest_p0_post, post.post_endpoint);
            EXPECT_EQ(after_post.retained_slot_token,
                      before.retained_slot_token);
            EXPECT_EQ(after_post.expected_count, before.expected_count);
            EXPECT_EQ(after_post.attempt_count, repeat + 1);
            EXPECT_EQ(after_post.completion_count, repeat + 1);
            EXPECT_FALSE(after_post.pre_open);
            context.latest_target = post.post_endpoint;
        }

        auto current = context.latest_target.writer;
        for (u32 tail = 0; tail < tail_occurrences; ++tail) {
            const auto retained_before_tail =
                lifecycle.SnapshotTargetRepeatRetainedState();
            ASSERT_TRUE(lifecycle
                            .ObserveTailPre(
                                h.Intent(h.p1, current.mutation_epoch), current,
                                context.retained_slot_token)
                            .tail_exact);
            EXPECT_EQ(lifecycle.SnapshotTargetRepeatRetainedState(),
                      retained_before_tail);
            current = h.Stamp(h.p1, current.mutation_epoch + 1);
            ASSERT_TRUE(lifecycle.ObserveTailPost(current).tail_exact);
            EXPECT_EQ(lifecycle.SnapshotTargetRepeatRetainedState(),
                      retained_before_tail);
        }
        const auto retained_before_anchor =
            lifecycle.SnapshotTargetRepeatRetainedState();
        const auto selected = lifecycle.ObserveAnchor(h.anchor, current);
        EXPECT_TRUE(selected.select);
        EXPECT_EQ(selected.candidate_index,
                  context.candidate.candidate_index);
        EXPECT_EQ(selected.source_post_count, 1u);
        EXPECT_EQ(selected.target_pre_count, 1u);
        EXPECT_EQ(selected.target_repeat_attempt_count, expected_repeats);
        EXPECT_EQ(selected.target_repeat_completion_count, expected_repeats);
        EXPECT_EQ(lifecycle.SnapshotTargetRepeatRetainedState(),
                  retained_before_anchor);
    }
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     ArmedTargetRepeatPreRecomputesEveryEndpointScopeIntentCandidateAndBudgetAtom) {
    const CrossScopePairTestHarness h{};
    for (u32 mismatch = 0; mismatch < 68; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4};
        const auto context = ArmRootBoundTargetRepeat(lifecycle, h, 2, 2);
        const auto retained_before =
            lifecycle.SnapshotTargetRepeatRetainedState();
        auto pre = MakeCrossScopeTargetRepeatPre(h, context);
        switch (mismatch) {
        case 0: pre.stored_latest.valid = false; break;
        case 1: ++pre.stored_latest.writer.mutation_epoch; break;
        case 2: ++pre.stored_latest.guest_rendering_serial; break;
        case 3: ++pre.stored_latest.host_rendering_instance_id; break;
        case 4: pre.stored_latest.after_diagnostic_resume = false; break;
        case 5: pre.current_endpoint.valid = false; break;
        case 6: ++pre.current_endpoint.writer.link.uid; break;
        case 7: ++pre.current_endpoint.writer.range.base.layer; break;
        case 8: ++pre.current_endpoint.writer.backing_generation; break;
        case 9: ++pre.current_endpoint.writer.mutation_epoch; break;
        case 10: ++pre.current_endpoint.guest_rendering_serial; break;
        case 11: ++pre.current_endpoint.host_rendering_instance_id; break;
        case 12: pre.intent.hint = h.p1; break;
        case 13: ++pre.intent.link.uid; break;
        case 14: ++pre.intent.range.base.layer; break;
        case 15: ++pre.intent.backing_generation; break;
        case 16: ++pre.intent.mutation_epoch; break;
        case 17: pre.configured_effective_depth_write = false; break;
        case 18: pre.canonical_draw = false; break;
        case 19: pre.live_guest_rendering_serial = 0; break;
        case 20:
            pre.live_guest_rendering_serial =
                pre.current_endpoint.guest_rendering_serial;
            break;
        case 21: pre.live_host_rendering_instance_id = 0; break;
        case 22:
            pre.live_host_rendering_instance_id =
                pre.current_endpoint.host_rendering_instance_id;
            break;
        case 23: pre.live_rendering_active = false; break;
        case 24: pre.live_regular_origin = false; break;
        case 25: pre.live_diagnostic_origin = true; break;
        case 26: pre.candidate.valid = false; break;
        case 27: ++pre.candidate.generation; break;
        case 28: ++pre.candidate.candidate_index; break;
        case 29: pre.candidate.recorded_plane_mask = 0x1; break;
        case 30: ++pre.candidate.writer.link.uid; break;
        case 31: pre.slot.present = false; break;
        case 32: ++pre.slot.generation; break;
        case 33: ++pre.slot.candidate_index; break;
        case 34: pre.cross_open_collision = true; break;
        case 35: pre.stored_latest.producer_marked = false; break;
        case 36: pre.stored_latest.writer.hint.valid = false; break;
        case 37: ++pre.stored_latest.writer.hint.fragment_pgm_hash; break;
        case 38: pre.stored_latest.writer.link.id = {}; break;
        case 39: ++pre.stored_latest.writer.link.uid; break;
        case 40: ++pre.stored_latest.writer.range.extent.levels; break;
        case 41: ++pre.stored_latest.writer.backing_generation; break;
        case 42: pre.current_endpoint.producer_marked = false; break;
        case 43: pre.current_endpoint.after_diagnostic_resume = false; break;
        case 44: pre.current_endpoint.writer.hint.valid = false; break;
        case 45: ++pre.current_endpoint.writer.hint.fragment_pgm_hash; break;
        case 46: pre.current_endpoint.writer.link.id = {}; break;
        case 47: ++pre.current_endpoint.writer.link.uid; break;
        case 48: ++pre.current_endpoint.writer.range.extent.layers; break;
        case 49: pre.current_endpoint.guest_rendering_serial = 0; break;
        case 50: pre.current_endpoint.host_rendering_instance_id = 0; break;
        case 51: pre.candidate.writer.hint.valid = false; break;
        case 52: ++pre.candidate.writer.hint.fragment_pgm_hash; break;
        case 53: ++pre.candidate.writer.hint.draw.element_count; break;
        case 54: pre.candidate.writer.link.id = {}; break;
        case 55: ++pre.candidate.writer.link.uid; break;
        case 56: ++pre.candidate.writer.range.base.layer; break;
        case 57: ++pre.candidate.writer.range.extent.levels; break;
        case 58: ++pre.candidate.writer.backing_generation; break;
        case 59: ++pre.candidate.writer.mutation_epoch; break;
        case 60: ++pre.stored_latest.writer.hint.draw.element_count; break;
        case 61: ++pre.stored_latest.writer.range.base.layer; break;
        case 62: ++pre.current_endpoint.writer.hint.draw.instance_count; break;
        case 63: pre.stored_latest.writer.valid = false; break;
        case 64: pre.current_endpoint.writer.valid = false; break;
        case 65: pre.candidate.writer.valid = false; break;
        case 66: ++pre.retained_slot_token.slot; break;
        case 67: ++pre.retained_slot_token.generation; break;
        default: FAIL() << "unhandled target-repeat PRE mismatch";
        }
        const auto rejected =
            lifecycle.ObserveTargetRepeatPreMetadata(pre);
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(rejected.decision,
                  PpDepthPredecessorCrossScopePairDecision::
                      TargetRepeatMismatch);
        EXPECT_FALSE(rejected.target_repeat_pre_open);
        EXPECT_FALSE(rejected.select);
        const auto retained_after =
            lifecycle.SnapshotTargetRepeatRetainedState();
        EXPECT_EQ(retained_after.candidate, retained_before.candidate);
        EXPECT_EQ(retained_after.latest_p0_post,
                  retained_before.latest_p0_post);
        EXPECT_EQ(retained_after.retained_slot_token,
                  retained_before.retained_slot_token);
        EXPECT_EQ(retained_after.expected_count,
                  retained_before.expected_count);
        EXPECT_EQ(retained_after.completion_count,
                  retained_before.completion_count);
        EXPECT_FALSE(retained_after.pre_open);
        EXPECT_NE(lifecycle
                      .ObserveTargetRepeatPreMetadata(
                          MakeCrossScopeTargetRepeatPre(h, context))
                      .decision,
                  PpDepthPredecessorCrossScopePairDecision::Idle)
            << "a malformed PRE is terminal without fallback";
    }

    PpDepthPredecessorCrossScopePairLifecycle wrap{4};
    auto wrap_context = ArmRootBoundTargetRepeat(
        wrap, h, 2, 2, std::numeric_limits<u64>::max() - 1);
    auto wrap_pre = MakeCrossScopeTargetRepeatPre(h, wrap_context);
    EXPECT_EQ(wrap.ObserveTargetRepeatPreMetadata(wrap_pre).decision,
              PpDepthPredecessorCrossScopePairDecision::
                  TargetRepeatMismatch)
        << "a max mutation cannot open a successor correlation";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     ArmedTargetRepeatPostIsAtomicExactAndEveryDriftIsTerminal) {
    const CrossScopePairTestHarness h{};
    for (u32 mismatch = 0; mismatch < 44; ++mismatch) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4};
        const auto context = ArmRootBoundTargetRepeat(lifecycle, h, 2, 2);
        const auto pre = MakeCrossScopeTargetRepeatPre(h, context);
        ASSERT_TRUE(
            lifecycle.ObserveTargetRepeatPreMetadata(pre)
                .target_repeat_pre_open);
        const auto retained_before =
            lifecycle.SnapshotTargetRepeatRetainedState();
        auto post = MakeCrossScopeTargetRepeatPost(h, context, pre);
        switch (mismatch) {
        case 0: post.post_endpoint.valid = false; break;
        case 1: post.post_endpoint.producer_marked = false; break;
        case 2: ++post.post_endpoint.writer.hint.fragment_pgm_hash; break;
        case 3: ++post.post_endpoint.writer.hint.draw.element_count; break;
        case 4: ++post.post_endpoint.writer.link.uid; break;
        case 5: ++post.post_endpoint.writer.range.base.layer; break;
        case 6: ++post.post_endpoint.writer.backing_generation; break;
        case 7: --post.post_endpoint.writer.mutation_epoch; break;
        case 8: ++post.post_endpoint.writer.mutation_epoch; break;
        case 9: ++post.post_endpoint.guest_rendering_serial; break;
        case 10: ++post.post_endpoint.host_rendering_instance_id; break;
        case 11: post.post_endpoint.after_diagnostic_resume = true; break;
        case 12: post.configured_effective_depth_write = false; break;
        case 13: post.regular_origin = false; break;
        case 14: post.diagnostic_origin = true; break;
        case 15: post.first_writer.post_exact = false; break;
        case 16: post.first_writer.target_first_depth_writer = false; break;
        case 17: post.first_writer.target_scope_load = false; break;
        case 18: post.first_writer.target_scope_clear = true; break;
        case 19: post.candidate.valid = false; break;
        case 20: ++post.candidate.generation; break;
        case 21: ++post.candidate.candidate_index; break;
        case 22: post.candidate.recorded_plane_mask = 0x1; break;
        case 23: ++post.candidate.writer.link.uid; break;
        case 24: post.slot.present = false; break;
        case 25: ++post.slot.generation; break;
        case 26: ++post.slot.candidate_index; break;
        case 27: post.post_endpoint.writer.hint.valid = false; break;
        case 28: post.post_endpoint.writer.link.id = {}; break;
        case 29: ++post.post_endpoint.writer.range.extent.levels; break;
        case 30: post.post_endpoint.guest_rendering_serial = 0; break;
        case 31: post.post_endpoint.host_rendering_instance_id = 0; break;
        case 32: post.candidate.writer.hint.valid = false; break;
        case 33: ++post.candidate.writer.hint.fragment_pgm_hash; break;
        case 34: ++post.candidate.writer.hint.draw.instance_count; break;
        case 35: post.candidate.writer.link.id = {}; break;
        case 36: ++post.candidate.writer.range.base.layer; break;
        case 37: ++post.candidate.writer.range.extent.layers; break;
        case 38: ++post.candidate.writer.backing_generation; break;
        case 39: ++post.candidate.writer.mutation_epoch; break;
        case 40: post.post_endpoint.writer.valid = false; break;
        case 41: post.candidate.writer.valid = false; break;
        case 42: ++post.retained_slot_token.slot; break;
        case 43: ++post.retained_slot_token.generation; break;
        default: FAIL() << "unhandled target-repeat POST mismatch";
        }
        const auto rejected =
            lifecycle.ObserveTargetRepeatPostMetadata(post);
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(rejected.decision,
                  PpDepthPredecessorCrossScopePairDecision::
                      TargetRepeatMismatch);
        EXPECT_EQ(rejected.target_repeat_completion_count, 0u)
            << "a failed POST must not partially roll the endpoint";
        EXPECT_FALSE(rejected.select);
        const auto retained_after =
            lifecycle.SnapshotTargetRepeatRetainedState();
        EXPECT_EQ(retained_after.candidate, retained_before.candidate);
        EXPECT_EQ(retained_after.latest_p0_post,
                  retained_before.latest_p0_post);
        EXPECT_EQ(retained_after.retained_slot_token,
                  retained_before.retained_slot_token);
        EXPECT_EQ(retained_after.expected_count,
                  retained_before.expected_count);
        EXPECT_EQ(retained_after.attempt_count,
                  retained_before.attempt_count);
        EXPECT_EQ(retained_after.completion_count,
                  retained_before.completion_count);
        EXPECT_FALSE(retained_after.pre_open)
            << "terminal POST failure closes only metadata correlation";
        EXPECT_NE(lifecycle
                      .ObserveTargetRepeatPostMetadata(
                          MakeCrossScopeTargetRepeatPost(h, context, pre))
                      .decision,
                  PpDepthPredecessorCrossScopePairDecision::Idle)
            << "a malformed POST is terminal without fallback";
    }

    PpDepthPredecessorCrossScopePairLifecycle missing{4};
    const auto missing_context = ArmRootBoundTargetRepeat(missing, h, 2, 2);
    EXPECT_EQ(missing
                  .ObserveTargetRepeatPostMetadata(
                      MakeCrossScopeTargetRepeatPost(
                          h, missing_context,
                          MakeCrossScopeTargetRepeatPre(h, missing_context)))
                  .decision,
              PpDepthPredecessorCrossScopePairDecision::
                  MissingTargetRepeatPost);

    PpDepthPredecessorCrossScopePairLifecycle duplicate{4};
    const auto duplicate_context =
        ArmRootBoundTargetRepeat(duplicate, h, 2, 2);
    const auto duplicate_pre =
        MakeCrossScopeTargetRepeatPre(h, duplicate_context);
    ASSERT_TRUE(duplicate.ObserveTargetRepeatPreMetadata(duplicate_pre)
                    .target_repeat_pre_open);
    const auto duplicate_post =
        MakeCrossScopeTargetRepeatPost(h, duplicate_context, duplicate_pre);
    ASSERT_EQ(duplicate
                  .ObserveTargetRepeatPostMetadata(duplicate_post)
                  .target_repeat_completion_count,
              1u);
    EXPECT_EQ(duplicate
                  .ObserveTargetRepeatPostMetadata(duplicate_post)
                  .decision,
              PpDepthPredecessorCrossScopePairDecision::
                  DuplicateTargetRepeatPost);
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     ArmedTargetRepeatBudgetOrderingLatestTailAndIncompleteFrameFailClosed) {
    const CrossScopePairTestHarness h{};

    PpDepthPredecessorCrossScopePairLifecycle too_few{4};
    const auto too_few_context = ArmRootBoundTargetRepeat(too_few, h, 6, 6);
    EXPECT_EQ(too_few
                  .ObserveTailPre(
                      h.Intent(h.p1,
                               too_few_context.latest_target.writer
                                   .mutation_epoch),
                      too_few_context.latest_target.writer,
                      too_few_context.retained_slot_token)
                  .decision,
              PpDepthPredecessorCrossScopePairDecision::
                  TargetRepeatMismatch);

    for (const bool replace_slot : {false, true}) {
        PpDepthPredecessorCrossScopePairLifecycle token_drift{4};
        auto token_context =
            ArmRootBoundTargetRepeat(token_drift, h, 2, 2);
        const auto token_pre =
            MakeCrossScopeTargetRepeatPre(h, token_context);
        ASSERT_TRUE(token_drift
                        .ObserveTargetRepeatPreMetadata(token_pre)
                        .target_repeat_pre_open);
        const auto token_post = MakeCrossScopeTargetRepeatPost(
            h, token_context, token_pre);
        ASSERT_EQ(token_drift
                      .ObserveTargetRepeatPostMetadata(token_post)
                      .target_repeat_completion_count,
                  1u);
        token_context.latest_target = token_post.post_endpoint;
        auto wrong_token = token_context.retained_slot_token;
        if (replace_slot) {
            ++wrong_token.slot;
        } else {
            ++wrong_token.generation;
        }
        const auto retained_before =
            token_drift.SnapshotTargetRepeatRetainedState();
        const auto rejected = token_drift.ObserveTailPre(
            h.Intent(h.p1,
                     token_context.latest_target.writer.mutation_epoch),
            token_context.latest_target.writer, wrong_token);
        SCOPED_TRACE(replace_slot);
        EXPECT_EQ(rejected.decision,
                  PpDepthPredecessorCrossScopePairDecision::TailMismatch)
            << "slot replacement or reacquisition cannot bind the tail";
        EXPECT_FALSE(rejected.select);
        EXPECT_EQ(token_drift.SnapshotTargetRepeatRetainedState(),
                  retained_before);
        EXPECT_NE(token_drift
                      .ObserveTailPre(
                          h.Intent(
                              h.p1,
                              token_context.latest_target.writer
                                  .mutation_epoch),
                          token_context.latest_target.writer,
                          token_context.retained_slot_token)
                      .decision,
                  PpDepthPredecessorCrossScopePairDecision::Idle)
            << "a retained-slot mismatch is terminal without fallback";
    }

    PpDepthPredecessorCrossScopePairLifecycle incomplete{4};
    const auto incomplete_context =
        ArmRootBoundTargetRepeat(incomplete, h, 2, 2);
    ASSERT_TRUE(incomplete
                    .ObserveTargetRepeatPreMetadata(
                        MakeCrossScopeTargetRepeatPre(h, incomplete_context))
                    .target_repeat_pre_open);
    EXPECT_EQ(incomplete.EndFrame().decision,
              PpDepthPredecessorCrossScopePairDecision::
                  MissingTargetRepeatPost);

    PpDepthPredecessorCrossScopePairLifecycle duplicate_pre{4};
    const auto duplicate_pre_context =
        ArmRootBoundTargetRepeat(duplicate_pre, h, 2, 2);
    const auto duplicate_open =
        MakeCrossScopeTargetRepeatPre(h, duplicate_pre_context);
    ASSERT_TRUE(duplicate_pre
                    .ObserveTargetRepeatPreMetadata(duplicate_open)
                    .target_repeat_pre_open);
    EXPECT_EQ(duplicate_pre
                  .ObserveTargetRepeatPreMetadata(duplicate_open)
                  .decision,
              PpDepthPredecessorCrossScopePairDecision::
                  DuplicateTargetRepeatPre);

    PpDepthPredecessorCrossScopePairLifecycle over{4};
    auto over_context = ArmRootBoundTargetRepeat(over, h, 2, 2);
    const auto exact_pre = MakeCrossScopeTargetRepeatPre(h, over_context);
    ASSERT_TRUE(over.ObserveTargetRepeatPreMetadata(exact_pre)
                    .target_repeat_pre_open);
    const auto exact_post =
        MakeCrossScopeTargetRepeatPost(h, over_context, exact_pre);
    ASSERT_EQ(over.ObserveTargetRepeatPostMetadata(exact_post)
                  .target_repeat_completion_count,
              1u);
    over_context.latest_target = exact_post.post_endpoint;
    const auto over_budget = over.ObserveTargetRepeatPreMetadata(
        MakeCrossScopeTargetRepeatPre(h, over_context));
    EXPECT_EQ(over_budget.decision,
              PpDepthPredecessorCrossScopePairDecision::
                  TargetRepeatMismatch);
    EXPECT_EQ(over_budget.target_repeat_attempt_count, 2u);
    EXPECT_EQ(over_budget.target_repeat_completion_count, 1u);
    EXPECT_FALSE(over_budget.target_repeat_pre_open);

    PpDepthPredecessorCrossScopePairLifecycle stale{4};
    auto stale_context = ArmRootBoundTargetRepeat(stale, h, 2, 2);
    const auto stale_initial = stale_context.latest_target.writer;
    const auto stale_pre = MakeCrossScopeTargetRepeatPre(h, stale_context);
    ASSERT_TRUE(stale.ObserveTargetRepeatPreMetadata(stale_pre)
                    .target_repeat_pre_open);
    const auto stale_post =
        MakeCrossScopeTargetRepeatPost(h, stale_context, stale_pre);
    ASSERT_EQ(stale.ObserveTargetRepeatPostMetadata(stale_post)
                  .target_repeat_completion_count,
              1u);
    EXPECT_EQ(stale
                  .ObserveTailPre(
                      h.Intent(h.p1, stale_initial.mutation_epoch),
                      stale_initial, stale_context.retained_slot_token)
                  .decision,
              PpDepthPredecessorCrossScopePairDecision::TailMismatch)
        << "the superseded target endpoint cannot begin the tail";

    PpDepthPredecessorCrossScopePairLifecycle latest{4};
    auto latest_context = ArmRootBoundTargetRepeat(latest, h, 2, 2);
    const auto latest_pre = MakeCrossScopeTargetRepeatPre(h, latest_context);
    ASSERT_TRUE(latest.ObserveTargetRepeatPreMetadata(latest_pre)
                    .target_repeat_pre_open);
    const auto latest_post =
        MakeCrossScopeTargetRepeatPost(h, latest_context, latest_pre);
    ASSERT_EQ(latest.ObserveTargetRepeatPostMetadata(latest_post)
                  .target_repeat_completion_count,
              1u);
    EXPECT_TRUE(latest
                    .ObserveTailPre(
                        h.Intent(h.p1,
                                 latest_post.post_endpoint.writer
                                     .mutation_epoch),
                        latest_post.post_endpoint.writer,
                        latest_context.retained_slot_token)
                    .tail_exact)
        << "the atomically rolled latest endpoint begins the tail";
    latest_context.latest_target = latest_post.post_endpoint;
    EXPECT_EQ(latest
                  .ObserveTargetRepeatPreMetadata(
                      MakeCrossScopeTargetRepeatPre(h, latest_context))
                  .decision,
              PpDepthPredecessorCrossScopePairDecision::
                  TargetRepeatMismatch)
        << "a matched P0 after the P1 tail starts is terminal";

    PpDepthPredecessorCrossScopePairLifecycle after_anchor{4};
    auto anchor_context = ArmRootBoundTargetRepeat(after_anchor, h, 2, 2);
    const auto anchor_repeat_pre =
        MakeCrossScopeTargetRepeatPre(h, anchor_context);
    ASSERT_TRUE(after_anchor
                    .ObserveTargetRepeatPreMetadata(anchor_repeat_pre)
                    .target_repeat_pre_open);
    const auto anchor_repeat_post =
        MakeCrossScopeTargetRepeatPost(h, anchor_context,
                                       anchor_repeat_pre);
    ASSERT_EQ(after_anchor
                  .ObserveTargetRepeatPostMetadata(anchor_repeat_post)
                  .target_repeat_completion_count,
              1u);
    anchor_context.latest_target = anchor_repeat_post.post_endpoint;
    auto anchor_current = anchor_context.latest_target.writer;
    for (u32 tail = 0; tail < 2; ++tail) {
        ASSERT_TRUE(after_anchor
                        .ObserveTailPre(
                            h.Intent(h.p1, anchor_current.mutation_epoch),
                            anchor_current,
                            anchor_context.retained_slot_token)
                        .tail_exact);
        anchor_current = h.Stamp(h.p1, anchor_current.mutation_epoch + 1);
        ASSERT_TRUE(after_anchor.ObserveTailPost(anchor_current).tail_exact);
    }
    ASSERT_TRUE(after_anchor.ObserveAnchor(h.anchor, anchor_current).select);
    EXPECT_EQ(after_anchor
                  .ObserveTargetRepeatPreMetadata(
                      MakeCrossScopeTargetRepeatPre(h, anchor_context))
                  .decision,
              PpDepthPredecessorCrossScopePairDecision::
                  TargetRepeatMismatch)
        << "a P0 match after anchor selection is terminal and cannot fall back";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     TargetRepeatRuntimeDispatchIsRoleExclusiveMetadataOnlyAndPreservesFrameMask3) {
    using Dispatch = PpDepthPredecessorCrossScopeRuntimeDispatch;
    const PpDepthPredecessorCrossScopeRuntimeDispatchInput exact_pre{
        .phase = PpDepthPredecessorCrossScopePairPhase::Armed,
        .role = PpDepthPredecessorCrossScopePairRole::Tail,
        .pre_draw = true,
        .matches_target_repeat = true,
    };
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeRuntimeDispatch(exact_pre),
              Dispatch::TargetRepeatPreMetadata);
    auto exact_post = exact_pre;
    exact_post.pre_draw = false;
    exact_post.target_repeat_post_open = true;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeRuntimeDispatch(exact_post),
              Dispatch::TargetRepeatPostMetadata);

    for (u32 mismatch = 0; mismatch < 13; ++mismatch) {
        auto drift = exact_post;
        switch (mismatch) {
        case 0: drift.phase = PpDepthPredecessorCrossScopePairPhase::Learning; break;
        case 1: drift.role = PpDepthPredecessorCrossScopePairRole::TargetPre; break;
        case 2: drift.pre_draw = true; break;
        case 3: drift.matches_target_repeat = false; break;
        case 4: drift.source_reservation_open = true; break;
        case 5: drift.target_post_open = true; break;
        case 6: drift.tail_post_open = true; break;
        case 7: drift.cross_open_collision = true; break;
        case 8: drift.matches_source_post = true; break;
        case 9: drift.matches_target_pre = true; break;
        case 10: drift.matches_tail = true; break;
        case 11: drift.configured_anchor = true; break;
        case 12: drift.target_repeat_post_open = false; break;
        default: FAIL() << "unhandled target-repeat POST dispatch mismatch";
        }
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeRuntimeDispatch(drift),
                  Dispatch::Reject);
    }

    for (u32 mismatch = 0; mismatch < 12; ++mismatch) {
        auto drift = exact_pre;
        switch (mismatch) {
        case 0: drift.phase = PpDepthPredecessorCrossScopePairPhase::Learning; break;
        case 1: drift.role = PpDepthPredecessorCrossScopePairRole::TargetPre; break;
        case 2: drift.pre_draw = false; break;
        case 3: drift.matches_tail = true; break;
        case 4: drift.matches_target_pre = true; break;
        case 5: drift.configured_anchor = true; break;
        case 6: drift.tail_post_open = true; break;
        case 7: drift.cross_open_collision = true; break;
        case 8: drift.matches_source_post = true; break;
        case 9: drift.source_reservation_open = true; break;
        case 10: drift.target_post_open = true; break;
        case 11: drift.target_repeat_post_open = true; break;
        default: FAIL() << "unhandled target-repeat dispatch mismatch";
        }
        SCOPED_TRACE(mismatch);
        EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeRuntimeDispatch(drift),
                  Dispatch::Reject)
            << "non-cross-scope/modes 1-3 and conflicting roles never gain the metadata route";
    }

    for (const auto dispatch : {Dispatch::TargetRepeatPreMetadata,
                                Dispatch::TargetRepeatPostMetadata}) {
      for (const bool lifecycle_select : {false, true}) {
        const auto action = PlanPpDepthPredecessorCrossScopeRuntimeAction(
            dispatch, lifecycle_select);
        SCOPED_TRACE(static_cast<u32>(dispatch));
        SCOPED_TRACE(lifecycle_select);
        EXPECT_TRUE(action.metadata_only);
        EXPECT_EQ(action.endpoint_plane,
                  PpDepthPredecessorCrossScopeEndpointPlane::None);
        EXPECT_FALSE(action.frame_preview);
        EXPECT_FALSE(action.frame_complete);
        EXPECT_FALSE(action.direct_record);
        EXPECT_FALSE(action.record_plane);
        EXPECT_FALSE(action.tag_depth_candidate);
        EXPECT_FALSE(action.select_candidate);
        EXPECT_FALSE(action.reuse_retained_slot);
        EXPECT_FALSE(action.first_copy);
        EXPECT_EQ(action.require_before_draw,
                  dispatch == Dispatch::TargetRepeatPreMetadata);
        EXPECT_EQ(action.classify_first_writer,
                  dispatch == Dispatch::TargetRepeatPostMetadata);
      }
    }

    for (const u32 configured_hops : {1u, 2u, 3u}) {
        const auto isolated = PlanPpDepthPredecessorRuntimeFrame({
            .hint_mode = true,
            .configured_hops = configured_hops,
            .cross_scope_pair_ready = true,
            .prospective_capture = true,
        });
        SCOPED_TRACE(configured_hops);
        EXPECT_NE(isolated.path,
                  PpDepthPredecessorRuntimePath::CrossScopeArmed);
        EXPECT_FALSE(isolated.begin_cross_scope)
            << "modes 1-3 cannot enter the call site that dispatches target-repeat metadata";
    }

    const PpTerminalScopeDrawSelector draw{
        .kind = VideoCore::ImageColorScopeDrawKind::Direct,
        .indexed = true,
        .element_count = 12,
        .instance_count = 1,
        .sampled_images = 4,
    };
    const VideoCore::ImageColorScopePrivateLink link{VideoCore::ImageId{109},
                                                     10900};
    const PpUpstreamFeedbackPrePostPlan plan{
        .candidate_capacity = 4,
        .status = FinalGuestSurfaceStatus::Complete,
        .copy = true,
    };
    PpUpstreamFeedbackPrePostFrame frame{draw, 4};
    ASSERT_TRUE(frame.Arm(draw));
    ASSERT_TRUE(frame.Configure(plan));
    const auto pre = frame.Preview(link, draw);
    ASSERT_TRUE(pre.capture);
    frame.MarkCopied(pre.candidate_index, false);
    const auto post = frame.Complete(link, draw);
    ASSERT_TRUE(post.capture);
    frame.MarkCopied(post.candidate_index, true);
    ASSERT_EQ(frame.RecordedPlaneMask(post.candidate_index), 0x3u);
    FinalGuestSurfaceReadbackSlotPool retained_slot_pool;
    const auto retained_slot = retained_slot_pool.TryAcquire();
    ASSERT_TRUE(retained_slot.has_value());
    const auto retained_slot_before = *retained_slot;
    for (const auto dispatch : {Dispatch::TargetRepeatPreMetadata,
                                Dispatch::TargetRepeatPostMetadata}) {
        const auto action =
            PlanPpDepthPredecessorCrossScopeRuntimeAction(dispatch, false);
        if (action.record_plane) {
            frame.MarkCopied(post.candidate_index, action.plane_index != 0);
        }
        if (action.select_candidate) {
            static_cast<void>(frame.SelectCandidate(post.candidate_index));
        }
        EXPECT_EQ(frame.RecordedPlaneMask(post.candidate_index), 0x3u);
        EXPECT_EQ(*retained_slot, retained_slot_before)
            << "metadata-only actions cannot replace or reacquire the physical slot token";
    }
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     ArmedTargetRepeatSuccessFailureAnchorAndFrameResetClearOnlyCorrelationState) {
    const CrossScopePairTestHarness h{};
    PpDepthPredecessorCrossScopePairLifecycle success{4};
    auto context = ArmRootBoundTargetRepeat(success, h, 2, 2);
    const auto pre = MakeCrossScopeTargetRepeatPre(h, context);
    ASSERT_TRUE(success.ObserveTargetRepeatPreMetadata(pre)
                    .target_repeat_pre_open);
    const auto post = MakeCrossScopeTargetRepeatPost(h, context, pre);
    const auto completed = success.ObserveTargetRepeatPostMetadata(post);
    EXPECT_FALSE(completed.target_repeat_pre_open);
    EXPECT_EQ(completed.target_repeat_attempt_count, 1u);
    EXPECT_EQ(completed.target_repeat_completion_count, 1u);
    context.latest_target = post.post_endpoint;
    auto current = context.latest_target.writer;
    for (u32 tail = 0; tail < 2; ++tail) {
        ASSERT_TRUE(success
                        .ObserveTailPre(
                            h.Intent(h.p1, current.mutation_epoch), current,
                            context.retained_slot_token)
                        .tail_exact);
        current = h.Stamp(h.p1, current.mutation_epoch + 1);
        ASSERT_TRUE(success.ObserveTailPost(current).tail_exact);
    }
    const auto anchor = success.ObserveAnchor(h.anchor, current);
    ASSERT_TRUE(anchor.select);
    EXPECT_FALSE(anchor.target_repeat_pre_open);
    const auto ended = success.EndFrame();
    EXPECT_EQ(ended.expected_target_repeat_count, 1u);
    EXPECT_EQ(ended.target_repeat_attempt_count, 1u);
    EXPECT_EQ(ended.target_repeat_completion_count, 1u);
    EXPECT_FALSE(ended.target_repeat_pre_open);
    const auto next = success.BeginFrame();
    EXPECT_EQ(next.expected_target_repeat_count, 1u);
    EXPECT_EQ(next.target_repeat_attempt_count, 0u);
    EXPECT_EQ(next.target_repeat_completion_count, 0u);
    EXPECT_FALSE(next.target_repeat_pre_open);
    EXPECT_EQ(next.source_post_count, 0u);
    EXPECT_EQ(next.target_pre_count, 0u);
    EXPECT_FALSE(next.candidate_saved);

    PpDepthPredecessorCrossScopePairLifecycle rejected{4};
    const auto rejected_context =
        ArmRootBoundTargetRepeat(rejected, h, 2, 2);
    auto bad = MakeCrossScopeTargetRepeatPre(h, rejected_context);
    bad.canonical_draw = false;
    const auto failure = rejected.ObserveTargetRepeatPreMetadata(bad);
    EXPECT_EQ(failure.decision,
              PpDepthPredecessorCrossScopePairDecision::
                  TargetRepeatMismatch);
    EXPECT_FALSE(failure.target_repeat_pre_open);
    static_cast<void>(rejected.EndFrame());
    const auto retry = rejected.BeginFrame();
    EXPECT_EQ(retry.expected_target_repeat_count, 1u);
    EXPECT_EQ(retry.target_repeat_attempt_count, 0u);
    EXPECT_EQ(retry.target_repeat_completion_count, 0u);
    EXPECT_FALSE(retry.target_repeat_pre_open);

    const PpDepthPredecessorCrossScopeArmedP0RepeatProbeRuntimeFrameState
        dirty_runtime{
            .correlation_open = true,
            .evidence = {
                .attempt_count = 1,
                .unique_valid = true,
            },
        };
    EXPECT_EQ(ResetPpDepthPredecessorCrossScopeArmedP0RepeatProbeRuntimeFrame(
                  dirty_runtime),
              PpDepthPredecessorCrossScopeArmedP0RepeatProbeRuntimeFrameState{})
        << "the actual repeat open-draw correlation is cleared at the shared frame-reset seam";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     BootstrapRuntimeEvidenceResetsPerFrameAndAccumulatesOnlyTheMatchingEnd) {
    using Event = PpDepthPredecessorCrossScopeBootstrapRuntimeEvidenceEvent;
    const CrossScopePairTestHarness h{};
    const auto selected_proof =
        ClassifyPpDepthPredecessorCrossScopeMode3SelectedProof(
            h.Mode3Begin(), h.Mode3Selected());
    PpDepthPredecessorCrossScopeBootstrapRuntimeEvidence stale{
        .begin_phase = PpDepthPredecessorTwoHopPhase::GenerationWrap,
        .begin_decision = PpDepthPredecessorTwoHopDecision::GenerationWrap,
        .begin_chain_kind =
            PpDepthPredecessorTwoHopChainKind::DistinctPrefixBeforeSameWriter,
        .begin_occurrence_role = PpDepthPredecessorTwoHopOccurrenceRole::P1Tail,
        .begin_raw_armed = true,
        .readiness = PpDepthPredecessorCrossScopeBootstrapReadiness::Exact,
        .end_decision = PpDepthPredecessorTwoHopDecision::Selected,
        .selected_proof = selected_proof,
    };
    const auto reset = AccumulatePpDepthPredecessorCrossScopeBootstrapRuntimeEvidence(
        stale, {.event = Event::Reset});
    EXPECT_EQ(reset, PpDepthPredecessorCrossScopeBootstrapRuntimeEvidence{});
    EXPECT_EQ(AccumulatePpDepthPredecessorCrossScopeBootstrapRuntimeEvidence(
                  reset,
                  {
                      .event = Event::End,
                      .end_decision = PpDepthPredecessorTwoHopDecision::MissingP1,
                      .selected_proof = selected_proof,
                  }),
              reset)
        << "an End without this frame's requested Begin cannot revive stale evidence";

    const PpDepthPredecessorTwoHopResult begin{
        .phase = PpDepthPredecessorTwoHopPhase::LearnP2,
        .decision = PpDepthPredecessorTwoHopDecision::Idle,
        .chain_kind = PpDepthPredecessorTwoHopChainKind::Distinct,
        .occurrence_role = PpDepthPredecessorTwoHopOccurrenceRole::None,
        .raw_armed = false,
    };
    const auto begun = AccumulatePpDepthPredecessorCrossScopeBootstrapRuntimeEvidence(
        stale,
        {
            .event = Event::Begin,
            .begin = begin,
            .readiness =
                PpDepthPredecessorCrossScopeBootstrapReadiness::PairNotReady,
        });
    EXPECT_EQ(begun.begin_phase, begin.phase);
    EXPECT_EQ(begun.begin_decision, begin.decision);
    EXPECT_EQ(begun.begin_chain_kind, begin.chain_kind);
    EXPECT_EQ(begun.begin_occurrence_role, begin.occurrence_role);
    EXPECT_EQ(begun.begin_raw_armed, begin.raw_armed);
    EXPECT_EQ(begun.readiness,
              PpDepthPredecessorCrossScopeBootstrapReadiness::PairNotReady);
    EXPECT_EQ(begun.end_decision, PpDepthPredecessorTwoHopDecision::Idle)
        << "a new Begin replaces stale prior-frame End evidence";
    EXPECT_EQ(begun.selected_proof,
              PpDepthPredecessorCrossScopeMode3SelectedProof{})
        << "a new Begin replaces stale prior-frame selected proof";

    const auto exact_begun =
        AccumulatePpDepthPredecessorCrossScopeBootstrapRuntimeEvidence(
            {},
            {
                .event = Event::Begin,
                .begin = h.Mode3Begin(),
                .readiness =
                    PpDepthPredecessorCrossScopeBootstrapReadiness::Exact,
            });

    const auto ended = AccumulatePpDepthPredecessorCrossScopeBootstrapRuntimeEvidence(
        exact_begun,
        {
            .event = Event::End,
            .end_decision = PpDepthPredecessorTwoHopDecision::MissingP1,
            .selected_proof = selected_proof,
        });
    EXPECT_EQ(ended.begin_phase, exact_begun.begin_phase);
    EXPECT_EQ(ended.begin_decision, exact_begun.begin_decision);
    EXPECT_EQ(ended.begin_chain_kind, exact_begun.begin_chain_kind);
    EXPECT_EQ(ended.begin_occurrence_role,
              exact_begun.begin_occurrence_role);
    EXPECT_EQ(ended.begin_raw_armed, exact_begun.begin_raw_armed);
    EXPECT_EQ(ended.readiness, exact_begun.readiness);
    EXPECT_EQ(ended.end_decision, PpDepthPredecessorTwoHopDecision::MissingP1);
    EXPECT_EQ(ended.selected_proof, selected_proof);
    EXPECT_EQ(AccumulatePpDepthPredecessorCrossScopeBootstrapRuntimeEvidence(
                  ended, {.event = Event::Reset}),
              PpDepthPredecessorCrossScopeBootstrapRuntimeEvidence{})
        << "the next frame cannot inherit either Begin or End evidence";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     DispatchIsAnchorFirstAndKeepsAsymmetricEndpointAndMetadataRolesSeparate) {
    using Dispatch = PpDepthPredecessorCrossScopeRuntimeDispatch;
    const auto classify = [](PpDepthPredecessorCrossScopePairPhase phase,
                             PpDepthPredecessorCrossScopePairRole role, bool pre_draw,
                             bool configured_anchor, bool source, bool target, bool tail,
                             bool source_reservation_open = false,
                             bool target_post_open = false, bool tail_post_open = false,
                             bool cross_open_collision = false) {
        return ClassifyPpDepthPredecessorCrossScopeRuntimeDispatch({
            .phase = phase,
            .role = role,
            .pre_draw = pre_draw,
            .configured_anchor = configured_anchor,
            .matches_source_post = source,
            .matches_target_pre = target,
            .matches_tail = tail,
            .source_reservation_open = source_reservation_open,
            .target_post_open = target_post_open,
            .tail_post_open = tail_post_open,
            .cross_open_collision = cross_open_collision,
        });
    };

    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Learning,
                       PpDepthPredecessorCrossScopePairRole::TargetPre, true, false, false,
                       true, false),
              Dispatch::LearningTargetPre);
    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Armed,
                       PpDepthPredecessorCrossScopePairRole::SourcePost, true, false, true,
                       false, false),
              Dispatch::SourcePreReserve);
    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Armed,
                       PpDepthPredecessorCrossScopePairRole::SourcePost, false, false, true,
                       false, false, true),
              Dispatch::SourcePostPlane0);
    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Armed,
                       PpDepthPredecessorCrossScopePairRole::TargetPre, true, false, false,
                       true, false),
              Dispatch::TargetPrePlane1);
    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Armed,
                       PpDepthPredecessorCrossScopePairRole::Tail, false, false, false, true,
                       false, false, true),
              Dispatch::TargetPostFirstWriter);
    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Armed,
                       PpDepthPredecessorCrossScopePairRole::Tail, true, false, false, false,
                       true),
              Dispatch::TailPreMetadata);
    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Armed,
                       PpDepthPredecessorCrossScopePairRole::Tail, false, false, false, false,
                       true, false, false, true),
              Dispatch::TailPostMetadata);

    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Armed,
                       PpDepthPredecessorCrossScopePairRole::Tail, true, true, true, true,
                       true),
              Dispatch::Anchor)
        << "configured anchor dispatch must precede all endpoint shape matches";
    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Armed,
                       PpDepthPredecessorCrossScopePairRole::Tail, false, false, false, true,
                       false),
              Dispatch::Reject)
        << "P0 post without its exact pre-open is structural loss";
    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Armed,
                       PpDepthPredecessorCrossScopePairRole::Tail, false, false, false, false,
                       true),
              Dispatch::Reject)
        << "P1 post without its exact metadata pre-open is structural loss";
    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Armed,
                       PpDepthPredecessorCrossScopePairRole::TargetPre, true, false, false,
                       true, false, false, false, false, true),
              Dispatch::Reject)
        << "cross-open collisions fail closed instead of guessing an endpoint";

    EXPECT_EQ(classify(PpDepthPredecessorCrossScopePairPhase::Armed,
                       PpDepthPredecessorCrossScopePairRole::SourcePost, false, false, true,
                       false, false),
              Dispatch::Reject)
        << "S POST cannot create a late reservation after the producer executed";

    const auto reserve_action =
        PlanPpDepthPredecessorCrossScopeRuntimeAction(Dispatch::SourcePreReserve, false);
    EXPECT_TRUE(reserve_action.frame_preview);
    EXPECT_FALSE(reserve_action.frame_complete);
    EXPECT_FALSE(reserve_action.direct_record);
    EXPECT_FALSE(reserve_action.record_plane);
    EXPECT_TRUE(reserve_action.reject_restart);
    EXPECT_FALSE(reserve_action.tag_depth_candidate);

    const auto source_action =
        PlanPpDepthPredecessorCrossScopeRuntimeAction(Dispatch::SourcePostPlane0, false);
    EXPECT_EQ(source_action.endpoint_plane,
              PpDepthPredecessorCrossScopeEndpointPlane::SourcePostPlane0);
    EXPECT_EQ(source_action.plane_index, 0u);
    EXPECT_TRUE(source_action.record_plane);
    EXPECT_FALSE(source_action.frame_preview);
    EXPECT_TRUE(source_action.frame_complete);
    EXPECT_FALSE(source_action.direct_record);
    EXPECT_TRUE(source_action.require_after_producer_mark);
    EXPECT_FALSE(source_action.require_before_draw);
    EXPECT_FALSE(source_action.tag_depth_candidate);

    const auto target_action =
        PlanPpDepthPredecessorCrossScopeRuntimeAction(Dispatch::TargetPrePlane1, false);
    EXPECT_EQ(target_action.endpoint_plane,
              PpDepthPredecessorCrossScopeEndpointPlane::TargetPrePlane1);
    EXPECT_EQ(target_action.plane_index, 1u);
    EXPECT_TRUE(target_action.record_plane);
    EXPECT_FALSE(target_action.frame_preview);
    EXPECT_FALSE(target_action.frame_complete);
    EXPECT_TRUE(target_action.direct_record);
    EXPECT_FALSE(target_action.require_after_producer_mark);
    EXPECT_TRUE(target_action.require_before_draw);
    EXPECT_FALSE(target_action.tag_depth_candidate)
        << "the retained candidate writer stays S and is never retagged to P0";

    const auto p0_post = PlanPpDepthPredecessorCrossScopeRuntimeAction(
        Dispatch::TargetPostFirstWriter, false);
    EXPECT_FALSE(p0_post.record_plane);
    EXPECT_TRUE(p0_post.classify_first_writer);
    EXPECT_FALSE(p0_post.tag_depth_candidate);
    EXPECT_FALSE(p0_post.select_candidate);

    for (const auto tail_dispatch : {Dispatch::TailPreMetadata, Dispatch::TailPostMetadata}) {
        const auto tail_action =
            PlanPpDepthPredecessorCrossScopeRuntimeAction(tail_dispatch, false);
        EXPECT_TRUE(tail_action.metadata_only);
        EXPECT_FALSE(tail_action.record_plane);
        EXPECT_FALSE(tail_action.tag_depth_candidate);
        EXPECT_FALSE(tail_action.select_candidate);
    }
    EXPECT_FALSE(PlanPpDepthPredecessorCrossScopeRuntimeAction(Dispatch::Anchor, false)
                     .select_candidate);
    EXPECT_TRUE(PlanPpDepthPredecessorCrossScopeRuntimeAction(Dispatch::Anchor, true)
                    .select_candidate)
        << "selection is delayed until the lifecycle validates the exact anchor";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     FrameTransactionReservesAtSourcePreCompletesAtSourcePostAndDirectlyRecordsTargetPre) {
    const CrossScopePairTestHarness h{};
    const PpUpstreamFeedbackPrePostPlan plan{
        .candidate_capacity = 4,
        .status = FinalGuestSurfaceStatus::Complete,
        .copy = true,
    };
    PpUpstreamFeedbackPrePostFrame frame{h.source.draw, 4};
    ASSERT_TRUE(frame.Arm(h.source.draw));
    ASSERT_TRUE(frame.Configure(plan));

    const auto reservation = frame.Preview(h.link, h.source.draw);
    ASSERT_TRUE(IsExactPpDepthPredecessorCrossScopeSourceReservation(reservation));
    EXPECT_FALSE(reservation.restart);
    EXPECT_EQ(frame.RecordedPlaneMask(reservation.candidate_index), 0u)
        << "S PRE reserves ownership without copying any endpoint plane";

    const auto completion = frame.Complete(h.link, h.source.draw);
    ASSERT_TRUE(IsExactPpDepthPredecessorCrossScopeSourceCompletion(
        completion, reservation.candidate_index));
    ASSERT_EQ(completion.candidate_index, reservation.candidate_index);

    frame.MarkCopied(completion.candidate_index, false);
    EXPECT_EQ(frame.RecordedPlaneMask(completion.candidate_index), 0x1u)
        << "S POST is physical plane0 after the marked source producer";
    frame.MarkCopied(completion.candidate_index, true);
    EXPECT_EQ(frame.RecordedPlaneMask(completion.candidate_index), 0x3u)
        << "P0 PRE records physical plane1 directly without another registry operation";
    ASSERT_TRUE(frame.SelectCandidate(completion.candidate_index));

    const auto rolling = frame.Preview(h.link, h.source.draw);
    ASSERT_TRUE(rolling.restart)
        << "dynamic-selector Frame supports rolling, but specialized mode4 forbids it";
    EXPECT_FALSE(IsExactPpDepthPredecessorCrossScopeSourceReservation(rolling));

    PpUpstreamFeedbackPrePostFrame wrong_owner_frame{h.source.draw, 4};
    ASSERT_TRUE(wrong_owner_frame.Arm(h.source.draw));
    ASSERT_TRUE(wrong_owner_frame.Configure(plan));
    const auto wrong_reservation = wrong_owner_frame.Preview(h.link, h.source.draw);
    ASSERT_TRUE(IsExactPpDepthPredecessorCrossScopeSourceReservation(wrong_reservation));
    const auto wrong_owner = wrong_owner_frame.Complete(
        {VideoCore::ImageId{999}, h.link.uid + 1}, h.source.draw);
    EXPECT_FALSE(IsExactPpDepthPredecessorCrossScopeSourceCompletion(
        wrong_owner, wrong_reservation.candidate_index));
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     ArmedSourceIdentityIsRoleIndependentButRestartDispatchClosesAtTargetPre) {
    using Dispatch = PpDepthPredecessorCrossScopeRuntimeDispatch;
    const CrossScopePairTestHarness h{};
    PpDepthPredecessorCrossScopePairLifecycle lifecycle{4, 40};
    h.Learn(lifecycle);
    const auto frame = lifecycle.BeginFrame();
    const auto source_post = h.SourceEndpoint(700, 130, 600);
    const auto source_candidate =
        h.Candidate(frame.generation, 2, 0x1, source_post.writer);
    ASSERT_EQ(lifecycle.ObserveSourcePostComplete(source_post, source_candidate).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);

    EXPECT_FALSE(lifecycle.MatchesSourcePost(h.source.draw,
                                             h.source.fragment_pgm_hash))
        << "the legacy POST matcher remains role-gated";
    EXPECT_TRUE(lifecycle.MatchesArmedSource(h.source.draw,
                                             h.source.fragment_pgm_hash))
        << "an S-shaped PRE must remain visible after the first S completes";
    EXPECT_FALSE(lifecycle.MatchesArmedSource(h.p0.draw, h.p0.fragment_pgm_hash));

    const PpDepthPredecessorCrossScopeRuntimeDispatchInput restart_input{
        .phase = PpDepthPredecessorCrossScopePairPhase::Armed,
        .role = PpDepthPredecessorCrossScopePairRole::TargetPre,
        .pre_draw = true,
        .matches_source_post = true,
        .source_restart_allowed = true,
    };
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeRuntimeDispatch(restart_input),
              Dispatch::SourcePreRestart);

    auto target_closed = restart_input;
    target_closed.source_restart_allowed = false;
    target_closed.target_pre_attempted = true;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeRuntimeDispatch(target_closed),
              Dispatch::Reject)
        << "the first TargetPre attempt is terminal for source rolling";

    auto target_open = restart_input;
    target_open.target_post_open = true;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeRuntimeDispatch(target_open),
              Dispatch::Reject);
    auto source_open = restart_input;
    source_open.source_reservation_open = true;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeRuntimeDispatch(source_open),
              Dispatch::Reject);
    auto collision = restart_input;
    collision.cross_open_collision = true;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeRuntimeDispatch(collision),
              Dispatch::Reject);
    auto after_tail = restart_input;
    after_tail.role = PpDepthPredecessorCrossScopePairRole::Tail;
    EXPECT_EQ(ClassifyPpDepthPredecessorCrossScopeRuntimeDispatch(after_tail),
              Dispatch::Reject)
        << "role-independent source identity must reject, not disappear as Ignore";

    const auto restart_action =
        PlanPpDepthPredecessorCrossScopeRuntimeAction(Dispatch::SourcePreRestart,
                                                       false);
    EXPECT_TRUE(restart_action.frame_preview);
    EXPECT_TRUE(restart_action.require_before_draw);
    EXPECT_TRUE(restart_action.reuse_retained_slot);
    EXPECT_FALSE(restart_action.reject_restart);
    EXPECT_FALSE(restart_action.record_plane);

    const auto restart_post_action =
        PlanPpDepthPredecessorCrossScopeRuntimeAction(
            Dispatch::SourcePostRestartPlane0, false);
    EXPECT_EQ(restart_post_action.endpoint_plane,
              PpDepthPredecessorCrossScopeEndpointPlane::SourcePostPlane0);
    EXPECT_EQ(restart_post_action.plane_index, 0u);
    EXPECT_TRUE(restart_post_action.record_plane);
    EXPECT_TRUE(restart_post_action.reuse_retained_slot);
    EXPECT_FALSE(restart_post_action.first_copy)
        << "replacement S overwrites plane0 in the retained GPU slot";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     SourceRestartPreClassifierRequiresStoredWitnessCurrentWriterLineageAndFrameRestart) {
    const CrossScopePairTestHarness h{};
    const auto stored_source = h.SourceEndpoint(700, 130, 600);
    const auto stored_candidate = h.Candidate(41, 2, 0x1, stored_source.writer);
    const PpDepthPredecessorCrossScopeResumeWitness prior_resume{
        .source_post = stored_source,
        .source_candidate = stored_candidate,
        .candidate_capacity = 4,
        .resume_guest_rendering_serial = 130,
        .resume_host_rendering_instance_id = 601,
        .resume_rendering_active = true,
        .resume_diagnostic_origin = true,
        .resume_preserved_guest_serial = true,
        .valid = true,
    };
    const PpDepthPredecessorCrossScopeSourceRestartPreObservation exact{
        .stored_source_post = stored_source,
        .stored_source_candidate = stored_candidate,
        .prior_resume = prior_resume,
        .current_source_writer = stored_source.writer,
        .repeated_source_checkpoint = {
            .guest_rendering_serial = 130,
            .host_rendering_instance_id = 601,
            .rendering_active = true,
            .regular_origin = false,
            .diagnostic_origin = true,
        },
        .frame_output = h.link,
        .frame_preview = {
            .candidate_index = 2,
            .status = FinalGuestSurfaceStatus::Complete,
            .capture = true,
            .restart = true,
        },
        .expected_generation = 41,
        .candidate_capacity = 4,
        .recorded_plane_mask_before_preview = 0x1,
        .recorded_plane_mask_after_preview = 0,
        .retained_slot_present = true,
        .target_pre_attempted = false,
    };
    const auto classified =
        ClassifyPpDepthPredecessorCrossScopeSourceRestartPre(exact);
    EXPECT_TRUE(classified.stored_witness_exact);
    EXPECT_TRUE(classified.current_writer_exact);
    EXPECT_TRUE(classified.mutation_successor_available);
    EXPECT_TRUE(classified.rendering_lineage_exact);
    EXPECT_TRUE(classified.frame_restart_exact);
    EXPECT_TRUE(classified.rolling_window_exact);
    EXPECT_TRUE(classified.exact);

    for (u32 mismatch = 0; mismatch < 34; ++mismatch) {
        auto drift = exact;
        switch (mismatch) {
        case 0:
            drift.stored_source_post.valid = false;
            break;
        case 1:
            drift.stored_source_candidate.valid = false;
            break;
        case 2:
            drift.prior_resume.valid = false;
            break;
        case 3:
            ++drift.prior_resume.source_post.writer.mutation_epoch;
            break;
        case 4:
            ++drift.prior_resume.source_candidate.candidate_index;
            break;
        case 5:
            ++drift.prior_resume.candidate_capacity;
            break;
        case 6:
            ++drift.current_source_writer.hint.fragment_pgm_hash;
            break;
        case 7:
            ++drift.current_source_writer.link.uid;
            break;
        case 8:
            ++drift.current_source_writer.range.base.layer;
            break;
        case 9:
            ++drift.current_source_writer.backing_generation;
            break;
        case 10:
            ++drift.current_source_writer.mutation_epoch;
            break;
        case 11:
            drift.current_source_writer.valid = false;
            break;
        case 12:
            drift.stored_source_post.writer.mutation_epoch = 0;
            drift.prior_resume.source_post.writer.mutation_epoch = 0;
            drift.stored_source_candidate.writer.mutation_epoch = 0;
            drift.prior_resume.source_candidate.writer.mutation_epoch = 0;
            drift.current_source_writer.mutation_epoch = 0;
            break;
        case 13:
            drift.stored_source_post.writer.mutation_epoch =
                std::numeric_limits<u64>::max();
            drift.prior_resume.source_post.writer.mutation_epoch =
                std::numeric_limits<u64>::max();
            drift.stored_source_candidate.writer.mutation_epoch =
                std::numeric_limits<u64>::max();
            drift.prior_resume.source_candidate.writer.mutation_epoch =
                std::numeric_limits<u64>::max();
            drift.current_source_writer.mutation_epoch =
                std::numeric_limits<u64>::max();
            break;
        case 14:
            ++drift.repeated_source_checkpoint.guest_rendering_serial;
            break;
        case 15:
            ++drift.repeated_source_checkpoint.host_rendering_instance_id;
            break;
        case 16:
            drift.repeated_source_checkpoint.rendering_active = false;
            break;
        case 17:
            drift.repeated_source_checkpoint.diagnostic_origin = false;
            break;
        case 18:
            drift.repeated_source_checkpoint.regular_origin = true;
            break;
        case 19:
            ++drift.frame_output.uid;
            break;
        case 20:
            drift.frame_preview.capture = false;
            break;
        case 21:
            drift.frame_preview.restart = false;
            break;
        case 22:
            drift.frame_preview.status = FinalGuestSurfaceStatus::GapLoss;
            break;
        case 23:
            drift.frame_preview.loss.gap = 1;
            break;
        case 24:
            ++drift.frame_preview.candidate_index;
            break;
        case 25:
            drift.recorded_plane_mask_after_preview = 0x1;
            break;
        case 26:
            drift.retained_slot_present = false;
            break;
        case 27:
            drift.target_pre_attempted = true;
            break;
        case 28:
            drift.expected_generation = 0;
            break;
        case 29:
            drift.candidate_capacity = 0;
            break;
        case 30:
            drift.candidate_capacity =
                PpUpstreamFeedbackPrePostPlan::MaxCandidates + 1;
            break;
        case 31:
            drift.recorded_plane_mask_before_preview = 0;
            break;
        case 32:
            drift.repeated_source_checkpoint.host_rendering_instance_id = 0;
            break;
        case 33:
            drift.prior_resume.resume_host_rendering_instance_id = 0;
            drift.repeated_source_checkpoint.host_rendering_instance_id = 0;
            break;
        default:
            FAIL() << "unhandled source-restart PRE mismatch";
        }
        SCOPED_TRACE(mismatch);
        EXPECT_FALSE(
            ClassifyPpDepthPredecessorCrossScopeSourceRestartPre(drift).exact);
    }

    auto wrapped_pre = exact;
    wrapped_pre.prior_resume.resume_host_rendering_instance_id =
        std::numeric_limits<u64>::max();
    wrapped_pre.repeated_source_checkpoint.host_rendering_instance_id =
        std::numeric_limits<u64>::max();
    EXPECT_TRUE(
        ClassifyPpDepthPredecessorCrossScopeSourceRestartPre(wrapped_pre).exact)
        << "a live diagnostic source at max host is admissible because its copy-resume wraps to one";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     CompletedSameLinkFrameRestartReusesCandidateAndDestructivelyClearsOldPlanes) {
    const CrossScopePairTestHarness h{};
    const PpUpstreamFeedbackPrePostPlan plan{
        .candidate_capacity = 4,
        .status = FinalGuestSurfaceStatus::Complete,
        .copy = true,
    };
    PpUpstreamFeedbackPrePostFrame frame{h.source.draw, 4};
    ASSERT_TRUE(frame.Arm(h.source.draw));
    ASSERT_TRUE(frame.Configure(plan));
    const auto first_pre = frame.Preview(h.link, h.source.draw);
    ASSERT_TRUE(first_pre.capture);
    frame.MarkCopied(first_pre.candidate_index, false);
    ASSERT_TRUE(frame.Complete(h.link, h.source.draw).capture);
    ASSERT_EQ(frame.RecordedPlaneMask(first_pre.candidate_index), 0x1u);

    const u32 mask_before_restart =
        frame.RecordedPlaneMask(first_pre.candidate_index);
    const auto restart = frame.Preview(h.link, h.source.draw);
    ASSERT_TRUE(IsExactPpDepthPredecessorCrossScopeSourceRestart(
        restart, first_pre.candidate_index, mask_before_restart,
        frame.RecordedPlaneMask(first_pre.candidate_index), true));
    EXPECT_EQ(restart.candidate_index, first_pre.candidate_index);
    EXPECT_EQ(frame.RecordedPlaneMask(first_pre.candidate_index), 0u)
        << "Preview invalidates the superseded plane before replacement copy";
    ASSERT_TRUE(frame.Complete(h.link, h.source.draw).capture);
    frame.MarkCopied(restart.candidate_index, false);
    EXPECT_EQ(frame.RecordedPlaneMask(restart.candidate_index), 0x1u);

    PpUpstreamFeedbackPrePostFrame cross_link{h.source.draw, 4};
    ASSERT_TRUE(cross_link.Arm(h.source.draw));
    ASSERT_TRUE(cross_link.Configure(plan));
    const auto old_pre = cross_link.Preview(h.link, h.source.draw);
    cross_link.MarkCopied(old_pre.candidate_index, false);
    ASSERT_TRUE(cross_link.Complete(h.link, h.source.draw).capture);
    const VideoCore::ImageColorScopePrivateLink other{
        VideoCore::ImageId{999}, h.link.uid + 1};
    const auto new_link = cross_link.Preview(other, h.source.draw);
    EXPECT_FALSE(IsExactPpDepthPredecessorCrossScopeSourceRestart(
        new_link, old_pre.candidate_index, 0x1,
        cross_link.RecordedPlaneMask(old_pre.candidate_index), true));

    PpUpstreamFeedbackPrePostFrame incomplete{h.source.draw, 4};
    ASSERT_TRUE(incomplete.Arm(h.source.draw));
    ASSERT_TRUE(incomplete.Configure(plan));
    const auto incomplete_pre = incomplete.Preview(h.link, h.source.draw);
    const auto duplicate_pre = incomplete.Preview(h.link, h.source.draw);
    EXPECT_FALSE(IsExactPpDepthPredecessorCrossScopeSourceRestart(
        duplicate_pre, incomplete_pre.candidate_index, 0,
        incomplete.RecordedPlaneMask(incomplete_pre.candidate_index), true));

    PpUpstreamFeedbackPrePostFrame missing_plane0{h.source.draw, 4};
    ASSERT_TRUE(missing_plane0.Arm(h.source.draw));
    ASSERT_TRUE(missing_plane0.Configure(plan));
    const auto missing_plane0_pre =
        missing_plane0.Preview(h.link, h.source.draw);
    ASSERT_TRUE(missing_plane0.Complete(h.link, h.source.draw).capture)
        << "the registry entry is complete even though no physical plane was copied";
    const u32 missing_plane0_before = missing_plane0.RecordedPlaneMask(
        missing_plane0_pre.candidate_index);
    const auto structurally_restartable =
        missing_plane0.Preview(h.link, h.source.draw);
    ASSERT_TRUE(structurally_restartable.capture);
    ASSERT_TRUE(structurally_restartable.restart);
    EXPECT_FALSE(IsExactPpDepthPredecessorCrossScopeSourceRestart(
        structurally_restartable, missing_plane0_pre.candidate_index,
        missing_plane0_before,
        missing_plane0.RecordedPlaneMask(missing_plane0_pre.candidate_index),
        true))
        << "registry completion alone cannot stand in for physical mask1 ownership";

    PpUpstreamFeedbackPrePostFrame selected{h.source.draw, 4};
    ASSERT_TRUE(selected.Arm(h.source.draw));
    ASSERT_TRUE(selected.Configure(plan));
    const auto selected_pre = selected.Preview(h.link, h.source.draw);
    selected.MarkCopied(selected_pre.candidate_index, false);
    ASSERT_TRUE(selected.Complete(h.link, h.source.draw).capture);
    selected.MarkCopied(selected_pre.candidate_index, true);
    ASSERT_TRUE(selected.SelectCandidate(selected_pre.candidate_index));
    const auto selected_restart = selected.Preview(h.link, h.source.draw);
    ASSERT_TRUE(selected_restart.capture);
    ASSERT_TRUE(selected_restart.restart);
    ASSERT_EQ(selected_restart.candidate_index, selected_pre.candidate_index);
    const auto no_fallback = selected.Take(true);
    EXPECT_FALSE(no_fallback.copy);
    EXPECT_EQ(no_fallback.recorded_plane_mask, 0u)
        << "restart clears both the old selection and both copied-plane bits";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     SourceRestartPostRequiresExactMutationLineageCandidateAndSchedulerSuccessorResume) {
    const CrossScopePairTestHarness h{};
    const auto old_source = h.SourceEndpoint(700, 130, 600);
    const auto old_candidate = h.Candidate(41, 2, 0x1, old_source.writer);
    const PpDepthPredecessorCrossScopeResumeWitness prior_resume{
        .source_post = old_source,
        .source_candidate = old_candidate,
        .candidate_capacity = 4,
        .resume_guest_rendering_serial = 130,
        .resume_host_rendering_instance_id = 601,
        .resume_rendering_active = true,
        .resume_diagnostic_origin = true,
        .resume_preserved_guest_serial = true,
        .valid = true,
    };
    auto replacement = h.SourceEndpoint(701, 130, 601);
    replacement.after_diagnostic_resume = true;
    const auto replacement_candidate =
        h.Candidate(41, 2, 0x1, replacement.writer);
    const PpDepthPredecessorCrossScopeResumeWitness replacement_resume{
        .source_post = replacement,
        .source_candidate = replacement_candidate,
        .candidate_capacity = 4,
        .resume_guest_rendering_serial = 130,
        .resume_host_rendering_instance_id = 602,
        .resume_rendering_active = true,
        .resume_diagnostic_origin = true,
        .resume_preserved_guest_serial = true,
        .valid = true,
    };
    const PpDepthPredecessorCrossScopeSourceRestartPostObservation exact{
        .prior_resume = prior_resume,
        .endpoint = replacement,
        .candidate = replacement_candidate,
        .new_resume = replacement_resume,
        .expected_generation = 41,
        .candidate_capacity = 4,
        .expected_candidate_index = 2,
    };
    const auto classified =
        ClassifyPpDepthPredecessorCrossScopeSourceRestartPost(exact);
    EXPECT_TRUE(classified.endpoint_identity_exact);
    EXPECT_TRUE(classified.mutation_successor_exact);
    EXPECT_TRUE(classified.endpoint_lineage_exact);
    EXPECT_TRUE(classified.candidate_exact);
    EXPECT_TRUE(classified.resume_successor_exact);
    EXPECT_TRUE(classified.exact);

    EXPECT_EQ(NextPpDepthPredecessorCrossScopeHostInstanceId(601), 602u);
    EXPECT_EQ(NextPpDepthPredecessorCrossScopeHostInstanceId(
                  std::numeric_limits<u64>::max()),
              1u)
        << "Scheduler host-instance overflow skips zero and wraps to one";
    EXPECT_EQ(NextPpDepthPredecessorCrossScopeHostInstanceId(0), 0u)
        << "zero is invalid and cannot manufacture a lineage";

    for (u32 mismatch = 0; mismatch < 30; ++mismatch) {
        auto drift = exact;
        switch (mismatch) {
        case 0:
            drift.endpoint.valid = false;
            break;
        case 1:
            ++drift.endpoint.writer.hint.fragment_pgm_hash;
            break;
        case 2:
            ++drift.endpoint.writer.link.uid;
            break;
        case 3:
            ++drift.endpoint.writer.range.base.layer;
            break;
        case 4:
            ++drift.endpoint.writer.backing_generation;
            break;
        case 5:
            drift.endpoint.writer.mutation_epoch = 700;
            break;
        case 6:
            drift.endpoint.writer.mutation_epoch = 702;
            break;
        case 7:
            drift.endpoint.writer.mutation_epoch = 0;
            break;
        case 8:
            drift.endpoint.writer.mutation_epoch =
                std::numeric_limits<u64>::max();
            break;
        case 9:
            ++drift.endpoint.guest_rendering_serial;
            break;
        case 10:
            ++drift.endpoint.host_rendering_instance_id;
            break;
        case 11:
            drift.endpoint.after_diagnostic_resume = false;
            break;
        case 12:
            drift.endpoint.producer_marked = false;
            break;
        case 13:
            drift.candidate.valid = false;
            break;
        case 14:
            --drift.candidate.generation;
            break;
        case 15:
            ++drift.candidate.candidate_index;
            break;
        case 16:
            drift.candidate.recorded_plane_mask = 0;
            break;
        case 17:
            ++drift.candidate.writer.mutation_epoch;
            break;
        case 18:
            drift.new_resume.valid = false;
            break;
        case 19:
            ++drift.new_resume.source_post.writer.mutation_epoch;
            break;
        case 20:
            ++drift.new_resume.source_candidate.candidate_index;
            break;
        case 21:
            ++drift.new_resume.candidate_capacity;
            break;
        case 22:
            ++drift.new_resume.resume_guest_rendering_serial;
            break;
        case 23:
            drift.new_resume.resume_host_rendering_instance_id = 601;
            break;
        case 24:
            drift.new_resume.resume_host_rendering_instance_id = 603;
            break;
        case 25:
            drift.new_resume.resume_host_rendering_instance_id = 0;
            break;
        case 26:
            drift.new_resume.resume_rendering_active = false;
            break;
        case 27:
            drift.new_resume.resume_diagnostic_origin = false;
            break;
        case 28:
            drift.new_resume.resume_preserved_guest_serial = false;
            break;
        case 29:
            drift.expected_candidate_index = 3;
            break;
        default:
            FAIL() << "unhandled source-restart POST mismatch";
        }
        SCOPED_TRACE(mismatch);
        EXPECT_FALSE(
            ClassifyPpDepthPredecessorCrossScopeSourceRestartPost(drift).exact);
    }

    auto wrapped_prior = prior_resume;
    wrapped_prior.resume_host_rendering_instance_id =
        std::numeric_limits<u64>::max();
    const PpDepthPredecessorCrossScopeSourceRestartPreObservation wrapped_pre{
        .stored_source_post = old_source,
        .stored_source_candidate = old_candidate,
        .prior_resume = wrapped_prior,
        .current_source_writer = old_source.writer,
        .repeated_source_checkpoint = {
            .guest_rendering_serial = 130,
            .host_rendering_instance_id = std::numeric_limits<u64>::max(),
            .rendering_active = true,
            .regular_origin = false,
            .diagnostic_origin = true,
        },
        .frame_output = h.link,
        .frame_preview = {
            .candidate_index = 2,
            .status = FinalGuestSurfaceStatus::Complete,
            .capture = true,
            .restart = true,
        },
        .expected_generation = 41,
        .candidate_capacity = 4,
        .recorded_plane_mask_before_preview = 0x1,
        .recorded_plane_mask_after_preview = 0,
        .retained_slot_present = true,
    };
    ASSERT_TRUE(
        ClassifyPpDepthPredecessorCrossScopeSourceRestartPre(wrapped_pre).exact);
    auto wrapped_endpoint = replacement;
    wrapped_endpoint.host_rendering_instance_id =
        std::numeric_limits<u64>::max();
    auto wrapped_candidate = replacement_candidate;
    wrapped_candidate.writer = wrapped_endpoint.writer;
    auto wrapped_resume = replacement_resume;
    wrapped_resume.source_post = wrapped_endpoint;
    wrapped_resume.source_candidate = wrapped_candidate;
    wrapped_resume.resume_host_rendering_instance_id = 1;
    const auto wrapped = ClassifyPpDepthPredecessorCrossScopeSourceRestartPost({
        .prior_resume = wrapped_prior,
        .endpoint = wrapped_endpoint,
        .candidate = wrapped_candidate,
        .new_resume = wrapped_resume,
        .expected_generation = 41,
        .candidate_capacity = 4,
        .expected_candidate_index = 2,
    });
    EXPECT_TRUE(wrapped.resume_successor_exact);
    EXPECT_TRUE(wrapped.exact);
    wrapped_resume.resume_host_rendering_instance_id = 2;
    EXPECT_FALSE(ClassifyPpDepthPredecessorCrossScopeSourceRestartPost({
                     .prior_resume = wrapped_prior,
                     .endpoint = wrapped_endpoint,
                     .candidate = wrapped_candidate,
                     .new_resume = wrapped_resume,
                     .expected_generation = 41,
                     .candidate_capacity = 4,
                     .expected_candidate_index = 2,
                 })
                     .exact)
        << "a merely distinct post-wrap host is not the Scheduler successor";

    const auto initial_copy =
        PlanPpDepthPredecessorCrossScopeSourcePlaneCopy(false);
    EXPECT_FALSE(initial_copy.reuse_retained_slot);
    EXPECT_TRUE(initial_copy.first_copy);
    EXPECT_EQ(initial_copy.plane_index, 0u);
    const auto restart_copy =
        PlanPpDepthPredecessorCrossScopeSourcePlaneCopy(true);
    EXPECT_TRUE(restart_copy.reuse_retained_slot);
    EXPECT_FALSE(restart_copy.first_copy);
    EXPECT_EQ(restart_copy.plane_index, 0u);
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     SourceRestartLifecycleInstallsOnlyTheLatestOfMultipleExactPreTargetSources) {
    const CrossScopePairTestHarness h{};
    PpDepthPredecessorCrossScopePairLifecycle lifecycle{4, 40};
    h.Learn(lifecycle);
    const auto frame = lifecycle.BeginFrame();
    const auto first = h.SourceEndpoint(700, 130, 600);
    const auto first_candidate =
        h.Candidate(frame.generation, 2, 0x1, first.writer);
    ASSERT_EQ(lifecycle.ObserveSourcePostComplete(first, first_candidate).role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    PpDepthPredecessorCrossScopeResumeWitness first_resume{
        .source_post = first,
        .source_candidate = first_candidate,
        .candidate_capacity = 4,
        .resume_guest_rendering_serial = 130,
        .resume_host_rendering_instance_id = 601,
        .resume_rendering_active = true,
        .resume_diagnostic_origin = true,
        .resume_preserved_guest_serial = true,
        .valid = true,
    };
    const auto make_pre = [&](const PpDepthPredecessorEndpointStamp& stored,
                              const PpDepthPredecessorCandidateStamp& candidate,
                              const PpDepthPredecessorCrossScopeResumeWitness& resume) {
        return PpDepthPredecessorCrossScopeSourceRestartPreObservation{
            .stored_source_post = stored,
            .stored_source_candidate = candidate,
            .prior_resume = resume,
            .current_source_writer = stored.writer,
            .repeated_source_checkpoint = {
                .guest_rendering_serial = resume.resume_guest_rendering_serial,
                .host_rendering_instance_id = resume.resume_host_rendering_instance_id,
                .rendering_active = true,
                .regular_origin = false,
                .diagnostic_origin = true,
            },
            .frame_output = h.link,
            .frame_preview = {
                .candidate_index = candidate.candidate_index,
                .status = FinalGuestSurfaceStatus::Complete,
                .capture = true,
                .restart = true,
            },
            .expected_generation = frame.generation,
            .candidate_capacity = 4,
            .recorded_plane_mask_before_preview = 0x1,
            .recorded_plane_mask_after_preview = 0,
            .retained_slot_present = true,
        };
    };
    auto first_begin = lifecycle.BeginSourcePostRestart(
        make_pre(first, first_candidate, first_resume));
    EXPECT_EQ(first_begin.role, PpDepthPredecessorCrossScopePairRole::SourcePost);
    EXPECT_EQ(first_begin.source_post_count, 0u);
    EXPECT_EQ(first_begin.source_restart_count, 0u);
    EXPECT_TRUE(first_begin.source_restart_open);
    EXPECT_FALSE(lifecycle.MatchesStoredSourcePost(first))
        << "Begin destructively invalidates the superseded endpoint";

    auto second = h.SourceEndpoint(701, 130, 601);
    second.after_diagnostic_resume = true;
    const auto second_candidate =
        h.Candidate(frame.generation, 2, 0x1, second.writer);
    PpDepthPredecessorCrossScopeResumeWitness second_resume{
        .source_post = second,
        .source_candidate = second_candidate,
        .candidate_capacity = 4,
        .resume_guest_rendering_serial = 130,
        .resume_host_rendering_instance_id = 602,
        .resume_rendering_active = true,
        .resume_diagnostic_origin = true,
        .resume_preserved_guest_serial = true,
        .valid = true,
    };
    const auto first_replaced = lifecycle.ObserveSourcePostRestartComplete(
        second, second_candidate, second_resume);
    EXPECT_EQ(first_replaced.role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    EXPECT_EQ(first_replaced.source_post_count, 1u);
    EXPECT_EQ(first_replaced.source_restart_count, 1u);
    EXPECT_FALSE(first_replaced.source_restart_open);
    EXPECT_TRUE(lifecycle.MatchesStoredSourcePost(second));
    EXPECT_FALSE(lifecycle.MatchesStoredSourcePost(first));

    const auto second_begin = lifecycle.BeginSourcePostRestart(
        make_pre(second, second_candidate, second_resume));
    ASSERT_TRUE(second_begin.source_restart_open);
    auto third = h.SourceEndpoint(702, 130, 602);
    third.after_diagnostic_resume = true;
    const auto third_candidate =
        h.Candidate(frame.generation, 2, 0x1, third.writer);
    const PpDepthPredecessorCrossScopeResumeWitness third_resume{
        .source_post = third,
        .source_candidate = third_candidate,
        .candidate_capacity = 4,
        .resume_guest_rendering_serial = 130,
        .resume_host_rendering_instance_id = 603,
        .resume_rendering_active = true,
        .resume_diagnostic_origin = true,
        .resume_preserved_guest_serial = true,
        .valid = true,
    };
    const auto second_replaced = lifecycle.ObserveSourcePostRestartComplete(
        third, third_candidate, third_resume);
    EXPECT_EQ(second_replaced.source_post_count, 1u);
    EXPECT_EQ(second_replaced.source_restart_count, 2u);
    EXPECT_TRUE(lifecycle.MatchesStoredSourcePost(third));
    EXPECT_FALSE(lifecycle.MatchesStoredSourcePost(second));

    auto latest_target = h.Boundary(third, 702, third_candidate);
    latest_target.resume_guest_rendering_serial = 130;
    latest_target.resume_host_rendering_instance_id = 603;
    latest_target.target_guest_rendering_serial = 131;
    latest_target.target_host_rendering_instance_id = 604;
    EXPECT_TRUE(lifecycle.ObserveTargetPre(latest_target).boundary_exact)
        << "TargetPre binds only to the latest completed replacement";
    EXPECT_FALSE(lifecycle.CanBeginSourcePostRestart())
        << "the first TargetPre attempt permanently closes source rolling";

    u32 restart_count = std::numeric_limits<u32>::max() - 1;
    ASSERT_TRUE(TryIncrementPpDepthPredecessorCrossScopeSourceRestartCount(
        restart_count));
    EXPECT_EQ(restart_count, std::numeric_limits<u32>::max());
    EXPECT_FALSE(TryIncrementPpDepthPredecessorCrossScopeSourceRestartCount(
        restart_count));
    EXPECT_EQ(restart_count, std::numeric_limits<u32>::max());
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     InvalidSourceRestartBeginDestructivelyRemovesTheOldSourceWithoutFallback) {
    const CrossScopePairTestHarness h{};
    for (u32 failure = 0; failure < 13; ++failure) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4, 50};
        h.Learn(lifecycle);
        const auto frame = lifecycle.BeginFrame();
        const auto old_source = h.SourceEndpoint(800, 140, 700);
        const auto old_candidate =
            h.Candidate(frame.generation, 1, 0x1, old_source.writer);
        ASSERT_EQ(lifecycle.ObserveSourcePostComplete(old_source, old_candidate).role,
                  PpDepthPredecessorCrossScopePairRole::TargetPre);
        const PpDepthPredecessorCrossScopeResumeWitness old_resume{
            .source_post = old_source,
            .source_candidate = old_candidate,
            .candidate_capacity = 4,
            .resume_guest_rendering_serial = 140,
            .resume_host_rendering_instance_id = 701,
            .resume_rendering_active = true,
            .resume_diagnostic_origin = true,
            .resume_preserved_guest_serial = true,
            .valid = true,
        };
        PpDepthPredecessorCrossScopeSourceRestartPreObservation attempt{
            .stored_source_post = old_source,
            .stored_source_candidate = old_candidate,
            .prior_resume = old_resume,
            .current_source_writer = old_source.writer,
            .repeated_source_checkpoint = {
                .guest_rendering_serial = 140,
                .host_rendering_instance_id = 701,
                .rendering_active = true,
                .regular_origin = false,
                .diagnostic_origin = true,
            },
            .frame_output = h.link,
            .frame_preview = {
                .candidate_index = 1,
                .status = FinalGuestSurfaceStatus::Complete,
                .capture = true,
                .restart = true,
            },
            .expected_generation = frame.generation,
            .candidate_capacity = 4,
            .recorded_plane_mask_before_preview = 0x1,
            .recorded_plane_mask_after_preview = 0,
            .retained_slot_present = true,
        };
        switch (failure) {
        case 0:
            ++attempt.frame_output.uid;
            break;
        case 1:
            attempt.frame_preview.restart = false;
            break;
        case 2:
            ++attempt.frame_preview.candidate_index;
            break;
        case 3:
            --attempt.stored_source_candidate.generation;
            break;
        case 4:
            ++attempt.prior_resume.source_candidate.candidate_index;
            break;
        case 5:
            ++attempt.current_source_writer.mutation_epoch;
            break;
        case 6:
            ++attempt.repeated_source_checkpoint.guest_rendering_serial;
            break;
        case 7:
            ++attempt.repeated_source_checkpoint.host_rendering_instance_id;
            break;
        case 8:
            attempt.recorded_plane_mask_after_preview = 0x1;
            break;
        case 9:
            attempt.retained_slot_present = false;
            break;
        case 10:
            attempt.target_pre_attempted = true;
            break;
        case 11:
            attempt.stored_source_post.writer.mutation_epoch =
                std::numeric_limits<u64>::max();
            attempt.stored_source_candidate.writer.mutation_epoch =
                std::numeric_limits<u64>::max();
            attempt.prior_resume.source_post.writer.mutation_epoch =
                std::numeric_limits<u64>::max();
            attempt.prior_resume.source_candidate.writer.mutation_epoch =
                std::numeric_limits<u64>::max();
            attempt.current_source_writer.mutation_epoch =
                std::numeric_limits<u64>::max();
            break;
        case 12:
            attempt.frame_preview.loss.gap = 1;
            break;
        default:
            FAIL() << "unhandled destructive restart-begin failure";
        }

        SCOPED_TRACE(failure);
        const auto rejected = lifecycle.BeginSourcePostRestart(attempt);
        EXPECT_NE(rejected.decision,
                  PpDepthPredecessorCrossScopePairDecision::Idle);
        EXPECT_FALSE(rejected.source_restart_open);
        EXPECT_EQ(rejected.source_post_count, 0u);
        EXPECT_FALSE(lifecycle.MatchesStoredSourcePost(old_source))
            << "recognizing a restart attempt invalidates the old source even when proof fails";
        auto old_target = h.Boundary(old_source, 800, old_candidate);
        old_target.resume_guest_rendering_serial = 140;
        old_target.resume_host_rendering_instance_id = 701;
        EXPECT_FALSE(lifecycle.ObserveTargetPre(old_target).boundary_exact);
    }
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     InvalidOrIncompleteSourceReplacementCannotRestoreTheSupersededSource) {
    const CrossScopePairTestHarness h{};
    for (u32 failure = 0; failure < 22; ++failure) {
        PpDepthPredecessorCrossScopePairLifecycle lifecycle{4, 60};
        h.Learn(lifecycle);
        const auto frame = lifecycle.BeginFrame();
        const auto old_source = h.SourceEndpoint(900, 150, 800);
        const auto old_candidate =
            h.Candidate(frame.generation, 3, 0x1, old_source.writer);
        ASSERT_EQ(lifecycle.ObserveSourcePostComplete(old_source, old_candidate).role,
                  PpDepthPredecessorCrossScopePairRole::TargetPre);
        const PpDepthPredecessorCrossScopeResumeWitness old_resume{
            .source_post = old_source,
            .source_candidate = old_candidate,
            .candidate_capacity = 4,
            .resume_guest_rendering_serial = 150,
            .resume_host_rendering_instance_id = 801,
            .resume_rendering_active = true,
            .resume_diagnostic_origin = true,
            .resume_preserved_guest_serial = true,
            .valid = true,
        };
        const PpDepthPredecessorCrossScopeSourceRestartPreObservation begin{
            .stored_source_post = old_source,
            .stored_source_candidate = old_candidate,
            .prior_resume = old_resume,
            .current_source_writer = old_source.writer,
            .repeated_source_checkpoint = {
                .guest_rendering_serial = 150,
                .host_rendering_instance_id = 801,
                .rendering_active = true,
                .regular_origin = false,
                .diagnostic_origin = true,
            },
            .frame_output = h.link,
            .frame_preview = {
                .candidate_index = 3,
                .status = FinalGuestSurfaceStatus::Complete,
                .capture = true,
                .restart = true,
            },
            .expected_generation = frame.generation,
            .candidate_capacity = 4,
            .recorded_plane_mask_before_preview = 0x1,
            .recorded_plane_mask_after_preview = 0,
            .retained_slot_present = true,
        };
        ASSERT_TRUE(lifecycle.BeginSourcePostRestart(begin).source_restart_open);
        auto replacement = h.SourceEndpoint(901, 150, 801);
        replacement.after_diagnostic_resume = true;
        auto replacement_candidate =
            h.Candidate(frame.generation, 3, 0x1, replacement.writer);
        PpDepthPredecessorCrossScopeResumeWitness replacement_resume{
            .source_post = replacement,
            .source_candidate = replacement_candidate,
            .candidate_capacity = 4,
            .resume_guest_rendering_serial = 150,
            .resume_host_rendering_instance_id = 802,
            .resume_rendering_active = true,
            .resume_diagnostic_origin = true,
            .resume_preserved_guest_serial = true,
            .valid = true,
        };
        switch (failure) {
        case 0:
            replacement.valid = false;
            break;
        case 1:
            ++replacement.writer.hint.fragment_pgm_hash;
            break;
        case 2:
            ++replacement.writer.link.uid;
            break;
        case 3:
            ++replacement.writer.range.base.layer;
            break;
        case 4:
            ++replacement.writer.backing_generation;
            break;
        case 5:
            replacement.writer.mutation_epoch = 900;
            break;
        case 6:
            replacement.writer.mutation_epoch = 902;
            break;
        case 7:
            ++replacement.guest_rendering_serial;
            break;
        case 8:
            ++replacement.host_rendering_instance_id;
            break;
        case 9:
            replacement.after_diagnostic_resume = false;
            break;
        case 10:
            replacement_candidate.valid = false;
            break;
        case 11:
            --replacement_candidate.generation;
            break;
        case 12:
            replacement_candidate.candidate_index = 2;
            break;
        case 13:
            replacement_candidate.recorded_plane_mask = 0x3;
            break;
        case 14:
            ++replacement_candidate.writer.mutation_epoch;
            break;
        case 15:
            replacement_resume.valid = false;
            break;
        case 16:
            ++replacement_resume.resume_guest_rendering_serial;
            break;
        case 17:
            replacement_resume.resume_host_rendering_instance_id = 801;
            break;
        case 18:
            replacement_resume.resume_host_rendering_instance_id = 803;
            break;
        case 19:
            replacement_resume.resume_rendering_active = false;
            break;
        case 20:
            replacement_resume.resume_diagnostic_origin = false;
            break;
        case 21:
            ++replacement_resume.source_candidate.candidate_index;
            break;
        default:
            FAIL() << "unhandled destructive restart-complete failure";
        }

        SCOPED_TRACE(failure);
        const auto rejected = lifecycle.ObserveSourcePostRestartComplete(
            replacement, replacement_candidate, replacement_resume);
        EXPECT_NE(rejected.decision,
                  PpDepthPredecessorCrossScopePairDecision::Idle);
        EXPECT_FALSE(rejected.source_restart_open);
        EXPECT_EQ(rejected.source_post_count, 0u);
        EXPECT_FALSE(lifecycle.MatchesStoredSourcePost(old_source));
        EXPECT_FALSE(lifecycle.MatchesStoredSourcePost(replacement));
        auto stale_target = h.Boundary(old_source, 900, old_candidate);
        stale_target.resume_guest_rendering_serial = 150;
        stale_target.resume_host_rendering_instance_id = 801;
        stale_target.target_guest_rendering_serial = 151;
        stale_target.target_host_rendering_instance_id = 802;
        EXPECT_FALSE(lifecycle.ObserveTargetPre(stale_target).boundary_exact)
            << "replacement failure cannot revive the destructively cleared source";
    }

    PpDepthPredecessorCrossScopePairLifecycle incomplete{4, 70};
    h.Learn(incomplete);
    const auto incomplete_frame = incomplete.BeginFrame();
    const auto incomplete_old = h.SourceEndpoint(1000, 160, 900);
    const auto incomplete_candidate = h.Candidate(
        incomplete_frame.generation, 0, 0x1, incomplete_old.writer);
    ASSERT_EQ(incomplete
                  .ObserveSourcePostComplete(incomplete_old,
                                             incomplete_candidate)
                  .role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    const PpDepthPredecessorCrossScopeResumeWitness incomplete_resume{
        .source_post = incomplete_old,
        .source_candidate = incomplete_candidate,
        .candidate_capacity = 4,
        .resume_guest_rendering_serial = 160,
        .resume_host_rendering_instance_id = 901,
        .resume_rendering_active = true,
        .resume_diagnostic_origin = true,
        .resume_preserved_guest_serial = true,
        .valid = true,
    };
    ASSERT_TRUE(incomplete
                    .BeginSourcePostRestart({
                        .stored_source_post = incomplete_old,
                        .stored_source_candidate = incomplete_candidate,
                        .prior_resume = incomplete_resume,
                        .current_source_writer = incomplete_old.writer,
                        .repeated_source_checkpoint = {
                            .guest_rendering_serial = 160,
                            .host_rendering_instance_id = 901,
                            .rendering_active = true,
                            .diagnostic_origin = true,
                        },
                        .frame_output = h.link,
                        .frame_preview = {
                            .candidate_index = 0,
                            .status = FinalGuestSurfaceStatus::Complete,
                            .capture = true,
                            .restart = true,
                        },
                        .expected_generation = incomplete_frame.generation,
                        .candidate_capacity = 4,
                        .recorded_plane_mask_before_preview = 0x1,
                        .recorded_plane_mask_after_preview = 0,
                        .retained_slot_present = true,
                    })
                    .source_restart_open);
    const auto abandoned = incomplete.EndFrame();
    EXPECT_NE(abandoned.decision,
              PpDepthPredecessorCrossScopePairDecision::Idle);
    EXPECT_EQ(abandoned.source_post_count, 0u);
    EXPECT_FALSE(incomplete.MatchesStoredSourcePost(incomplete_old));
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     DuplicateRestartCompleteAndOlderTargetOrPostTargetRestartFailClosed) {
    const CrossScopePairTestHarness h{};
    const auto prepare = [&](PpDepthPredecessorCrossScopePairLifecycle& lifecycle,
                             PpDepthPredecessorEndpointStamp& source,
                             PpDepthPredecessorCandidateStamp& candidate,
                             PpDepthPredecessorCrossScopeResumeWitness& resume) {
        h.Learn(lifecycle);
        const auto frame = lifecycle.BeginFrame();
        source = h.SourceEndpoint(1100, 170, 1000);
        candidate = h.Candidate(frame.generation, 1, 0x1, source.writer);
        ASSERT_EQ(lifecycle.ObserveSourcePostComplete(source, candidate).role,
                  PpDepthPredecessorCrossScopePairRole::TargetPre);
        resume = {
            .source_post = source,
            .source_candidate = candidate,
            .candidate_capacity = 4,
            .resume_guest_rendering_serial = 170,
            .resume_host_rendering_instance_id = 1001,
            .resume_rendering_active = true,
            .resume_diagnostic_origin = true,
            .resume_preserved_guest_serial = true,
            .valid = true,
        };
    };

    PpDepthPredecessorCrossScopePairLifecycle duplicate{4, 80};
    PpDepthPredecessorEndpointStamp duplicate_source{};
    PpDepthPredecessorCandidateStamp duplicate_candidate{};
    PpDepthPredecessorCrossScopeResumeWitness duplicate_resume{};
    prepare(duplicate, duplicate_source, duplicate_candidate,
            duplicate_resume);
    auto impossible_replacement = h.SourceEndpoint(1101, 170, 1001);
    impossible_replacement.after_diagnostic_resume = true;
    const auto impossible_candidate = h.Candidate(
        duplicate_candidate.generation, duplicate_candidate.candidate_index,
        0x1, impossible_replacement.writer);
    const PpDepthPredecessorCrossScopeResumeWitness impossible_resume{
        .source_post = impossible_replacement,
        .source_candidate = impossible_candidate,
        .candidate_capacity = 4,
        .resume_guest_rendering_serial = 170,
        .resume_host_rendering_instance_id = 1002,
        .resume_rendering_active = true,
        .resume_diagnostic_origin = true,
        .resume_preserved_guest_serial = true,
        .valid = true,
    };
    const auto no_begin = duplicate.ObserveSourcePostRestartComplete(
        impossible_replacement, impossible_candidate, impossible_resume);
    EXPECT_NE(no_begin.decision,
              PpDepthPredecessorCrossScopePairDecision::Idle);
    EXPECT_EQ(no_begin.source_post_count, 0u);
    EXPECT_FALSE(duplicate.MatchesStoredSourcePost(duplicate_source));

    PpDepthPredecessorCrossScopePairLifecycle older_target{4, 90};
    PpDepthPredecessorEndpointStamp old_source{};
    PpDepthPredecessorCandidateStamp old_candidate{};
    PpDepthPredecessorCrossScopeResumeWitness old_resume{};
    prepare(older_target, old_source, old_candidate, old_resume);
    ASSERT_TRUE(older_target
                    .BeginSourcePostRestart({
                        .stored_source_post = old_source,
                        .stored_source_candidate = old_candidate,
                        .prior_resume = old_resume,
                        .current_source_writer = old_source.writer,
                        .repeated_source_checkpoint = {
                            .guest_rendering_serial = 170,
                            .host_rendering_instance_id = 1001,
                            .rendering_active = true,
                            .diagnostic_origin = true,
                        },
                        .frame_output = h.link,
                        .frame_preview = {
                            .candidate_index = old_candidate.candidate_index,
                            .status = FinalGuestSurfaceStatus::Complete,
                            .capture = true,
                            .restart = true,
                        },
                        .expected_generation = old_candidate.generation,
                        .candidate_capacity = 4,
                        .recorded_plane_mask_before_preview = 0x1,
                        .recorded_plane_mask_after_preview = 0,
                        .retained_slot_present = true,
                    })
                    .source_restart_open);
    auto newest = h.SourceEndpoint(1101, 170, 1001);
    newest.after_diagnostic_resume = true;
    const auto newest_candidate = h.Candidate(
        old_candidate.generation, old_candidate.candidate_index, 0x1,
        newest.writer);
    const PpDepthPredecessorCrossScopeResumeWitness newest_resume{
        .source_post = newest,
        .source_candidate = newest_candidate,
        .candidate_capacity = 4,
        .resume_guest_rendering_serial = 170,
        .resume_host_rendering_instance_id = 1002,
        .resume_rendering_active = true,
        .resume_diagnostic_origin = true,
        .resume_preserved_guest_serial = true,
        .valid = true,
    };
    ASSERT_EQ(older_target
                  .ObserveSourcePostRestartComplete(newest, newest_candidate,
                                                    newest_resume)
                  .role,
              PpDepthPredecessorCrossScopePairRole::TargetPre);
    auto stale_boundary = h.Boundary(old_source, 1100, old_candidate);
    stale_boundary.resume_guest_rendering_serial = 170;
    stale_boundary.resume_host_rendering_instance_id = 1001;
    stale_boundary.target_guest_rendering_serial = 171;
    stale_boundary.target_host_rendering_instance_id = 1002;
    EXPECT_FALSE(older_target.ObserveTargetPre(stale_boundary).boundary_exact)
        << "an older completed S cannot be recovered after replacement";
    EXPECT_FALSE(older_target.CanBeginSourcePostRestart());

    PpDepthPredecessorCrossScopePairLifecycle after_target{4, 100};
    PpDepthPredecessorEndpointStamp target_source{};
    PpDepthPredecessorCandidateStamp target_candidate{};
    PpDepthPredecessorCrossScopeResumeWitness target_resume{};
    prepare(after_target, target_source, target_candidate, target_resume);
    auto target_boundary = h.Boundary(target_source, 1100, target_candidate);
    target_boundary.resume_guest_rendering_serial = 170;
    target_boundary.resume_host_rendering_instance_id = 1001;
    target_boundary.target_guest_rendering_serial = 171;
    target_boundary.target_host_rendering_instance_id = 1002;
    ASSERT_TRUE(after_target.ObserveTargetPre(target_boundary).boundary_exact);
    EXPECT_FALSE(after_target.CanBeginSourcePostRestart());
    auto post_target_attempt =
        PpDepthPredecessorCrossScopeSourceRestartPreObservation{
            .stored_source_post = target_source,
            .stored_source_candidate = target_candidate,
            .prior_resume = target_resume,
            .current_source_writer = target_source.writer,
            .repeated_source_checkpoint = {
                .guest_rendering_serial = 170,
                .host_rendering_instance_id = 1001,
                .rendering_active = true,
                .diagnostic_origin = true,
            },
            .frame_output = h.link,
            .frame_preview = {
                .candidate_index = target_candidate.candidate_index,
                .status = FinalGuestSurfaceStatus::Complete,
                .capture = true,
                .restart = true,
            },
            .expected_generation = target_candidate.generation,
            .candidate_capacity = 4,
            .recorded_plane_mask_before_preview = 0x1,
            .recorded_plane_mask_after_preview = 0,
            .retained_slot_present = true,
            .target_pre_attempted = true,
        };
    const auto closed =
        after_target.BeginSourcePostRestart(post_target_attempt);
    EXPECT_NE(closed.decision,
              PpDepthPredecessorCrossScopePairDecision::Idle);
    EXPECT_FALSE(closed.source_restart_open);
    EXPECT_EQ(closed.source_post_count, 0u);
    EXPECT_FALSE(after_target.MatchesStoredSourcePost(target_source));

    PpDepthPredecessorCrossScopePairLifecycle mismatch_terminal{4, 110};
    PpDepthPredecessorEndpointStamp mismatch_source{};
    PpDepthPredecessorCandidateStamp mismatch_candidate{};
    PpDepthPredecessorCrossScopeResumeWitness mismatch_resume{};
    prepare(mismatch_terminal, mismatch_source, mismatch_candidate,
            mismatch_resume);
    auto mismatched_target =
        h.Boundary(mismatch_source, 1100, mismatch_candidate);
    mismatched_target.resume_guest_rendering_serial = 170;
    mismatched_target.resume_host_rendering_instance_id = 1001;
    mismatched_target.target_guest_rendering_serial = 171;
    mismatched_target.target_host_rendering_instance_id = 1002;
    ++mismatched_target.target_pre_current_writer.mutation_epoch;
    const auto mismatch = mismatch_terminal.ObserveTargetPre(mismatched_target);
    EXPECT_NE(mismatch.decision,
              PpDepthPredecessorCrossScopePairDecision::Idle);
    EXPECT_FALSE(mismatch_terminal.CanBeginSourcePostRestart());
    const auto restart_after_mismatch = mismatch_terminal.BeginSourcePostRestart({
        .stored_source_post = mismatch_source,
        .stored_source_candidate = mismatch_candidate,
        .prior_resume = mismatch_resume,
        .current_source_writer = mismatch_source.writer,
        .repeated_source_checkpoint = {
            .guest_rendering_serial = 170,
            .host_rendering_instance_id = 1001,
            .rendering_active = true,
            .diagnostic_origin = true,
        },
        .frame_output = h.link,
        .frame_preview = {
            .candidate_index = mismatch_candidate.candidate_index,
            .status = FinalGuestSurfaceStatus::Complete,
            .capture = true,
            .restart = true,
        },
        .expected_generation = mismatch_candidate.generation,
        .candidate_capacity = 4,
        .recorded_plane_mask_before_preview = 0x1,
        .recorded_plane_mask_after_preview = 0,
        .retained_slot_present = true,
        .target_pre_attempted = true,
    });
    EXPECT_NE(restart_after_mismatch.decision,
              PpDepthPredecessorCrossScopePairDecision::Idle);
    EXPECT_FALSE(restart_after_mismatch.source_restart_open);
    auto exact_target = h.Boundary(mismatch_source, 1100,
                                   mismatch_candidate);
    exact_target.resume_guest_rendering_serial = 170;
    exact_target.resume_host_rendering_instance_id = 1001;
    exact_target.target_guest_rendering_serial = 171;
    exact_target.target_host_rendering_instance_id = 1002;
    EXPECT_FALSE(mismatch_terminal.ObserveTargetPre(exact_target).boundary_exact)
        << "a first TargetPre mismatch is terminal; a later exact target cannot reopen it";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     BoundaryCheckpointSelectionKeepsLearningSourceAndArmedResumeIndependent) {
    const PpDepthPredecessorCrossScopeRuntimeBoundaryCheckpoints checkpoints{
        .source_pre_transit = {
            .guest_rendering_serial = 900,
            .host_rendering_instance_id = 1100,
            .rendering_active = true,
            .regular_origin = false,
            .diagnostic_origin = true,
        },
        .pre_external_begin = {
            .guest_rendering_serial = 900,
            .host_rendering_instance_id = 1101,
            .rendering_active = false,
            .regular_origin = false,
            .diagnostic_origin = true,
        },
    };

    const auto learning =
        SelectPpDepthPredecessorCrossScopeLearningSourceCheckpoint(checkpoints);
    EXPECT_EQ(learning.guest_rendering_serial, 900u);
    EXPECT_EQ(learning.host_rendering_instance_id, 1100u);
    EXPECT_TRUE(learning.rendering_active);
    EXPECT_FALSE(learning.regular_origin);
    EXPECT_TRUE(learning.diagnostic_origin);

    const auto armed =
        SelectPpDepthPredecessorCrossScopeArmedResumeCheckpoint(checkpoints);
    EXPECT_EQ(armed.guest_rendering_serial, 900u);
    EXPECT_EQ(armed.host_rendering_instance_id, 1101u);
    EXPECT_FALSE(armed.rendering_active)
        << "an ended pre-external scope must not replace the earlier source checkpoint";
    EXPECT_FALSE(armed.regular_origin);
    EXPECT_TRUE(armed.diagnostic_origin);
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     SourceLineageClassifierAcceptsOnlySameHostOrNewerDiagnosticDescendant) {
    using Kind = PpDepthPredecessorCrossScopeSourceLineageKind;
    const auto classify = [](u64 source_guest, u64 source_host,
                             bool source_diagnostic, u64 checkpoint_guest,
                             u64 checkpoint_host, bool checkpoint_active,
                             bool checkpoint_regular,
                             bool checkpoint_diagnostic) {
        return ClassifyPpDepthPredecessorCrossScopeSourceLineage({
            .source_guest_rendering_serial = source_guest,
            .source_host_rendering_instance_id = source_host,
            .source_after_diagnostic_resume = source_diagnostic,
            .checkpoint = {
                .guest_rendering_serial = checkpoint_guest,
                .host_rendering_instance_id = checkpoint_host,
                .rendering_active = checkpoint_active,
                .regular_origin = checkpoint_regular,
                .diagnostic_origin = checkpoint_diagnostic,
            },
        });
    };
    const auto expect_exact = [&](bool source_diagnostic, u64 checkpoint_host,
                                  bool checkpoint_regular,
                                  bool checkpoint_diagnostic, Kind kind) {
        for (const bool active : {false, true}) {
            SCOPED_TRACE(active ? "active" : "ended");
            const auto result = classify(900, 1100, source_diagnostic, 900,
                                         checkpoint_host, active,
                                         checkpoint_regular,
                                         checkpoint_diagnostic);
            EXPECT_TRUE(result.source_identity_nonzero);
            EXPECT_TRUE(result.checkpoint_identity_nonzero);
            EXPECT_TRUE(result.hosts_below_max);
            EXPECT_TRUE(result.guest_exact);
            EXPECT_TRUE(result.origin_one_hot);
            EXPECT_EQ(result.same_host, checkpoint_host == 1100);
            EXPECT_EQ(result.strictly_newer_host, checkpoint_host > 1100);
            EXPECT_EQ(result.kind, kind);
            EXPECT_TRUE(result.exact)
                << "rendering activity is telemetry, not lineage";
        }
    };

    expect_exact(false, 1100, true, false, Kind::SameHost);
    expect_exact(true, 1100, false, true, Kind::SameHost);
    expect_exact(false, 1101, false, true, Kind::DiagnosticDescendant);
    expect_exact(true, 1101, false, true, Kind::DiagnosticDescendant);
    expect_exact(false, 1200, false, true, Kind::DiagnosticDescendant);

    struct Rejected {
        u64 source_guest;
        u64 source_host;
        bool source_diagnostic;
        u64 checkpoint_guest;
        u64 checkpoint_host;
        bool checkpoint_regular;
        bool checkpoint_diagnostic;
    };
    const std::array rejected{
        Rejected{0, 1100, false, 0, 1100, true, false},
        Rejected{900, 1100, false, 0, 1100, true, false},
        Rejected{900, 1100, false, 901, 1100, true, false},
        Rejected{900, 0, false, 900, 1100, true, false},
        Rejected{900, 1100, false, 900, 0, true, false},
        Rejected{900, std::numeric_limits<u64>::max(), false, 900,
                 std::numeric_limits<u64>::max(), true, false},
        Rejected{900, 1100, false, 900,
                 std::numeric_limits<u64>::max(), false, true},
        Rejected{900, std::numeric_limits<u64>::max(), false, 900, 1,
                 false, true},
        Rejected{900, 1100, false, 900, 1099, false, true},
        Rejected{900, 1100, false, 900, 1101, true, false},
        Rejected{900, 1100, false, 900, 1100, false, true},
        Rejected{900, 1100, true, 900, 1100, true, false},
        Rejected{900, 1100, false, 900, 1100, false, false},
        Rejected{900, 1100, false, 900, 1100, true, true},
        Rejected{900, 1100, false, 900, 1101, false, false},
        Rejected{900, 1100, false, 900, 1101, true, true},
    };
    for (u32 index = 0; index < rejected.size(); ++index) {
        const auto& input = rejected[index];
        SCOPED_TRACE(index);
        for (const bool active : {false, true}) {
            const auto result = classify(
                input.source_guest, input.source_host,
                input.source_diagnostic, input.checkpoint_guest,
                input.checkpoint_host, active, input.checkpoint_regular,
                input.checkpoint_diagnostic);
            EXPECT_EQ(result.kind, Kind::None);
            EXPECT_FALSE(result.exact);
        }
    }
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     LearningSourceCheckpointMatchesRegularOrDiagnosticProducerOriginExactly) {
    const CrossScopePairTestHarness h{};
    const auto make = [&](bool source_diagnostic,
                          PpDepthPredecessorCrossScopeRenderingCheckpoint checkpoint) {
        auto source = h.SourceEndpoint(110, 900, 1100);
        source.after_diagnostic_resume = source_diagnostic;
        return BuildPpDepthPredecessorCrossScopeLearningTargetPreBoundary({
            .source_current = source,
            .target_intent = h.Intent(h.p0, 110),
            .predecessor = {
                .recorded = true,
                .depth_stencil_exact = true,
                .same_scope = false,
            },
            .raw_current_link = h.link,
            .raw_current_range = h.range,
            .raw_current_backing_generation = 83,
            .raw_current_mutation_epoch = 110,
            .raw_boundary_active = true,
            .raw_boundary_tracked = true,
            .boundary_before_guest_rendering_serial =
                checkpoint.guest_rendering_serial,
            .boundary_before_host_rendering_instance_id =
                checkpoint.host_rendering_instance_id,
            .boundary_after_guest_rendering_serial = 901,
            .boundary_after_host_rendering_instance_id = 1102,
            .boundary_before_rendering_active = checkpoint.rendering_active,
            .boundary_before_regular_origin = checkpoint.regular_origin,
            .boundary_before_diagnostic_origin = checkpoint.diagnostic_origin,
            .boundary_after_rendering_active = true,
            .boundary_after_regular_origin = true,
            .boundary_after_diagnostic_origin = false,
            .live_target_guest_rendering_serial = 901,
            .live_target_host_rendering_instance_id = 1102,
            .live_target_rendering_active = true,
            .live_target_regular_origin = true,
            .live_target_diagnostic_origin = false,
            .source_outside_target_guest_scope = true,
            .after_begin_rendering = true,
            .target_depth_load = true,
            .target_depth_clear = false,
            .target_stencil_clear = false,
            .depth_aspect = true,
            .canonical_attachment = true,
        });
    };
    const auto exact_checkpoint = [](bool diagnostic) {
        return PpDepthPredecessorCrossScopeRenderingCheckpoint{
            .guest_rendering_serial = 900,
            .host_rendering_instance_id = 1100,
            .rendering_active = true,
            .regular_origin = !diagnostic,
            .diagnostic_origin = diagnostic,
        };
    };

    for (const bool source_diagnostic : {false, true}) {
        SCOPED_TRACE(source_diagnostic ? "DiagnosticResume source" : "Regular source");
        for (const bool active : {false, true}) {
            auto checkpoint = exact_checkpoint(source_diagnostic);
            checkpoint.rendering_active = active;
            const auto exact = make(source_diagnostic, checkpoint);
            EXPECT_TRUE(exact.boundary_before_source_origin_exact);
            EXPECT_FALSE(
                exact.boundary_before_diagnostic_descendant_exact);
            EXPECT_TRUE(exact.boundary_before_source_lineage_exact);
            EXPECT_EQ(exact.boundary_before_regular_origin_exact,
                      !source_diagnostic)
                << "br remains raw Regular-origin telemetry";
            EXPECT_TRUE(exact.raw_boundary_exact);
            EXPECT_TRUE(exact.exact);
            EXPECT_TRUE(
                PlanPpDepthPredecessorCrossScopeLearningTargetPreAttempt(exact)
                    .observe_cross_scope);

            checkpoint.host_rendering_instance_id = 1101;
            checkpoint.regular_origin = false;
            checkpoint.diagnostic_origin = true;
            const auto descendant = make(source_diagnostic, checkpoint);
            EXPECT_EQ(descendant.boundary_before_source_origin_exact,
                      source_diagnostic);
            EXPECT_TRUE(
                descendant.boundary_before_diagnostic_descendant_exact);
            EXPECT_TRUE(descendant.boundary_before_source_lineage_exact)
                << "a newer DiagnosticResume host preserves either source origin";
            EXPECT_TRUE(descendant.raw_boundary_exact);
            EXPECT_TRUE(descendant.exact);

            checkpoint.regular_origin = true;
            checkpoint.diagnostic_origin = false;
            const auto newer_regular = make(source_diagnostic, checkpoint);
            EXPECT_FALSE(
                newer_regular.boundary_before_diagnostic_descendant_exact);
            EXPECT_FALSE(newer_regular.boundary_before_source_lineage_exact);
            EXPECT_FALSE(newer_regular.raw_boundary_exact);
            EXPECT_FALSE(newer_regular.exact);
        }

        for (u32 structural_mismatch = 0; structural_mismatch < 2;
             ++structural_mismatch) {
            auto checkpoint = exact_checkpoint(source_diagnostic);
            switch (structural_mismatch) {
            case 0:
                ++checkpoint.guest_rendering_serial;
                break;
            case 1:
                --checkpoint.host_rendering_instance_id;
                break;
            default:
                FAIL() << "unhandled source checkpoint mismatch";
            }
            SCOPED_TRACE(structural_mismatch);
            const auto rejected = make(source_diagnostic, checkpoint);
            EXPECT_FALSE(rejected.raw_boundary_exact);
            EXPECT_FALSE(rejected.exact);
        }

        for (const auto [regular_origin, diagnostic_origin] :
             {std::pair{false, false}, std::pair{false, true},
              std::pair{true, false}, std::pair{true, true}}) {
            const bool origin_exact = regular_origin != diagnostic_origin &&
                                      diagnostic_origin == source_diagnostic;
            auto source = h.SourceEndpoint(110, 900, 1100);
            source.after_diagnostic_resume = source_diagnostic;
            auto raw = PpDepthPredecessorCrossScopeLearningTargetPreRuntimeObservation{
                .source_current = source,
                .target_intent = h.Intent(h.p0, 110),
                .predecessor = {
                    .recorded = true,
                    .depth_stencil_exact = true,
                    .same_scope = false,
                },
                .raw_current_link = h.link,
                .raw_current_range = h.range,
                .raw_current_backing_generation = 83,
                .raw_current_mutation_epoch = 110,
                .raw_boundary_active = true,
                .raw_boundary_tracked = true,
                .boundary_before_guest_rendering_serial = 900,
                .boundary_before_host_rendering_instance_id = 1100,
                .boundary_after_guest_rendering_serial = 901,
                .boundary_after_host_rendering_instance_id = 1102,
                .boundary_before_rendering_active = true,
                .boundary_before_regular_origin = regular_origin,
                .boundary_before_diagnostic_origin = diagnostic_origin,
                .boundary_after_rendering_active = true,
                .boundary_after_regular_origin = true,
                .boundary_after_diagnostic_origin = false,
                .live_target_guest_rendering_serial = 901,
                .live_target_host_rendering_instance_id = 1102,
                .live_target_rendering_active = true,
                .live_target_regular_origin = true,
                .live_target_diagnostic_origin = false,
                .source_outside_target_guest_scope = true,
                .after_begin_rendering = true,
                .target_depth_load = true,
                .target_depth_clear = false,
                .target_stencil_clear = false,
                .depth_aspect = true,
                .canonical_attachment = true,
            };
            const auto classified =
                BuildPpDepthPredecessorCrossScopeLearningTargetPreBoundary(raw);
            SCOPED_TRACE(regular_origin ? "Regular=1" : "Regular=0");
            SCOPED_TRACE(diagnostic_origin ? "Diagnostic=1" : "Diagnostic=0");
            EXPECT_EQ(classified.boundary_before_source_origin_exact, origin_exact);
            EXPECT_FALSE(
                classified.boundary_before_diagnostic_descendant_exact);
            EXPECT_EQ(classified.boundary_before_source_lineage_exact, origin_exact);
            EXPECT_EQ(classified.raw_boundary_exact, origin_exact);
            EXPECT_EQ(classified.exact, origin_exact);
        }
    }
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     LearningTargetPreMapperUsesRawRegularBoundaryFactsWithoutGenericSkippedStateGate) {
    const CrossScopePairTestHarness h{};
    const auto source = h.SourceEndpoint(110, 900, 1100);
    const auto make = [&](u32 mismatch)
        -> PpDepthPredecessorCrossScopeLearningTargetPreRuntimeBoundary {
        auto raw = PpDepthPredecessorCrossScopeLearningTargetPreRuntimeObservation{
            .source_current = source,
            .target_intent = h.Intent(h.p0, 110),
            .predecessor = {
                .recorded = true,
                .depth_stencil_exact = true,
                .same_scope = false,
            },
            .raw_current_link = h.link,
            .raw_current_range = h.range,
            .raw_current_backing_generation = 83,
            .raw_current_mutation_epoch = 110,
            .raw_boundary_active = true,
            .raw_boundary_tracked = true,
            .boundary_before_guest_rendering_serial = 900,
            .boundary_before_host_rendering_instance_id = 1100,
            .boundary_after_guest_rendering_serial = 901,
            .boundary_after_host_rendering_instance_id = 1101,
            .boundary_before_rendering_active = true,
            .boundary_before_regular_origin = true,
            .boundary_before_diagnostic_origin = false,
            .boundary_after_rendering_active = true,
            .boundary_after_regular_origin = true,
            .boundary_after_diagnostic_origin = false,
            .live_target_guest_rendering_serial = 901,
            .live_target_host_rendering_instance_id = 1101,
            .live_target_rendering_active = true,
            .live_target_regular_origin = true,
            .live_target_diagnostic_origin = false,
            .source_outside_target_guest_scope = true,
            .after_begin_rendering = true,
            .target_depth_load = true,
            .target_depth_clear = false,
            .target_stencil_clear = false,
            .depth_aspect = true,
            .canonical_attachment = true,
        };
        switch (mismatch) {
        case 0:
            break;
        case 1:
            ++raw.raw_current_link.uid;
            break;
        case 2:
            ++raw.raw_current_range.base.layer;
            break;
        case 3:
            ++raw.raw_current_backing_generation;
            break;
        case 4:
            ++raw.raw_current_mutation_epoch;
            break;
        case 5:
            ++raw.boundary_before_guest_rendering_serial;
            break;
        case 6:
            ++raw.boundary_before_host_rendering_instance_id;
            break;
        case 7:
            raw.boundary_before_rendering_active = false;
            break;
        case 8:
            raw.boundary_before_regular_origin = false;
            break;
        case 9:
            raw.boundary_before_diagnostic_origin = true;
            break;
        case 10:
            raw.boundary_after_guest_rendering_serial =
                raw.boundary_before_guest_rendering_serial;
            break;
        case 11:
            ++raw.boundary_after_guest_rendering_serial;
            break;
        case 12:
            raw.boundary_after_host_rendering_instance_id =
                raw.boundary_before_host_rendering_instance_id;
            break;
        case 13:
            raw.boundary_after_host_rendering_instance_id = 0;
            break;
        case 14:
            raw.boundary_after_rendering_active = false;
            break;
        case 15:
            raw.boundary_after_regular_origin = false;
            break;
        case 16:
            raw.boundary_after_diagnostic_origin = true;
            break;
        case 17:
            raw.source_current.valid = false;
            break;
        case 18:
            raw.predecessor.recorded = false;
            break;
        case 19:
            raw.predecessor.same_scope = true;
            break;
        case 20:
            raw.target_depth_load = false;
            break;
        case 21:
            raw.target_depth_clear = true;
            break;
        case 22:
            raw.target_stencil_clear = true;
            break;
        case 23:
            raw.depth_aspect = false;
            break;
        case 24:
            raw.canonical_attachment = false;
            break;
        case 25:
            raw.source_outside_target_guest_scope = false;
            break;
        case 26:
            raw.after_begin_rendering = false;
            break;
        case 27:
            raw.raw_boundary_active = false;
            break;
        case 28:
            raw.raw_boundary_tracked = false;
            break;
        case 29:
            ++raw.live_target_guest_rendering_serial;
            break;
        case 30:
            ++raw.live_target_host_rendering_instance_id;
            break;
        case 31:
            raw.live_target_rendering_active = false;
            break;
        case 32:
            raw.live_target_regular_origin = false;
            break;
        case 33:
            raw.live_target_diagnostic_origin = true;
            break;
        default:
            ADD_FAILURE() << "unhandled learning runtime boundary mismatch";
        }
        return BuildPpDepthPredecessorCrossScopeLearningTargetPreBoundary(raw);
    };

    const auto exact = make(0);
    ASSERT_TRUE(exact.raw_boundary_exact);
    EXPECT_TRUE(exact.boundary_before_guest_exact);
    EXPECT_TRUE(exact.boundary_before_host_exact);
    EXPECT_TRUE(exact.boundary_before_rendering_active);
    EXPECT_TRUE(exact.boundary_before_regular_origin_exact);
    EXPECT_TRUE(exact.boundary_before_source_origin_exact);
    EXPECT_FALSE(exact.boundary_before_diagnostic_descendant_exact);
    EXPECT_TRUE(exact.boundary_before_source_lineage_exact);
    ASSERT_TRUE(exact.exact);
    const auto exact_attempt =
        PlanPpDepthPredecessorCrossScopeLearningTargetPreAttempt(exact);
    EXPECT_TRUE(exact_attempt.observe_cross_scope);
    EXPECT_FALSE(exact_attempt.reject_shared_feedback);
    EXPECT_TRUE(exact_attempt.continue_nested_multi_hop);
    EXPECT_TRUE(ClassifyPpDepthPredecessorCrossScopeLearningBoundary(exact.observation).exact)
        << "regular G-to-G+1 LOAD is independent of generic skipped-state/barrier context";
    for (u32 mismatch = 1; mismatch < 34; ++mismatch) {
        SCOPED_TRACE(mismatch);
        if (mismatch == 7) {
            EXPECT_TRUE(make(mismatch).exact)
                << "an ended source host retains exact lineage";
        } else {
            EXPECT_FALSE(make(mismatch).exact);
        }
    }

    const auto expect_before = [&](u32 mismatch, std::array<bool, 4> flags) {
        const auto boundary = make(mismatch);
        EXPECT_EQ(boundary.boundary_before_guest_exact, flags[0]);
        EXPECT_EQ(boundary.boundary_before_host_exact, flags[1]);
        EXPECT_EQ(boundary.boundary_before_rendering_active, flags[2]);
        EXPECT_EQ(boundary.boundary_before_regular_origin_exact, flags[3]);
        EXPECT_FALSE(boundary.raw_boundary_exact);
        EXPECT_FALSE(boundary.exact);
        EXPECT_TRUE(
            ClassifyPpDepthPredecessorCrossScopeLearningBoundary(boundary.observation).exact)
            << "before-boundary evidence must not alter the logical G-to-G+1 classifier";
        const auto attempt =
            PlanPpDepthPredecessorCrossScopeLearningTargetPreAttempt(boundary);
        EXPECT_FALSE(attempt.observe_cross_scope)
            << "a raw before mismatch must not advance the lifecycle";
        EXPECT_FALSE(attempt.reject_shared_feedback)
            << "bootstrap diagnostics must not poison the shared mode3 frame";
        EXPECT_TRUE(attempt.continue_nested_multi_hop);
    };
    expect_before(5, {false, true, true, true});
    expect_before(6, {true, false, true, true});
    expect_before(8, {true, true, true, false});
    expect_before(9, {true, true, true, false});
    const auto ended_source = make(7);
    EXPECT_FALSE(ended_source.boundary_before_rendering_active);
    EXPECT_FALSE(
        ended_source.boundary_before_diagnostic_descendant_exact);
    EXPECT_TRUE(ended_source.boundary_before_source_lineage_exact);
    EXPECT_TRUE(ended_source.raw_boundary_exact);
    EXPECT_TRUE(ended_source.exact);
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     LearningRuntimeGuardLeavesLifecycleEligibleForALaterExactAttempt) {
    const CrossScopePairTestHarness h{};
    const auto exact_boundary = [&] {
        return PpDepthPredecessorCrossScopeLearningTargetPreRuntimeBoundary{
            .observation = h.LearningBoundary(h.SourceEndpoint(110, 900, 1100), 110),
            .raw_boundary_exact = true,
            .boundary_before_guest_exact = true,
            .boundary_before_host_exact = true,
            .boundary_before_rendering_active = true,
            .boundary_before_regular_origin_exact = true,
            .boundary_before_source_origin_exact = true,
            .boundary_before_diagnostic_descendant_exact = true,
            .boundary_before_source_lineage_exact = true,
            .raw_join_exact = true,
            .live_target_exact = true,
            .exact = true,
        };
    };

    PpDepthPredecessorCrossScopePairLifecycle lifecycle{4};
    auto result = lifecycle.BeginLearningFrame(h.Mode3Begin(), h.p0, h.p1, h.anchor);
    ASSERT_EQ(result.role, PpDepthPredecessorCrossScopePairRole::TargetPre);
    ASSERT_EQ(result.decision, PpDepthPredecessorCrossScopePairDecision::Idle);

    auto nonexact = exact_boundary();
    nonexact.raw_boundary_exact = false;
    nonexact.boundary_before_guest_exact = false;
    nonexact.exact = false;
    ASSERT_TRUE(
        ClassifyPpDepthPredecessorCrossScopeLearningBoundary(nonexact.observation).exact);
    const auto nonexact_attempt =
        PlanPpDepthPredecessorCrossScopeLearningTargetPreAttempt(nonexact);
    EXPECT_FALSE(nonexact_attempt.observe_cross_scope);
    EXPECT_FALSE(nonexact_attempt.reject_shared_feedback);
    EXPECT_TRUE(nonexact_attempt.continue_nested_multi_hop);

    const PpUpstreamFeedbackPrePostPlan feedback_plan{
        .candidate_capacity = 4,
        .status = FinalGuestSurfaceStatus::Complete,
        .copy = true,
    };
    PpUpstreamFeedbackPrePostFrame feedback{h.p0.draw, 4};
    ASSERT_TRUE(feedback.Arm(h.p0.draw));
    ASSERT_TRUE(feedback.Configure(feedback_plan));
    if (nonexact_attempt.reject_shared_feedback) {
        feedback.Reject(FinalGuestSurfaceStatus::GapLoss, {.gap = 1});
    }
    if (nonexact_attempt.observe_cross_scope) {
        result = lifecycle.ObserveLearningTargetPre(nonexact.observation);
    }
    EXPECT_EQ(result.role, PpDepthPredecessorCrossScopePairRole::TargetPre);
    EXPECT_EQ(result.decision, PpDepthPredecessorCrossScopePairDecision::Idle);
    EXPECT_EQ(result.target_pre_count, 0u);
    EXPECT_FALSE(result.boundary_exact)
        << "a raw nonexact attempt must not poison the learning lifecycle";
    const auto preview = feedback.Preview(h.link, h.p0.draw);
    EXPECT_TRUE(preview.capture);
    EXPECT_EQ(preview.status, FinalGuestSurfaceStatus::Complete);
    EXPECT_FALSE(preview.loss.Any())
        << "the shared mode3 frame must remain usable after a nonexact mode4 attempt";

    const auto exact = exact_boundary();
    const auto exact_attempt =
        PlanPpDepthPredecessorCrossScopeLearningTargetPreAttempt(exact);
    ASSERT_TRUE(exact_attempt.observe_cross_scope);
    ASSERT_FALSE(exact_attempt.reject_shared_feedback);
    ASSERT_TRUE(exact_attempt.continue_nested_multi_hop);
    if (exact_attempt.observe_cross_scope) {
        result = lifecycle.ObserveLearningTargetPre(exact.observation);
    }
    EXPECT_EQ(result.role, PpDepthPredecessorCrossScopePairRole::TargetPre);
    EXPECT_EQ(result.decision, PpDepthPredecessorCrossScopePairDecision::Idle);
    EXPECT_EQ(result.target_pre_count, 1u);
    EXPECT_TRUE(result.boundary_exact)
        << "skipping the nonexact attempt preserves later exact nested-mode3 eligibility";
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     SourcePostPlane0BuildsOnlyAnExactCopyLocalDiagnosticResumeWitness) {
    const CrossScopePairTestHarness h{};
    const auto endpoint = h.SourceEndpoint(90, 700, 900);
    const auto candidate = h.Candidate(41, 2, 0x1, endpoint.writer);
    const auto make = [&](u32 mismatch)
        -> PpDepthPredecessorCrossScopeResumeWitness {
        auto observation = PpDepthPredecessorCrossScopeSourcePostRuntimeObservation{
            .endpoint = endpoint,
            .candidate = candidate,
            .expected_generation = 41,
            .candidate_capacity = 4,
            .resume_guest_rendering_serial = 700,
            .resume_host_rendering_instance_id = 901,
            .after_producer_mark = true,
            .source_plane_copied = true,
            .resume_rendering_active = true,
            .resume_diagnostic_origin = true,
        };
        switch (mismatch) {
        case 0:
            break;
        case 1:
            observation.after_producer_mark = false;
            break;
        case 2:
            observation.source_plane_copied = false;
            break;
        case 3:
            observation.endpoint.valid = false;
            break;
        case 4:
            observation.endpoint.producer_marked = false;
            break;
        case 5:
            observation.endpoint.writer.hint.valid = false;
            break;
        case 6:
            observation.candidate.valid = false;
            break;
        case 7:
            --observation.candidate.generation;
            break;
        case 8:
            observation.candidate.candidate_index = observation.candidate_capacity;
            break;
        case 9:
            observation.candidate.recorded_plane_mask = 0x3;
            break;
        case 10:
            ++observation.candidate.writer.mutation_epoch;
            break;
        case 11:
            observation.expected_generation = 0;
            break;
        case 12:
            observation.candidate_capacity = 0;
            break;
        case 13:
            observation.candidate_capacity =
                PpUpstreamFeedbackPrePostPlan::MaxCandidates + 1;
            break;
        case 14:
            observation.resume_guest_rendering_serial = 0;
            break;
        case 15:
            ++observation.resume_guest_rendering_serial;
            break;
        case 16:
            observation.resume_host_rendering_instance_id = 0;
            break;
        case 17:
            observation.resume_host_rendering_instance_id =
                observation.endpoint.host_rendering_instance_id;
            break;
        case 18:
            observation.resume_rendering_active = false;
            break;
        case 19:
            observation.resume_diagnostic_origin = false;
            break;
        default:
            ADD_FAILURE() << "unhandled source-post runtime mismatch";
        }
        return BuildPpDepthPredecessorCrossScopeResumeWitness(observation);
    };

    const auto exact = make(0);
    ASSERT_TRUE(exact.valid);
    EXPECT_EQ(exact.source_post, endpoint);
    EXPECT_EQ(exact.source_candidate, candidate);
    EXPECT_EQ(exact.resume_guest_rendering_serial, 700u);
    EXPECT_EQ(exact.resume_host_rendering_instance_id, 901u);
    EXPECT_TRUE(exact.resume_rendering_active);
    EXPECT_TRUE(exact.resume_diagnostic_origin);
    EXPECT_TRUE(exact.resume_preserved_guest_serial);

    auto resumed_source = PpDepthPredecessorCrossScopeSourcePostRuntimeObservation{
        .endpoint = endpoint,
        .candidate = candidate,
        .expected_generation = 41,
        .candidate_capacity = 4,
        .resume_guest_rendering_serial = 700,
        .resume_host_rendering_instance_id = 901,
        .after_producer_mark = true,
        .source_plane_copied = true,
        .resume_rendering_active = true,
        .resume_diagnostic_origin = true,
    };
    resumed_source.endpoint.after_diagnostic_resume = true;
    EXPECT_TRUE(BuildPpDepthPredecessorCrossScopeResumeWitness(resumed_source).valid)
        << "the source producer's inherited diagnostic origin is distinct from the new "
           "post-copy resume witness";
    resumed_source.resume_diagnostic_origin = false;
    EXPECT_FALSE(BuildPpDepthPredecessorCrossScopeResumeWitness(resumed_source).valid)
        << "the source origin cannot substitute for the required copy-local resume witness";
    for (u32 mismatch = 1; mismatch < 20; ++mismatch) {
        SCOPED_TRACE(mismatch);
        EXPECT_FALSE(make(mismatch).valid);
    }
}

TEST(PpDepthPredecessorCrossScopePairRuntime,
     LearningEvidenceSnapshotsOnlyTheLatestExactAttempt) {
    const CrossScopePairTestHarness h{};
    const auto exact_boundary = [&] {
        return PpDepthPredecessorCrossScopeLearningTargetPreRuntimeBoundary{
            .observation = h.LearningBoundary(h.SourceEndpoint(110, 900, 1100), 110),
            .raw_boundary_exact = true,
            .boundary_before_guest_exact = true,
            .boundary_before_host_exact = true,
            .boundary_before_rendering_active = true,
            .boundary_before_regular_origin_exact = true,
            .boundary_before_source_origin_exact = true,
            .boundary_before_diagnostic_descendant_exact = true,
            .boundary_before_source_lineage_exact = true,
            .raw_join_exact = true,
            .live_target_exact = true,
            .exact = true,
        };
    };
    const auto expect = [](const PpDepthPredecessorCrossScopeLearningEvidence& evidence,
                           std::array<bool, 14> flags) {
        EXPECT_EQ(evidence.raw_boundary_exact, flags[0]);
        EXPECT_EQ(evidence.boundary_before_guest_exact, flags[1]);
        EXPECT_EQ(evidence.boundary_before_host_exact, flags[2]);
        EXPECT_EQ(evidence.boundary_before_rendering_active, flags[3]);
        EXPECT_EQ(evidence.boundary_before_regular_origin_exact, flags[4]);
        EXPECT_EQ(evidence.boundary_before_source_origin_exact, flags[5]);
        EXPECT_EQ(evidence.boundary_before_diagnostic_descendant_exact,
                  flags[6]);
        EXPECT_EQ(evidence.boundary_before_source_lineage_exact, flags[7]);
        EXPECT_EQ(evidence.raw_join_exact, flags[8]);
        EXPECT_EQ(evidence.live_target_exact, flags[9]);
        EXPECT_EQ(evidence.predecessor_exact, flags[10]);
        EXPECT_EQ(evidence.join_exact, flags[11]);
        EXPECT_EQ(evidence.regular_cross_scope_exact, flags[12]);
        EXPECT_EQ(evidence.load_exact, flags[13]);
    };

    auto latest = SnapshotPpDepthPredecessorCrossScopeLearningEvidence(exact_boundary());
    expect(latest,
           {true, true, true, true, true, true, true, true, true, true, true, true,
            true, true});

    for (u32 mutation = 0; mutation < 14; ++mutation) {
        auto boundary = exact_boundary();
        switch (mutation) {
        case 0:
            boundary.raw_boundary_exact = false;
            break;
        case 1:
            boundary.boundary_before_guest_exact = false;
            break;
        case 2:
            boundary.boundary_before_host_exact = false;
            break;
        case 3:
            boundary.boundary_before_rendering_active = false;
            break;
        case 4:
            boundary.boundary_before_regular_origin_exact = false;
            break;
        case 5:
            boundary.boundary_before_source_origin_exact = false;
            break;
        case 6:
            boundary.boundary_before_diagnostic_descendant_exact = false;
            break;
        case 7:
            boundary.boundary_before_source_lineage_exact = false;
            break;
        case 8:
            boundary.raw_join_exact = false;
            break;
        case 9:
            boundary.live_target_exact = false;
            break;
        case 10:
            boundary.observation.predecessor.recorded = false;
            break;
        case 11:
            ++boundary.observation.target_intent.link.uid;
            break;
        case 12:
            boundary.observation.source_outside_target_guest_scope = false;
            break;
        case 13:
            boundary.observation.target_depth_load = false;
            break;
        default:
            FAIL() << "unhandled learning evidence mutation";
        }
        latest = SnapshotPpDepthPredecessorCrossScopeLearningEvidence(boundary);
        std::array<bool, 14> expected{true, true, true, true, true, true, true,
                                     true, true, true, true, true, true, true};
        expected[mutation] = false;
        expect(latest, expected);
    }

    latest = SnapshotPpDepthPredecessorCrossScopeLearningEvidence(exact_boundary());
    SCOPED_TRACE("a later exact attempt replaces the previous mutation snapshot");
    expect(latest,
           {true, true, true, true, true, true, true, true, true, true, true, true,
            true, true});
}

