        case 11: seed.candidate.recorded_plane_mask = 0x1; break;
        case 12: seed.slot.present = false; break;
        case 13: ++seed.slot.generation; break;
        case 14: ++seed.slot.candidate_index; break;
        case 15: ++seed.lifecycle.candidate_index; break;
        default: FAIL() << "unhandled seed mismatch";
