    EXPECT_EQ(invalid_repeat_text.find("4294967295"), std::string::npos);

    const auto reset_repeat_outcome =
        MakePpDepthPredecessorCrossScopeRuntimeOutcome(
            private_result,
            PpDepthPredecessorRuntimeFrameDisposition::Publish, true, true,
            learning_evidence, logical_candidates, transition_candidates,
            bootstrap_evidence, armed_target_pre_evidence,
            source_restart_evidence, selected_latest_evidence,
            root_binding_evidence, first_tail_pre_drift_evidence,
            PpDepthPredecessorCrossScopeArmedP0RepeatProbeEvidenceSummary{});
