    EXPECT_NE(malformed_repeat_text.find(reset_repeat_tuple),
              std::string::npos)
        << "unbounded private repeat counts sanitize the whole tuple to zero";
    EXPECT_EQ(malformed_repeat_text.find("4294967295"),
              std::string::npos);

    for (u32 mismatch = 0; mismatch < 3; ++mismatch) {
        auto malformed_repeat_budget = armed_p0_repeat_probe_evidence;
        switch (mismatch) {
        case 0:
            malformed_repeat_budget.unique_evidence.expected_repeat_count = 0;
            break;
        case 1:
            ++malformed_repeat_budget.unique_evidence.attempt_count;
            break;
        case 2:
            ++malformed_repeat_budget.unique_evidence.completion_count;
            break;
        default: FAIL() << "unhandled malformed repeat budget";
        }
        const auto malformed_repeat_budget_text =
            FormatPpDepthPredecessorCrossScopeRuntimeOutcome(
                MakePpDepthPredecessorCrossScopeRuntimeOutcome(
                    private_result,
                    PpDepthPredecessorRuntimeFrameDisposition::Publish,
                    true, true, learning_evidence, logical_candidates,
                    transition_candidates, bootstrap_evidence,
                    armed_target_pre_evidence, source_restart_evidence,
                    selected_latest_evidence, root_binding_evidence,
                    first_tail_pre_drift_evidence,
                    malformed_repeat_budget));
        SCOPED_TRACE(mismatch);
        EXPECT_NE(malformed_repeat_budget_text.find(reset_repeat_tuple),
                  std::string::npos)
            << "an invalid repeat budget sanitizes the whole tuple";
    }

    auto malformed_repeat_multiplicity = armed_p0_repeat_probe_evidence;
