        EXPECT_EQ(report.loss.invalidation, 1u);
        EXPECT_EQ(report.predecessor_first_failure, predecessor_failure);
        EXPECT_EQ(report.target_first_failure, target_failure);
        EXPECT_EQ(report.generic_route_unarmed_count, generic_route_count);
        EXPECT_EQ(report.generic_rejection_count, generic_rejection_count);
        EXPECT_EQ(report.ordinal_admission_count, ordinal_count);
        EXPECT_EQ(report.ordering_exact_count, ordering_count);
        EXPECT_FALSE(report.retains_private_state);
