    // compatibility Bind wrapper must never be the live diagnostic path.
    const auto direct_evaluation =
        EvaluatePpUpstreamSampleTeeProducerPreDepthOrdinalContentToDirectSelected(
            direct_descriptor);
    const auto& direct = direct_evaluation.binding;
    EXPECT_EQ(direct_evaluation.first_failure,
              DirectSelectedFirstFailure::Exact);
    EXPECT_EQ(BindPpUpstreamSampleTeeProducerPreDepthOrdinalContentToDirectSelected(
                  direct_descriptor),
              direct_evaluation.binding)
        << "The compatibility binder exposes only the behavior-authoritative binding";
    EXPECT_EQ(direct.status, FinalGuestSurfaceStatus::Complete);
    EXPECT_FALSE(direct.loss.Any());
    EXPECT_TRUE(direct.exact);
    EXPECT_TRUE(direct.publish_predecessor_pre);
    EXPECT_TRUE(direct.publish_target_pre);
    EXPECT_FALSE(direct.predecessor_post_equals_fresh_predecessor);
    EXPECT_FALSE(direct.target_pre_post_equals_fresh_target);
