    EXPECT_TRUE(direct.direct_selected_same_frame_exact);
    EXPECT_TRUE(direct.predecessor_post_equals_target_immediate_predecessor);
    EXPECT_TRUE(direct.target_post_equals_direct_selected);
    EXPECT_TRUE(direct.generic_nonadmission_exact);
    EXPECT_TRUE(direct.ordinal_pair_exact);
    EXPECT_TRUE(direct.semantic_layout_exact);
    EXPECT_FALSE(direct.consumes_scope_entry);
    EXPECT_FALSE(direct.affects_pds);
    EXPECT_EQ(direct.existing_gpu_copy_count, 2u);
    EXPECT_EQ(direct.existing_token_count, 1u);
    EXPECT_EQ(direct.existing_download_invalidation_count, 1u);
    EXPECT_EQ(direct.existing_release_count, 1u);
    EXPECT_EQ(direct.additional_gpu_copy_count, 0u);
    EXPECT_EQ(direct.additional_slot_count, 0u);
    EXPECT_EQ(direct.additional_invalidation_count, 0u);
    EXPECT_EQ(direct.additional_release_count, 0u);
