        ASSERT_EQ(report->status, FinalGuestSurfaceStatus::InvalidationLoss);
        ASSERT_EQ(report->loss, FinalGuestSurfaceLoss{.invalidation = 1});
        ASSERT_EQ(report->generic_warmup_count, 1u);
