    const std::vector<DirectPostContinuityCase> direct_post_continuity_cases{
        {
            "guest serial equality",
            [&](auto& value) {
                ++value.target_post.output.guest_rendering_serial;
                refresh_direct_selected(value);
            },
        },
        {
            "predecessor host is not max",
            [](auto& value) {
                value.predecessor_post.output.host_rendering_instance_id =
                    std::numeric_limits<u64>::max();
                value.target_pre_diagnostic_immediate_predecessor =
                    value.predecessor_post.output;
            },
        },
        {
            "target host succeeds predecessor host",
            [&](auto& value) {
                ++value.target_post.output.host_rendering_instance_id;
                refresh_direct_selected(value);
            },
        },
        {
            "predecessor link joins target pre",
            [&](auto& value) {
                ++value.predecessor_pre_intent.link.uid;
                value.predecessor_post.output.writer.link =
                    value.predecessor_pre_intent.link;
                refresh_predecessor_local_chain(value);
            },
        },
        {
            "predecessor backing joins target pre",
            [&](auto& value) {
                ++value.predecessor_pre_intent.backing_generation;
                value.predecessor_post.output.writer.backing_generation =
                    value.predecessor_pre_intent.backing_generation;
                refresh_predecessor_local_chain(value);
            },
        },
        {
            "predecessor mutation joins target pre",
            [&](auto& value) {
                ++value.predecessor_pre_intent.mutation_epoch;
                ++value.predecessor_post.output.writer.mutation_epoch;
                refresh_predecessor_local_chain(value);
            },
        },
    };
